insert into public.cards (id, deck_id, kind, topic, badge, question, passage, answer, wrong, criteria, explanation, source_label, source_page, source_slide, source_url, sort) values
  ('korean-grammar-001', 'korean-grammar', 'choice', '맞춤법의 원리', '한글 맞춤법 제1항', '한글 맞춤법의 표기 대상은?', null, '표준어', array['방언', '모든 입말', '외래어만'], '{}'::text[], '제1항 "한글 맞춤법은 표준어를 소리대로 적되, 어법에 맞도록 함을 원칙으로 한다." 적는 대상은 표준어이고 방언은 제외된다.', '우리말 바로 쓰기', 17, null, null, 0),
  ('korean-grammar-002', 'korean-grammar', 'choice', '맞춤법의 원리', '표준어를 소리대로 적는다', '이 원칙이 따르는 것은?', null, '표음주의', array['표의주의', '형태주의', '어원주의'], '{}'::text[], '소리대로 적는 것은 발음 형태대로 적는 표음주의로, 표음 문자인 한글의 특성을 살려 쓰기의 편의를 도모한다.', '우리말 바로 쓰기', 17, null, null, 1),
  ('korean-grammar-003', 'korean-grammar', 'choice', '맞춤법의 원리', '어법에 맞도록 적는다', '이 원칙의 목적은?', null, '단어 뜻을 쉽게 파악', array['발음대로 적기', '쓰기를 쉽게', '외래어 통일'], '{}'::text[], '어법에 맞도록 적는 것은 각 형태소의 본 모양을 밝혀 적어 단어의 뜻을 쉽게 파악하게 하려는 것(표의주의·형태주의)이다.', '우리말 바로 쓰기', 17, null, null, 2),
  ('korean-grammar-004', 'korean-grammar', 'choice', '맞춤법의 원리', '넓고 [널꼬] · 찾으래 [차즈래] · 얼음 [어름]', '이렇게 적는 원리는?', null, '어법에 맞도록', array['소리대로', '두음 법칙', '사이시옷 표기'], '{}'::text[], '소리 나는 대로 적으면 뜻을 파악하기 어려워 어간 형태를 고정해 원형을 밝혀 적는다. 어법에 맞도록 적는 원리다.', '우리말 바로 쓰기', 22, null, null, 3),
  ('korean-grammar-005', 'korean-grammar', 'choice', '맞춤법의 원리', '거위 · 바다 · 구름 · 설거지', '이렇게 적는 원리는?', null, '소리대로', array['어법에 맞도록', '구개음화', '두음 법칙'], '{}'::text[], '형태소가 나뉘지 않거나 원형과 상관없이 발음대로 적는 단어로, 소리대로 적는 원리를 따른다.', '우리말 바로 쓰기', 22, null, null, 4),
  ('korean-grammar-006', 'korean-grammar', 'choice', '맞춤법의 원리', '믿음 · 지붕 · 낚시 · 놓다 · 늦잠', '표기 원칙이 다른 하나는?', null, '지붕', array['믿음', '낚시', '놓다'], '{}'::text[], '지붕은 집+웅이지만 원형을 밝히지 않고 소리대로 적는다. 믿음·낚시·놓다·늦잠은 원형을 밝혀 어법에 맞도록 적었다.', '우리말 바로 쓰기', 24, null, null, 5),
  ('korean-grammar-007', 'korean-grammar', 'choice', '맞춤법의 원리', '빛 · 날다 · 오리 · 하늘 · 푸르다', '적용된 원리가 다른 하나는?', null, '빛', array['날다', '오리', '하늘'], '{}'::text[], '빛은 [빋]·[비치]·[빈만]처럼 환경에 따라 달리 발음되지만 형태를 고정해 어법에 맞도록 적는다. 나머지는 소리대로 적는다.', '우리말 바로 쓰기', 28, null, null, 6),
  ('korean-grammar-008', 'korean-grammar', 'choice', '맞춤법의 원리', '빛 → [빋] [비치] [빈만]', '소리대로만 적으면 생기는 문제는?', null, '한 단어가 여러 형태로', array['받침을 못 씀', '띄어쓰기가 어려워짐', '표준어가 사라짐'], '{}'::text[], '소리대로만 적으면 한 단어가 환경에 따라 여러 형태로 적혀 뜻을 파악하기 어렵다. 그래서 어법에 맞도록 적는 원칙을 붙였다.', '우리말 바로 쓰기', 24, null, null, 7),
  ('korean-grammar-009', 'korean-grammar', 'choice', '맞춤법의 원리', '꽃이다? 꼬치다? 꼿이다?', '맞춤법을 정한 까닭은?', null, '의사소통 혼란을 막으려고', array['방언을 보존하려고', '외래어를 막으려고', '발음을 바꾸려고'], '{}'::text[], '사람마다 다르게 적으면 의사소통이 제대로 되지 않으므로, 우리말을 한글로 적을 때 지킬 약속으로 한글 맞춤법을 정했다.', '우리말 바로 쓰기', 28, null, null, 8),
  ('korean-grammar-010', 'korean-grammar', 'choice', '맞춤법의 원리', '한글 맞춤법 제2항', '띄어쓰기의 기본 단위는?', null, '단어', array['음절', '형태소', '문장'], '{}'::text[], '제2항 "문장의 각 단어는 띄어 씀을 원칙으로 한다." 독립적으로 쓰이는 말의 단위인 단어를 기준으로 띄어 쓴다.', '우리말 바로 쓰기', 19, null, null, 9),
  ('korean-grammar-011', 'korean-grammar', 'choice', '맞춤법의 원리', '형태소 원형을 밝혀 적기', '이 방식에 대한 설명으로 옳지 않은 것은?', null, '뜻을 파악하기 어렵다', array['가독성을 높인다', '표의주의다', '어법에 맞게 적기다'], '{}'::text[], '형태소의 원형을 밝혀 적으면 뜻을 얼른 파악하기 쉽다. 뜻을 파악하기 어렵다는 것은 반대 설명이다.', '우리말 바로 쓰기', 24, null, null, 10),
  ('korean-grammar-012', 'korean-grammar', 'choice', '맞춤법의 원리', '앉고 · 앉으니 · 앉아서', '이렇게 적는 까닭은?', null, '어간 앉-을 고정', array['소리 나는 대로', '된소리 표기', '두음 법칙'], '{}'::text[], '[안꼬], [안즈니], [안자서]로 소리 나도 어간 앉-의 형태를 밝혀 적는다. 어법에 맞도록 적는 원리다.', '우리말 바로 쓰기', 28, null, null, 11),
  ('korean-grammar-013', 'korean-grammar', 'choice', '소리에 관한 것', '소쩍새 · 어깨 · 오빠 · 기쁘다', '된소리로 적는 까닭은?', null, '두 모음 사이 된소리', array['ㄱ·ㅂ 받침 뒤 된소리', '사이시옷 때문', '두음 법칙 때문'], '{}'::text[], '제5항: 한 단어 안에서 뚜렷한 까닭 없이 나는 된소리는 된소리로 적는다. 두 모음 사이에서 나는 된소리가 그 하나다.', '우리말 바로 쓰기', 17, null, null, 12),
  ('korean-grammar-014', 'korean-grammar', 'choice', '소리에 관한 것', '산뜻하다 · 잔뜩 · 살짝 · 엉뚱하다', '된소리로 적는 까닭은?', null, 'ㄴ·ㄹ·ㅁ·ㅇ 받침 뒤', array['두 모음 사이', 'ㄱ·ㅂ 받침 뒤', '어원이 분명해서'], '{}'::text[], '제5항 2: ㄴ·ㄹ·ㅁ·ㅇ 받침 뒤에서 뚜렷한 까닭 없이 나는 된소리는 다음 음절 첫소리를 된소리로 적는다.', '우리말 바로 쓰기', 17, null, null, 13),
  ('korean-grammar-015', 'korean-grammar', 'choice', '소리에 관한 것', '깍두기 · 국수 · 접시 · 싹둑', '된소리로 적지 않는 까닭은?', null, 'ㄱ·ㅂ 뒤 필연적 된소리', array['표준어가 아니라서', '두 모음 사이라서', '한자어라서'], '{}'::text[], 'ㄱ·ㅂ 받침 뒤에서는 필연적으로 된소리가 나므로 일반적 음운 변동으로 설명된다. 그래서 원래 형태대로 적는다.', '우리말 바로 쓰기', 22, null, null, 14),
  ('korean-grammar-016', 'korean-grammar', 'choice', '소리에 관한 것', '딱딱 · 쌉쌀하다 · 씁쓸하다', 'ㄱ·ㅂ 받침 뒤인데 된소리로 적는 까닭은?', null, '같은·비슷한 음절 겹침', array['두 모음 사이', '뜻을 구별하려고', '사이시옷 때문'], '{}'::text[], '제5항 다만: ㄱ·ㅂ 받침 뒤 된소리는 같은 음절이나 비슷한 음절이 겹쳐 나는 경우가 아니면 된소리로 적지 않는다.', '우리말 바로 쓰기', 25, null, null, 15),
  ('korean-grammar-017', 'korean-grammar', 'choice', '소리에 관한 것', '큰집에서 음식을 ___ 먹었다.', '빈칸의 바른 표기는?', null, '잔뜩', array['잔득', '짠뜩', '잔뚝'], '{}'::text[], '잔뜩은 ㄴ 받침 뒤에서 뚜렷한 까닭 없이 된소리가 나므로 된소리로 적는다(제5항).', '우리말 바로 쓰기', 25, null, null, 16),
  ('korean-grammar-018', 'korean-grammar', 'choice', '소리에 관한 것', '쉬는 시간에는 교실이 ___하다.', '빈칸의 바른 표기는?', null, '시끌벅적', array['시끌벅쩍', '시끌뻑적', '시끌벅작'], '{}'::text[], 'ㄱ 받침 뒤에서 필연적으로 나는 된소리는 된소리로 적지 않는다. 그래서 시끌벅적으로 적는다.', '우리말 바로 쓰기', 25, null, null, 17),
  ('korean-grammar-019', 'korean-grammar', 'choice', '소리에 관한 것', '이번 겨울에 담근 ___가 잘 익었다.', '빈칸의 바른 표기는?', null, '깍두기', array['깍뚜기', '깎두기', '깍둑이'], '{}'::text[], '[깍뚜기]로 소리 나지만 ㄱ 받침 뒤 필연적 된소리이므로 깍두기로 적는다.', '우리말 바로 쓰기', 25, null, null, 18),
  ('korean-grammar-020', 'korean-grammar', 'choice', '소리에 관한 것', '날씨가 더워 머리를 ___ 잘랐다.', '빈칸의 바른 표기는?', null, '싹둑', array['싹뚝', '삭둑', '싹똑'], '{}'::text[], '싹둑[싹뚝]은 ㄱ 받침 뒤 필연적 된소리라 된소리로 적지 않는다.', '우리말 바로 쓰기', 22, null, null, 19),
  ('korean-grammar-021', 'korean-grammar', 'choice', '소리에 관한 것', '맏이 · 해돋이 · 굳이 · 같이', '구개음화가 일어나도 원형을 적는 까닭은?', null, '형태소 원형을 밝힘', array['두음 법칙', '소리대로 적음', '사이시옷 표기'], '{}'::text[], '제6항(구개음화): ㄷ·ㅌ 받침 뒤에 종속적 관계의 -이(-)나 -히-가 올 때 ㅈ·ㅊ으로 소리 나도 ㄷ·ㅌ으로 적는다.', '우리말 바로 쓰기', 17, null, null, 20),
  ('korean-grammar-022', 'korean-grammar', 'choice', '소리에 관한 것', '닫히다 [다치다] · 붙이다 [부치다]', '이 발음에 나타난 음운 현상은?', null, '구개음화', array['두음 법칙', '된소리되기', '사이시옷'], '{}'::text[], 'ㄷ·ㅌ이 -이(-)·-히-와 만나 ㅈ·ㅊ으로 소리 나는 현상은 구개음화다. 표기는 원형대로 ㄷ·ㅌ으로 한다.', '우리말 바로 쓰기', 17, null, null, 21),
  ('korean-grammar-023', 'korean-grammar', 'choice', '소리에 관한 것', '제6항의 ‘종속적 관계’', '이것이 뜻하는 결합은?', null, '실질 형태소+형식 형태소', array['실질+실질 형태소', '조사+조사', '어미+어미'], '{}'::text[], '종속적 관계란 체언·어근·용언 어간 같은 실질 형태소에 조사·접미사·어미 같은 형식 형태소가 결합하는 관계다.', '우리말 바로 쓰기', 17, null, null, 22),
  ('korean-grammar-024', 'korean-grammar', 'choice', '소리에 관한 것', '女子 (단어 첫머리)', '두음 법칙에 맞는 표기는?', null, '여자', array['녀자', '니자', '너자'], '{}'::text[], '제10항: 한자음 녀·뇨·뉴·니가 단어 첫머리에 올 때는 두음 법칙에 따라 여·요·유·이로 적는다.', '우리말 바로 쓰기', 17, null, null, 23),
  ('korean-grammar-025', 'korean-grammar', 'choice', '소리에 관한 것', '歷史 (단어 첫머리)', '두음 법칙에 맞는 표기는?', null, '역사', array['력사', '녁사', '엮사'], '{}'::text[], '제11항: 한자음 랴·려·례·료·류·리가 단어 첫머리에 올 때는 야·여·예·요·유·이로 적는다.', '우리말 바로 쓰기', 17, null, null, 24),
  ('korean-grammar-026', 'korean-grammar', 'choice', '소리에 관한 것', '樂園 (단어 첫머리)', '두음 법칙에 맞는 표기는?', null, '낙원', array['락원', '악원', '랔원'], '{}'::text[], '제12항: 한자음 라·래·로·뢰·루·르가 단어 첫머리에 올 때는 나·내·노·뇌·누·느로 적는다.', '우리말 바로 쓰기', 17, null, null, 25),
  ('korean-grammar-027', 'korean-grammar', 'choice', '소리에 관한 것', '여자 · 굳이 · 어깨 · 닫히다 · 똑똑하다', '두음 법칙이 적용된 단어는?', null, '여자', array['굳이', '어깨', '닫히다'], '{}'::text[], '여자(女子)는 녀자의 녀가 첫머리에서 여로 바뀐 두음 법칙 예다. 굳이·닫히다는 구개음화, 어깨는 된소리 표기다.', '우리말 바로 쓰기', 18, null, null, 26),
  ('korean-grammar-028', 'korean-grammar', 'choice', '형태에 관한 것', '“밥 먹었니?” “___, 아직 안 먹었어요.”', '빈칸의 바른 표기는?', null, '아니요', array['아니오', '아니여', '아니유'], '{}'::text[], '묻는 말에 부정으로 대답하는 감탄사는 아니요(준말 아뇨)다. 아니오는 아니다의 활용형으로 서술어로 쓰인다.', '우리말 바로 쓰기', 17, null, null, 27),
  ('korean-grammar-029', 'korean-grammar', 'choice', '형태에 관한 것', '이것은 책이오. / 그것은 책이 아니오.', '이 문장의 ‘-오’는?', null, '종결 어미라 생략 불가', array['조사라 생략 가능', '연결 어미', '접미사'], '{}'::text[], '제15항 붙임: 서술어의 종결 어미 ‘-오’는 단어의 일부라 생략할 수 없다. 독립성 있는 조사 ‘요’는 생략할 수 있다.', '우리말 바로 쓰기', 17, null, null, 28),
  ('korean-grammar-030', 'korean-grammar', 'choice', '형태에 관한 것', '이것은 책이요, 그것은 붓이다.', '여기의 ‘-요’는?', null, '연결 어미', array['종결 어미', '보조사 요', '접미사'], '{}'::text[], '‘이다’, ‘아니다’의 어간 뒤에 붙어 다음 말과 이어 주는 연결 어미는 ‘-요’로 적고 생략할 수 없다.', '우리말 바로 쓰기', 17, null, null, 29),
  ('korean-grammar-031', 'korean-grammar', 'choice', '형태에 관한 것', '높이 · 믿음 · 같이 · 굳이', '이렇게 적는 규정은?', null, '제19항 어간 원형 밝힘', array['제20항 명사 원형', '제5항 된소리', '제30항 사이시옷'], '{}'::text[], '제19항: 어간에 -이·-음/-ㅁ이 붙어 명사가 되거나 -이·-히가 붙어 부사가 된 말은 어간의 원형을 밝혀 적는다.', '우리말 바로 쓰기', 18, null, null, 30),
  ('korean-grammar-032', 'korean-grammar', 'choice', '형태에 관한 것', '귀머거리 · 너머 · 마감 · 무덤', '어간 원형을 밝히지 않는 까닭은?', null, '-이·-음 외 모음 접미사', array['발음이 같아서', '한자어라서', '두음 법칙 때문'], '{}'::text[], '제19항 붙임: 어간에 -이·-음 이외의 모음으로 시작된 접미사가 붙어 다른 품사로 바뀐 것은 원형을 밝혀 적지 않는다.', '우리말 바로 쓰기', 18, null, null, 31),
  ('korean-grammar-033', 'korean-grammar', 'choice', '형태에 관한 것', '마주 · 도로 · 비로소 · 자주', '원형을 밝히지 않은 이 말들의 품사는?', null, '부사', array['명사', '조사', '동사'], '{}'::text[], '맞+우, 돌+오, 비롯+오, 잦+우처럼 -이·-음 외 모음 접미사가 붙어 부사로 바뀐 것은 원형을 밝혀 적지 않는다.', '우리말 바로 쓰기', 18, null, null, 32),
  ('korean-grammar-034', 'korean-grammar', 'choice', '형태에 관한 것', '~나마 · ~부터 · ~조차', '원형을 밝히지 않는 까닭은?', null, '조사로 바뀌어 뜻이 달라짐', array['명사로 바뀜', '두음 법칙', '된소리 표기'], '{}'::text[], '용언에 접미사가 붙어 조사로 바뀌어 뜻이 달라진 것은 원형을 밝혀 적지 않는다(붙다→부터, 좇다→조차).', '우리말 바로 쓰기', 18, null, null, 33),
  ('korean-grammar-035', 'korean-grammar', 'choice', '형태에 관한 것', '산 너머에 있는 마을 (넘- + -어)', '‘넘어’로 적지 않는 까닭은?', null, '-이·-음 외 접미사로 명사화', array['-이가 붙어 명사화', '-음이 붙어 명사화', '합성어라서'], '{}'::text[], '너머는 넘-에 -이·-음 이외의 모음 접미사 -어가 붙어 명사가 되었으므로 원형을 밝히지 않는다.', '우리말 바로 쓰기', 26, null, null, 34),
  ('korean-grammar-036', 'korean-grammar', 'choice', '형태에 관한 것', '먹이 · 높이 · 익히 · 너머', '어간 원형을 밝혀 적지 않은 것은?', null, '너머', array['먹이', '높이', '익히'], '{}'::text[], '먹이·높이·익히는 -이·-히가 붙어 원형을 밝혔다. 너머는 -이·-음 외 접미사가 붙어 소리대로 적는다.', '우리말 바로 쓰기', 26, null, null, 35),
  ('korean-grammar-037', 'korean-grammar', 'choice', '형태에 관한 것', '믿음 · 웃음 · 무덤 · 굳이 · 익히', '형태소 원형을 밝혀 적지 않은 것은?', null, '무덤', array['믿음', '굳이', '익히'], '{}'::text[], '무덤은 묻-에 -엄이 붙은 말로, -이·-음 외 접미사가 붙었으므로 원형을 밝혀 적지 않는다.', '우리말 바로 쓰기', 18, null, null, 36),
  ('korean-grammar-038', 'korean-grammar', 'choice', '형태에 관한 것', '마중 (맞- + -웅)', '원형을 밝혀 적지 않는 까닭은?', null, '-이·-음 외 접미사가 붙음', array['어간 뜻과 멀어짐', '두음 법칙', '된소리가 나서'], '{}'::text[], '마중은 맞-에 -이·-음 이외의 모음 접미사 -웅이 붙은 것이다. 어간 뜻과 멀어졌기 때문이 아니다.', '우리말 바로 쓰기', 29, null, null, 37),
  ('korean-grammar-039', 'korean-grammar', 'choice', '형태에 관한 것', '목거리 (목이 붓고 아픈 병)', '‘목걸이’와 달리 소리대로 적는 까닭은?', null, '어간 뜻과 멀어짐', array['접미사 -웅이 붙음', '사이시옷 때문', '두음 법칙'], '{}'::text[], '제19항 다만: -이·-음이 붙어 명사가 되었더라도 그 어간의 뜻과 멀어진 것은 원형을 밝혀 적지 않는다(목거리, 노름).', '우리말 바로 쓰기', 20, null, null, 38),
  ('korean-grammar-040', 'korean-grammar', 'choice', '형태에 관한 것', '노름판이 벌어졌다. / 즐거운 놀음', '‘노름’을 소리대로 적는 까닭은?', null, '본뜻에서 멀어짐', array['-음 외 접미사', '두음 법칙', '된소리 표기'], '{}'::text[], '노름(도박)은 놀-+-음이지만 본뜻에서 멀어져 소리대로 적는다. 놀음(놀이)은 원형을 밝혀 적는다.', '우리말 바로 쓰기', 20, null, null, 39),
  ('korean-grammar-041', 'korean-grammar', 'choice', '형태에 관한 것', '곳곳이 · 바둑이 · 삼발이 · 절뚝발이', '이렇게 적는 규정은?', null, '명사 뒤 -이, 명사 원형', array['어간 뒤 -이, 어간 원형', '두음 법칙', '사이시옷'], '{}'::text[], '제20항: 명사 뒤에 -이가 붙어서 된 말은 그 명사의 원형을 밝혀 적는다.', '우리말 바로 쓰기', 18, null, null, 40),
  ('korean-grammar-042', 'korean-grammar', 'choice', '형태에 관한 것', '꼬락서니 · 모가지 · 바가지 · 이파리', '명사 원형을 밝히지 않는 까닭은?', null, '-이 외 모음 접미사', array['-이 접미사', '자음 접미사', '어간 뜻과 멀어짐'], '{}'::text[], '제20항 붙임: -이 이외의 모음으로 시작된 접미사가 붙어서 된 말은 명사의 원형을 밝혀 적지 않는다(꼴+악서니, 목+아지).', '우리말 바로 쓰기', 18, null, null, 41),
  ('korean-grammar-043', 'korean-grammar', 'choice', '형태에 관한 것', '꼴 + -악서니', '바른 표기는?', null, '꼬락서니', array['꼴악서니', '꼴악써니', '꼬락써니'], '{}'::text[], '-이 이외의 모음 접미사 -악서니가 붙었으므로 명사 꼴의 원형을 밝히지 않고 꼬락서니로 적는다.', '우리말 바로 쓰기', 29, null, null, 42),
  ('korean-grammar-044', 'korean-grammar', 'choice', '형태에 관한 것', '값지다 · 넋두리 · 빛깔 · 낚시 · 늙정이', '이렇게 적는 규정은?', null, '자음 접미사 앞 원형 밝힘', array['모음 접미사 앞 원형', '사이시옷', '된소리 표기'], '{}'::text[], '제21항: 명사나 용언 어간 뒤에 자음으로 시작된 접미사가 붙어서 된 말은 그 명사나 어간의 원형을 밝혀 적는다.', '우리말 바로 쓰기', 18, null, null, 43),
  ('korean-grammar-045', 'korean-grammar', 'choice', '형태에 관한 것', '넓적하다 vs 널따랗다', '‘널따랗다’를 소리대로 적는 까닭은?', null, '겹받침 끝소리가 안 드러남', array['모음 접미사가 붙음', '두음 법칙', '사이시옷'], '{}'::text[], '제21항 다만: 겹받침의 끝소리가 드러나지 않으면 소리대로 적는다. 넓적하다는 ㅂ이 드러나 원형을 밝혀 적는다.', '우리말 바로 쓰기', 18, null, null, 44),
  ('korean-grammar-046', 'korean-grammar', 'choice', '형태에 관한 것', '곰곰이 · 더욱이 · 생긋이 · 일찍이', '이 말들이 만들어진 방식은?', null, '부사 + -이', array['명사 + -이', '어간 + -이', '-하다 어근 + -히'], '{}'::text[], '제25항 2: 부사에 -이가 붙어서 역시 부사가 되는 경우에는 그 부사의 원형을 밝혀 적는다.', '우리말 바로 쓰기', 18, null, null, 45),
  ('korean-grammar-047', 'korean-grammar', 'choice', '형태에 관한 것', '급히 · 꾸준히 · 딱히 · 깨끗이', '이 말들이 만들어진 방식은?', null, '-하다 어근 + -히/-이', array['부사 + -이', '명사 + -이', '어간 + -음'], '{}'::text[], '제25항 1: -하다가 붙는 어근에 -히나 -이가 붙어서 부사가 되면 그 어근의 원형을 밝혀 적는다.', '우리말 바로 쓰기', 18, null, null, 46),
  ('korean-grammar-048', 'korean-grammar', 'choice', '형태에 관한 것', '꽃잎 · 물난리 · 헛웃음 · 빗나가다', '원형을 밝혀 적는 까닭은?', null, '단어·접두사가 결합', array['두음 법칙', '된소리 표기', '사이시옷 표기'], '{}'::text[], '제27항: 둘 이상의 단어가 어울리거나 접두사가 붙어서 이루어진 말은 각각 그 원형을 밝혀 적는다.', '우리말 바로 쓰기', 18, null, null, 47),
  ('korean-grammar-049', 'korean-grammar', 'choice', '형태에 관한 것', '골병 · 며칠 · 오라비 · 부리나케', '원형을 밝히지 않는 까닭은?', null, '어원이 분명하지 않음', array['발음이 같아서', '한자어라서', '사이시옷 때문'], '{}'::text[], '제27항 붙임 2: 어원이 분명하지 아니한 것은 원형을 밝혀 적지 아니한다.', '우리말 바로 쓰기', 18, null, null, 48),
  ('korean-grammar-050', 'korean-grammar', 'choice', '형태에 관한 것', '몇 월 며칠 / 오늘이 ___이지?', '바른 표기는?', null, '며칠', array['몇일', '몇칠', '며일'], '{}'::text[], '며칠은 어원이 분명하지 않아 원형을 밝히지 않고 소리대로 적는다. 몇일은 틀린 표기다.', '우리말 바로 쓰기', 18, null, null, 49),
  ('korean-grammar-051', 'korean-grammar', 'choice', '형태에 관한 것', '반짇고리 · 사흗날 · 섣달 · 숟가락', 'ㄷ으로 적는 까닭은?', null, 'ㄹ이 ㄷ 소리로 남', array['사이시옷 대신', '두음 법칙', '된소리 표기'], '{}'::text[], '제29항: 끝소리가 ㄹ인 말과 딴 말이 어울릴 때 ㄹ 소리가 ㄷ 소리로 나는 것은 ㄷ으로 적는다(바느질, 사흘, 설, 술).', '우리말 바로 쓰기', 18, null, null, 50),
  ('korean-grammar-052', 'korean-grammar', 'choice', '형태에 관한 것', '베풀- + -ㅁ', '바른 명사형은?', null, '베풂', array['베품', '베풀음', '베픔'], '{}'::text[], '용언의 어간과 어미는 구별하여 적는다. 어간 베풀-에 명사형 어미 -ㅁ이 붙으면 베풂이다.', '우리말 바로 쓰기', 22, null, null, 51),
  ('korean-grammar-053', 'korean-grammar', 'choice', '형태에 관한 것', '넓- + -으니', '바른 표기는?', null, '넓으니', array['널브니', '넓브니', '널으니'], '{}'::text[], '용언의 어간과 어미는 구별해 적으므로 어간 넓-에 어미 -으니를 붙여 넓으니로 적는다.', '우리말 바로 쓰기', 25, null, null, 52),
  ('korean-grammar-054', 'korean-grammar', 'choice', '형태에 관한 것', '늘어나다 vs 쓰러지다', '‘쓰러지다’를 소리대로 적는 까닭은?', null, '앞말 본뜻에서 멀어짐', array['앞말 본뜻이 유지됨', '접두사가 붙음', '두음 법칙'], '{}'::text[], '두 용언이 어울려 한 용언이 될 때 앞말의 본뜻이 유지되면 원형을 밝히고(늘어나다), 멀어지면 소리대로 적는다(쓰러지다).', '우리말 바로 쓰기', 22, null, null, 53),
  ('korean-grammar-055', 'korean-grammar', 'choice', '형태에 관한 것', '사라지다 · 드러나다 · 쓰러지다', '공통 표기 원리는?', null, '본뜻 멀어져 소리대로', array['본뜻 유지해 원형대로', '사이시옷', '된소리 표기'], '{}'::text[], '살다·들다·쓸다의 본뜻에서 멀어졌으므로 원형을 밝히지 않고 소리 나는 대로 적는다.', '우리말 바로 쓰기', 22, null, null, 54),
  ('korean-grammar-056', 'korean-grammar', 'choice', '형태에 관한 것', '구름이 걷히자 산봉우리가 ___.', '빈칸의 바른 표기는?', null, '드러났다', array['들어났다', '드러낫다', '들어낫다'], '{}'::text[], '드러나다는 앞말 들다의 본뜻에서 멀어졌으므로 소리 나는 대로 적는다.', '우리말 바로 쓰기', 25, null, null, 55),
  ('korean-grammar-057', 'korean-grammar', 'choice', '형태에 관한 것', '사람들이 ___ 광장이 텅 비었다.', '빈칸의 바른 표기는?', null, '흩어지고', array['흐터지고', '흩터지고', '흐더지고'], '{}'::text[], '흩어지다는 앞말 흩다의 본뜻이 유지되므로 원형을 밝혀 적는다.', '우리말 바로 쓰기', 25, null, null, 56),
  ('korean-grammar-058', 'korean-grammar', 'choice', '형태에 관한 것', '나무가 ___ 전신주를 덮쳤다.', '빈칸의 바른 표기는?', null, '쓰러지면서', array['쓸어지면서', '쓸러지면서', '쓰러지며서'], '{}'::text[], '쓰러지다는 쓸다의 본뜻에서 멀어진 말이라 소리 나는 대로 적는다.', '우리말 바로 쓰기', 25, null, null, 57),
  ('korean-grammar-059', 'korean-grammar', 'choice', '형태에 관한 것', '수출이 작년보다 두 배나 ___.', '빈칸의 바른 표기는?', null, '늘어났다', array['느러났다', '늘어낫다', '늘러났다'], '{}'::text[], '늘어나다는 늘다의 본뜻이 유지되므로 원형을 밝혀 적는다.', '우리말 바로 쓰기', 25, null, null, 58),
  ('korean-grammar-060', 'korean-grammar', 'choice', '형태에 관한 것', '틈이 점점 ___ 있었다.', '빈칸의 바른 표기는?', null, '벌어지고', array['버러지고', '벌러지고', '벌어지구'], '{}'::text[], '벌어지다는 벌다(틈이 나다)의 본뜻이 유지되므로 원형을 밝혀 적는다.', '우리말 바로 쓰기', 25, null, null, 59),
  ('korean-grammar-061', 'korean-grammar', 'choice', '사이시옷', '나룻배 · 바닷가 · 햇볕 · 귓밥', '사이시옷을 적는 조건은?', null, '뒷말 첫소리가 된소리', array['ㄴ·ㅁ 앞 ㄴ 덧남', '모음 앞 ㄴㄴ 덧남', '두 음절 한자어'], '{}'::text[], '순우리말 합성어로 앞말이 모음으로 끝나고 뒷말 첫소리가 된소리로 나면 사이시옷을 받치어 적는다.', '우리말 바로 쓰기', 18, null, null, 60),
  ('korean-grammar-062', 'korean-grammar', 'choice', '사이시옷', '아랫니 · 잇몸 · 냇물 · 빗물', '사이시옷을 적는 조건은?', null, 'ㄴ·ㅁ 앞 ㄴ 덧남', array['뒷말이 된소리', '모음 앞 ㄴㄴ 덧남', '앞말이 자음'], '{}'::text[], '뒷말의 첫소리 ㄴ·ㅁ 앞에서 ㄴ 소리가 덧나는 경우 사이시옷을 적는다(아래+니→아랫니[아랜니]).', '우리말 바로 쓰기', 18, null, null, 61),
  ('korean-grammar-063', 'korean-grammar', 'choice', '사이시옷', '뒷일 · 깻잎 · 나뭇잎 · 허드렛일', '사이시옷을 적는 조건은?', null, '모음 앞 ㄴㄴ 덧남', array['ㄴ·ㅁ 앞 ㄴ 덧남', '뒷말이 된소리', '두 음절 한자어'], '{}'::text[], '뒷말의 첫소리 모음 앞에서 ㄴㄴ 소리가 덧나는 경우 사이시옷을 적는다(허드레+일→허드렛일[허드렌닐]).', '우리말 바로 쓰기', 18, null, null, 62),
  ('korean-grammar-064', 'korean-grammar', 'choice', '사이시옷', '곳간 · 셋방 · 숫자 · 찻간 · 툇간 · 횟수', '이 단어들의 공통점은?', null, '사이시옷 쓰는 한자어 6개', array['고유어끼리 합성어', '사이시옷 안 씀', '세 음절 한자어'], '{}'::text[], '한자어에는 사이시옷을 적지 않지만, 두 음절로 된 이 여섯 한자어에만 예외로 사이시옷을 적는다.', '우리말 바로 쓰기', 23, null, null, 63),
  ('korean-grammar-065', 'korean-grammar', 'choice', '사이시옷', '개수(個數) · 초점(焦點) · 전세방', '사이시옷을 적지 않는 까닭은?', null, '한자어로만 됨', array['앞말이 자음으로 끝남', '외래어 결합', '된소리가 안 남'], '{}'::text[], '한자어로만 이루어진 단어는 곳간·셋방·숫자·찻간·툇간·횟수를 빼고 사이시옷을 적지 않는다.', '우리말 바로 쓰기', 23, null, null, 64),
  ('korean-grammar-066', 'korean-grammar', 'choice', '사이시옷', '핑크빛 · 피자집', '사이시옷을 적지 않는 까닭은?', null, '외래어가 결합함', array['한자어라서', '된소리가 안 남', '앞말이 자음'], '{}'::text[], '고유어와 외래어가 결합한 경우에는 사이시옷을 적지 않는다.', '우리말 바로 쓰기', 23, null, null, 65),
  ('korean-grammar-067', 'korean-grammar', 'choice', '사이시옷', '꽃 + 사슴 → 꽃사슴', '사이시옷을 쓰지 않는 까닭은?', null, '앞말이 자음으로 끝남', array['고유어가 없음', '한자어라서', '외래어 결합'], '{}'::text[], '꽃은 받침으로 끝나므로 사이시옷을 더 적지 않는다. 뒷말의 첫소리가 된소리로 난다는 이유만으로 사이시옷을 적는 것은 아니다.', '우리말 바로 쓰기', 27, null, null, 66),
  ('korean-grammar-068', 'korean-grammar', 'choice', '사이시옷', '장마 + 비 → 장맛비 [장마삐]', '해당하는 사이시옷 조건은?', null, '뒷말 첫소리 된소리', array['ㄴ·ㅁ 앞 ㄴ 덧남', '모음 앞 ㄴㄴ 덧남', '한자어 예외'], '{}'::text[], '장맛비는 뒷말 비의 첫소리가 된소리[삐]로 바뀌는 경우다. ㄴ 소리가 덧나는 경우가 아니다.', '우리말 바로 쓰기', 27, null, null, 67),
  ('korean-grammar-069', 'korean-grammar', 'choice', '사이시옷', '나무 + 잎', '바른 표기는?', null, '나뭇잎', array['나무잎', '나문잎', '나뭇닢'], '{}'::text[], '나무+잎은 모음 앞에서 ㄴㄴ 소리가 덧나므로[나문닙] 사이시옷을 받쳐 나뭇잎으로 적는다.', '우리말 바로 쓰기', 27, null, null, 68),
  ('korean-grammar-070', 'korean-grammar', 'choice', '사이시옷', '교차(交叉) + 점(點)', '사이시옷을 쓰지 않는 까닭은?', null, '고유어가 없음', array['앞말이 자음', '된소리가 안 남', '외래어 결합'], '{}'::text[], '사이시옷은 결합한 두 명사 중 하나 이상이 고유어여야 한다. 교차점은 한자어끼리라 사이시옷을 쓰지 않는다.', '우리말 바로 쓰기', 27, null, null, 69),
  ('korean-grammar-071', 'korean-grammar', 'choice', '사이시옷', '냇물 · 잇몸 · 빗물 · 제삿날', '단어 구성이 다른 하나는?', null, '제삿날', array['냇물', '잇몸', '빗물'], '{}'::text[], '제삿날은 한자어 제사(祭祀)와 고유어 날의 합성어다. 나머지는 순우리말끼리의 합성어다.', '우리말 바로 쓰기', 19, null, null, 70),
  ('korean-grammar-072', 'korean-grammar', 'choice', '사이시옷', '만두 + 국 [만두꾹]', '바른 표기는?', null, '만둣국', array['만두국', '만둔국', '만둣꾹'], '{}'::text[], '뒷말의 첫소리가 된소리로 나므로 사이시옷을 받쳐 만둣국으로 적는다.', '우리말 바로 쓰기', 18, null, null, 71),
  ('korean-grammar-073', 'korean-grammar', 'choice', '사이시옷', '후일(後日) + 담(譚)', '바른 표기는?', null, '후일담', array['훗일담', '후잇담', '훗날담'], '{}'::text[], '후일담은 한자어로만 된 말이라 사이시옷을 적지 않는다.', '우리말 바로 쓰기', 18, null, null, 72),
  ('korean-grammar-074', 'korean-grammar', 'choice', '사이시옷', '한자어로만 된 단어', '사이시옷 표기 원칙은?', null, '6개 외엔 안 씀', array['항상 씀', '된소리 나면 씀', '두 음절이면 씀'], '{}'::text[], '한자어로만 된 단어에는 원칙적으로 사이시옷을 쓰지 않고, 곳간·셋방·숫자·찻간·툇간·횟수만 예외다.', '우리말 바로 쓰기', 19, null, null, 73),
  ('korean-grammar-075', 'korean-grammar', 'choice', '사이시옷', '고유어+한자어인 사이시옷 표기', '표기 조건을 모두 충족하는 예는?', null, '귓병 · 찻잔 · 훗일', array['곳간 · 셋방', '핑크빛 · 피자집', '개수 · 초점'], '{}'::text[], '고유어와 한자어가 결합한 합성어이면서 앞말이 모음으로 끝나고, 뒷말의 된소리나 ㄴ 소리 덧남 등 발음 조건을 충족해야 한다. 모음으로 끝난다는 조건만으로는 부족하다.', '우리말 바로 쓰기', 18, null, null, 74),
  ('korean-grammar-076', 'korean-grammar', 'choice', '준말', '보이어 → 뵈어, ( ? )', '또 하나의 준말은?', null, '보여', array['뵈여', '봬여', '보어'], '{}'::text[], '제38항: ㅏ·ㅗ·ㅜ·ㅡ 뒤에 -이어가 어울려 줄어질 때는 준 대로 적는다(보이어→뵈어/보여).', '우리말 바로 쓰기', 19, null, null, 75),
  ('korean-grammar-077', 'korean-grammar', 'choice', '준말', '싸이어 → ( ? ), 싸여', '또 하나의 준말은?', null, '쌔어', array['싸여어', '쌔여', '싸어'], '{}'::text[], '제38항에 따라 싸이어는 쌔어, 싸여 두 가지로 줄여 적을 수 있다.', '우리말 바로 쓰기', 19, null, null, 76),
  ('korean-grammar-078', 'korean-grammar', 'choice', '준말', '그렇지 않은', '준말의 바른 표기는?', null, '그렇잖은', array['그렇찮은', '그러잖은', '그렇쟎은'], '{}'::text[], '제39항: 어미 -지 뒤에 않-이 어울려 -잖-이 될 때는 준 대로 적는다.', '우리말 바로 쓰기', 19, null, null, 77),
  ('korean-grammar-079', 'korean-grammar', 'choice', '준말', '만만하지 않다', '준말의 바른 표기는?', null, '만만찮다', array['만만잖다', '만만챦다', '만만찬다'], '{}'::text[], '제39항: -하지 뒤에 않-이 어울려 -찮-이 될 때는 준 대로 적는다.', '우리말 바로 쓰기', 19, null, null, 78),
  ('korean-grammar-080', 'korean-grammar', 'choice', '준말', '간편하게', '준말의 바른 표기는?', null, '간편케', array['간편게', '간편께', '간펴케'], '{}'::text[], '제40항: 하의 ㅏ가 줄고 ㅎ이 다음 음절 첫소리와 어울려 거센소리가 되면 거센소리로 적는다.', '우리말 바로 쓰기', 19, null, null, 79),
  ('korean-grammar-081', 'korean-grammar', 'choice', '준말', '생각하건대', '준말의 바른 표기는?', null, '생각건대', array['생각컨대', '생각껀대', '생각껀데'], '{}'::text[], '안울림소리(ㄱ·ㄷ·ㅂ) 뒤에서는 하가 통째로 줄어 거센소리가 되지 않는다. 그래서 생각건대로 적는다.', '우리말 바로 쓰기', 19, null, null, 80),
  ('korean-grammar-082', 'korean-grammar', 'choice', '준말', '연구하도록', '준말의 바른 표기는?', null, '연구토록', array['연구도록', '연구또록', '연굿도록'], '{}'::text[], '울림소리 뒤에서 하의 ㅏ가 줄고 ㅎ이 남아 다음 첫소리와 거센소리가 되므로 연구토록으로 적는다.', '우리말 바로 쓰기', 19, null, null, 81),
  ('korean-grammar-083', 'korean-grammar', 'choice', '준말', '거북하지', '준말의 바른 표기는?', null, '거북지', array['거북치', '거부치', '거북찌'], '{}'::text[], 'ㄱ 받침 뒤라 하가 통째로 줄어든다. 거센소리로 적지 않고 거북지로 적는다.', '우리말 바로 쓰기', 19, null, null, 82),
  ('korean-grammar-084', 'korean-grammar', 'choice', '준말', '익숙하지 않다', '준말의 바른 표기는?', null, '익숙지 않다', array['익숙치 않다', '익쑥지 않다', '익숙찌 않다'], '{}'::text[], 'ㄱ·ㄷ·ㅂ 소리로 나는 받침 뒤에서 하가 통째로 줄면 거센소리로 적지 않는다(익숙지, 생각건대, 깨끗지).', '우리말 바로 쓰기', 19, null, null, 83),
  ('korean-grammar-085', 'korean-grammar', 'choice', '준말', '흔하다 → 흔타 · 정결하다 → 정결타', '거센소리로 적는 까닭은?', null, 'ㅎ이 다음 첫소리와 어울림', array['하 전체가 줆', '된소리되기', '사이시옷'], '{}'::text[], '울림소리 뒤에서는 하의 ㅏ만 줄고 남은 ㅎ이 다음 음절 첫소리와 어울려 거센소리가 된다.', '우리말 바로 쓰기', 19, null, null, 84),
  ('korean-grammar-086', 'korean-grammar', 'choice', '준말', '흔타 · 간편케 · 생각컨대 · 연구토록', '준말 표기가 잘못된 것은?', null, '생각컨대', array['흔타', '간편케', '연구토록'], '{}'::text[], '생각하건대는 ㄱ 받침 뒤라 하가 통째로 줄어 생각건대로 적는다.', '우리말 바로 쓰기', 19, null, null, 85),
  ('korean-grammar-087', 'korean-grammar', 'choice', '띄어쓰기', '민수야, 너밖에 없어.', '‘밖에’를 붙여 쓴 까닭은?', null, '조사라서', array['의존 명사라서', '접두사라서', '단위 명사라서'], '{}'::text[], '‘그것 말고는’의 뜻을 가진 ‘밖에’는 조사다. 조사는 그 앞말에 붙여 쓴다(제41항).', '우리말 바로 쓰기', 23, null, null, 86),
  ('korean-grammar-088', 'korean-grammar', 'choice', '띄어쓰기', '뭔 소리야? 나 지금 밖에 있는데?', '여기서 ‘밖’의 품사는?', null, '명사', array['조사', '의존 명사', '부사'], '{}'::text[], '실외를 뜻하는 ‘밖’은 명사이므로 앞말과 띄어 쓴다. ‘너밖에’의 ‘밖에’(조사)와 구별한다.', '우리말 바로 쓰기', 23, null, null, 87),
  ('korean-grammar-089', 'korean-grammar', 'choice', '띄어쓰기', '오늘만이라도', '이렇게 붙여 쓴 까닭은?', null, '조사가 연속됨', array['의존 명사라서', '어미라서', '접사라서'], '{}'::text[], '조사가 둘 이상 연속되거나 어미 뒤에 붙을 때도 앞말에 붙여 쓴다(만+이라도).', '우리말 바로 쓰기', 23, null, null, 88),
  ('korean-grammar-090', 'korean-grammar', 'choice', '띄어쓰기', '아는 것이 힘이다. / 할 수 있다.', '‘것, 수’를 띄어 쓰는 까닭은?', null, '의존 명사라서', array['조사라서', '단위 명사라서', '접미사라서'], '{}'::text[], '제42항: 의존 명사는 띄어 쓴다. 꾸며 주는 말이 있어야 쓰이지만 명사의 기능을 하는 단어이기 때문이다.', '우리말 바로 쓰기', 19, null, null, 89),
  ('korean-grammar-091', 'korean-grammar', 'choice', '띄어쓰기', '집 한 채 · 소 한 마리 · 옷 한 벌', '‘채, 마리, 벌’을 띄어 쓰는 근거는?', null, '제43항 단위 명사', array['제41항 조사', '제42항 의존 명사', '제47항 보조 용언'], '{}'::text[], '제43항: 단위를 나타내는 명사는 띄어 쓴다.', '우리말 바로 쓰기', 19, null, null, 90),
  ('korean-grammar-092', 'korean-grammar', 'choice', '띄어쓰기', '제6회 · 35그램 · 2층', '붙여 쓸 수 있는 까닭은?', null, '순서·숫자와 어울림', array['조사라서', '한자어라서', '의존 명사라서'], '{}'::text[], '단위 명사는 띄어 쓰지만, 순서를 나타내거나 아라비아 숫자와 어울려 쓰이면 붙여 쓸 수 있다(허용).', '우리말 바로 쓰기', 23, null, null, 91),
  ('korean-grammar-093', 'korean-grammar', 'choice', '띄어쓰기', '꺼져 간다 / 꺼져간다', '보조 용언 띄어쓰기는?', null, '띄어 씀 원칙, 붙임 허용', array['항상 붙여 씀', '항상 띄어 씀', '붙임 원칙, 띄움 허용'], '{}'::text[], '제47항: 보조 용언은 띄어 씀을 원칙으로 하되, 경우에 따라 붙여 씀도 허용한다.', '우리말 바로 쓰기', 19, null, null, 92),
  ('korean-grammar-094', 'korean-grammar', 'choice', '띄어쓰기', '너뿐이야. / 웃을 뿐이었다.', '두 ‘뿐’의 품사는 차례로?', null, '조사–의존 명사', array['의존 명사–조사', '조사–조사', '의존 명사–의존 명사'], '{}'::text[], '체언 뒤의 뿐은 조사라 붙여 쓰고, 관형어 뒤에서 따름이라는 뜻의 뿐은 의존 명사라 띄어 쓴다.', '우리말 바로 쓰기', 27, null, null, 93),
  ('korean-grammar-095', 'korean-grammar', 'choice', '띄어쓰기', '___ 모두 말해 보자. (알다)', '바른 띄어쓰기는?', null, '아는 대로', array['아는대로', '아 는대로', '아는 대 로'], '{}'::text[], '관형어 아는 뒤의 대로는 의존 명사이므로 띄어 쓴다.', '우리말 바로 쓰기', 27, null, null, 94),
  ('korean-grammar-096', 'korean-grammar', 'choice', '띄어쓰기', '손님들은 ___ 충분히 먹었다. (먹다)', '바른 띄어쓰기는?', null, '먹을 만큼', array['먹을만큼', '먹 을만큼', '먹을만 큼'], '{}'::text[], '관형어 먹을 뒤의 만큼은 의존 명사이므로 띄어 쓴다.', '우리말 바로 쓰기', 27, null, null, 95),
  ('korean-grammar-097', 'korean-grammar', 'choice', '띄어쓰기', '그 사람은 ___ 누구보다 앞선다. (말)', '바른 띄어쓰기는?', null, '말만큼은', array['말 만큼은', '말만 큼은', '말 만 큼은'], '{}'::text[], '체언 말 뒤의 만큼은 조사이므로 붙여 쓴다.', '우리말 바로 쓰기', 27, null, null, 96),
  ('korean-grammar-098', 'korean-grammar', 'choice', '띄어쓰기', '모든 것이 ___ 되었다. (내 생각)', '바른 띄어쓰기는?', null, '내 생각대로', array['내 생각 대로', '내생각 대로', '내생각대로'], '{}'::text[], '체언 생각 뒤의 대로는 조사이므로 붙여 쓴다. 관형어 내와 생각은 띄어 쓴다.', '우리말 바로 쓰기', 27, null, null, 97),
  ('korean-grammar-099', 'korean-grammar', 'choice', '띄어쓰기', '보다 높게 뛰자. / 시보다 소설이 좋다.', '두 ‘보다’의 품사는 차례로?', null, '부사–조사', array['조사–부사', '부사–부사', '조사–조사'], '{}'::text[], '‘어떤 수준에 비하여 한층 더’라는 뜻의 ‘보다’는 부사라 띄어 쓰고, 비교 대상 체언 뒤의 ‘보다’는 조사라 붙여 쓴다.', '우리말 바로 쓰기', 27, null, null, 98),
  ('korean-grammar-100', 'korean-grammar', 'choice', '띄어쓰기', '사과 10 개 / 사과 10개', '두 표기에 대한 설명으로 옳은 것은?', null, '둘 다 허용', array['10 개만 맞음', '10개만 맞음', '둘 다 틀림'], '{}'::text[], '단위를 나타내는 명사는 띄어 쓰는 것이 원칙이지만, 아라비아 숫자와 어울려 쓰일 때에는 붙여 쓰는 것도 허용된다. 따라서 두 표기가 모두 가능하다.', '우리말 바로 쓰기', 26, null, null, 99),
  ('korean-grammar-101', 'korean-grammar', 'choice', '띄어쓰기', '너무 아는 척을 하지 마.', '‘척’을 띄어 쓴 까닭은?', null, '의존 명사라서', array['조사라서', '보조 용언이라서', '접미사라서'], '{}'::text[], '척은 관형어 아는의 꾸밈을 받는 의존 명사이므로 띄어 쓴다.', '우리말 바로 쓰기', 26, null, null, 100),
  ('korean-grammar-102', 'korean-grammar', 'choice', '띄어쓰기', '나는 조용히 웃고만 있었다.', '‘만’을 붙여 쓴 까닭은?', null, '조사는 어미 뒤에도 붙임', array['의존 명사라서', '접미사라서', '보조 용언이라서'], '{}'::text[], '조사는 어미 뒤에 붙을 때도 앞말에 붙여 쓴다(웃-+-고+만).', '우리말 바로 쓰기', 26, null, null, 101),
  ('korean-grammar-103', 'korean-grammar', 'choice', '띄어쓰기', '그는 반성을 ___ 오히려 큰소리를 쳤다.', '바른 띄어쓰기는?', null, '하기는커녕', array['하기는 커녕', '하기 는커녕', '하기는커 녕'], '{}'::text[], '는커녕은 조사(는+커녕)이므로 앞말에 붙여 쓴다.', '우리말 바로 쓰기', 27, null, null, 102),
  ('korean-grammar-104', 'korean-grammar', 'choice', '띄어쓰기', '모습은 예전과 ___가 없었다.', '바른 띄어쓰기는?', null, '다를 바', array['다를바', '다 를바', '달을 바'], '{}'::text[], '바는 앞에 꾸미는 말이 있어야 쓰이는 의존 명사이므로 띄어 쓴다.', '우리말 바로 쓰기', 27, null, null, 103),
  ('korean-grammar-105', 'korean-grammar', 'choice', '띄어쓰기', '그는 ___ 도전했다.', '바른 띄어쓰기는?', null, '수없이', array['수 없이', '수없 이', '수 없 이'], '{}'::text[], '수없이는 한 단어인 부사이므로 붙여 쓴다.', '우리말 바로 쓰기', 27, null, null, 104),
  ('korean-grammar-106', 'korean-grammar', 'choice', '띄어쓰기', '주머니 안에는 ___.', '바른 띄어쓰기는?', null, '잔돈뿐이었다', array['잔돈 뿐이었다', '잔 돈뿐이었다', '잔돈뿐 이었다'], '{}'::text[], '체언 ‘잔돈’ 뒤의 ‘뿐’은 조사이고, ‘이었다’도 서술격 조사 ‘이다’의 활용형이므로 모두 붙여 쓴다.', '우리말 바로 쓰기', 30, null, null, 105),
  ('korean-grammar-107', 'korean-grammar', 'choice', '띄어쓰기', '그 물건은 ___ 빛이 났다.', '바른 띄어쓰기는?', null, '보석같이', array['보석 같이', '보 석같이', '보석같 이'], '{}'::text[], '체언 뒤에 쓰인 같이는 조사이므로 앞말에 붙여 쓴다.', '우리말 바로 쓰기', 30, null, null, 106),
  ('korean-grammar-108', 'korean-grammar', 'choice', '띄어쓰기', '학교를 ___ 벌써 3년이 지났다.', '바른 띄어쓰기는?', null, '졸업한 지', array['졸업한지', '졸업 한지', '졸 업한 지'], '{}'::text[], '시간의 경과를 나타내는 지는 의존 명사이므로 띄어 쓴다.', '우리말 바로 쓰기', 30, null, null, 107),
