  ('korean-grammar-110', 'korean-grammar', 'choice', '띄어쓰기', '이 문제를 ___ 시간이 필요하다.', '빈칸에 알맞은 띄어쓰기는?', null, '해결하는 데', array['해결하는데', '해결 하는데', '해결하 는데'], '{}'::text[], '이 문장의 데는 어떤 일을 하는 데 필요한 시간과 관련된 의존 명사다. 해결하는 뒤에서 띄어 쓴다. 문장을 이어 주는 어미 -는데와 구별한다.', '우리말 바로 쓰기', 30, null, null, 109),
  ('korean-grammar-111', 'korean-grammar', 'choice', '띄어쓰기', '문제 푸는 데 시간이 걸렸다.', '‘데’를 띄어 쓴 까닭은?', null, '의존 명사이기 때문', array['연결 어미이기 때문', '조사이기 때문', '접두사이기 때문'], '{}'::text[], '여기서 데는 문제를 푸는 일과 관련된 의존 명사이므로 앞말과 띄어 쓴다. 어미 -는데가 아니다.', '우리말 바로 쓰기', 30, null, null, 110),
  ('korean-grammar-112', 'korean-grammar', 'choice', '띄어쓰기', '‘지’의 띄어쓰기', '‘지’를 띄어 쓰는 경우는?', null, '시간의 경과를 나타냄', array['막연한 의문을 나타냄', '어미의 일부임', '항상 붙여 씀'], '{}'::text[], '시간의 경과를 나타내는 지는 의존 명사라 띄어 쓴다. 막연한 의문의 -ㄴ지는 어미라 붙여 쓴다.', '우리말 바로 쓰기', 30, null, null, 111),
  ('korean-grammar-113', 'korean-grammar', 'choice', '띄어쓰기', '보석같이 · 너같이', '‘같이’를 붙여 쓰는 조건은?', null, '체언 뒤 조사일 때', array['용언 뒤일 때', '문장 앞일 때', '항상 띄어 씀'], '{}'::text[], '‘같이’가 체언 뒤에 쓰여 ‘처럼’의 뜻이면 조사이므로 앞말에 붙여 쓴다.', '우리말 바로 쓰기', 30, null, null, 112),
  ('korean-grammar-114', 'korean-grammar', 'choice', '띄어쓰기', '아버지가방에들어가신다.', '띄어쓰기를 하지 않았을 때의 문제는?', null, '단어 경계가 불분명함', array['조사가 모두 빠짐', '모든 단어가 외래어임', '발음을 표시한 문장임'], '{}'::text[], '아버지가 방에 들어가신다와 아버지 가방에 들어가신다는 단어 경계가 다르다. 띄어쓰기는 문장의 구조와 의미를 분명하게 보여 준다.', '우리말 바로 쓰기', 29, null, null, 113),
  ('korean-grammar-115', 'korean-grammar', 'choice', '띄어쓰기', '책·공책 등을 챙길 수 있었다.', '띄어쓰기 설명으로 틀린 것은?', null, '등은 단위 명사라 띄움', array['을은 조사라 붙임', '수는 의존 명사라 띄움', '있었다는 한 단어'], '{}'::text[], '여기서 등은 예시한 것들을 열거하는 의존 명사이며 단위 명사가 아니다. 조사 을은 붙여 쓰고, 수는 의존 명사이므로 띄어 쓴다.', '우리말 바로 쓰기', 30, null, null, 114),
  ('korean-grammar-116', 'korean-grammar', 'choice', '띄어쓰기', '하늘에서 별이라도 따오겠다.', '‘이라도’를 붙여 쓴 까닭은?', null, '조사라서', array['의존 명사라서', '보조 용언', '부사라서'], '{}'::text[], '이라도는 조사이므로 체언 별에 붙여 쓴다.', '우리말 바로 쓰기', 27, null, null, 115),
  ('korean-grammar-117', 'korean-grammar', 'choice', '그 밖의 것', '깨끗__ · 가까__ · 번거로__', '빈칸에 공통으로 들어갈 말은?', null, '-이', array['-히', '-리', '-기'], '{}'::text[], '제51항: 부사의 끝음절이 분명히 이로만 나는 것은 -이로 적는다.', '우리말 바로 쓰기', 19, null, null, 116),
  ('korean-grammar-118', 'korean-grammar', 'choice', '그 밖의 것', '급__ · 딱__ · 속__ · 솔직__', '빈칸에 공통으로 들어갈 말은?', null, '-히', array['-이', '-리', '-기'], '{}'::text[], '제51항: 히로만 나거나 이·히로 나는 것은 -히로 적는다.', '우리말 바로 쓰기', 19, null, null, 117),
  ('korean-grammar-119', 'korean-grammar', 'choice', '그 밖의 것', '서류를 ___ 살펴보다.', '빈칸의 바른 표기는?', null, '꼼꼼히', array['꼼꼼이', '꼼꼼희', '꼼꼼리'], '{}'::text[], '꼼꼼히는 이·히로 나는 말이므로 -히로 적는다(제51항).', '우리말 바로 쓰기', 19, null, null, 118),
