  ('korean-grammar-121', 'korean-grammar', 'choice', '그 밖의 것', '-(으)ㄹ거나 · -(으)ㄹ걸 · -(으)ㄹ게', '이 어미의 첫 자음은 어떻게 적는가?', null, '예사소리로', array['된소리로', '거센소리로', '소리대로'], '{}'::text[], '제53항: 이 어미들은 [께]·[껄]처럼 소리 나도 예사소리로 적는다.', '우리말 바로 쓰기', 19, null, null, 120),
  ('korean-grammar-122', 'korean-grammar', 'choice', '그 밖의 것', '-하다가 붙는 어근 + -히', '‘딱히’를 ‘딱이’로 적지 않는 까닭은?', null, '히로 소리 나서', array['이로 소리 나서', '두음 법칙', '된소리 표기'], '{}'::text[], '부사의 끝음절이 히로 나거나 이·히로 나면 -히로 적는다.', '우리말 바로 쓰기', 19, null, null, 121),
  ('korean-grammar-123', 'korean-grammar', 'choice', '외래어·로마자', 'family', '외래어 표기법에 맞는 것은?', null, '패밀리', array['훼밀리', '페밀리', '패미리'], '{}'::text[], '외래어의 1 음운은 원칙적으로 1 기호로 적는다. f는 ㅍ으로 적어 패밀리다.', '우리말 바로 쓰기', 19, null, null, 122),
