  ('korean-grammar-164', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '흥정을 ___. / 조건을 ___.', '빈칸에 공통으로 들어갈 말은?', null, '붙인다', array['부친다', '붙힌다', '부치인다'], '{}'::text[], '겨루는 일을 어울려 시작하게 하다, 조건·이유 따위를 달다는 모두 붙이다이다.', '우리말 바로 쓰기', 21, null, null, 163),
  ('korean-grammar-165', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '감시원을 ___. / 별명을 ___.', '빈칸에 공통으로 들어갈 말은?', null, '붙인다', array['부친다', '붙힌다', '부치운다'], '{}'::text[], '사람을 딸려 붙게 하다, 이름을 만들어 주다는 모두 붙이다이다.', '우리말 바로 쓰기', 21, null, null, 164),
  ('korean-grammar-166', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '일을 ___. / 끓인 물을 ___.', '빈칸에 차례로 들어갈 말은?', null, '시킨다–식힌다', array['식힌다–시킨다', '시킨다–시킨다', '식힌다–식힌다'], '{}'::text[], '시키다는 어떤 일을 하게 하다, 식히다는 식다의 사동사다.', '우리말 바로 쓰기', 21, null, null, 165),
  ('korean-grammar-167', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '이 나무의 둘레는 세 ___이나 된다.', '빈칸의 바른 표기는?', null, '아름', array['알음', '앎', '아룸'], '{}'::text[], '아름은 두 팔을 둥글게 모아 만든 둘레다.', '우리말 바로 쓰기', 21, null, null, 166),
  ('korean-grammar-168', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '우리는 예전부터 ___이 있는 사이다.', '빈칸의 바른 표기는?', null, '알음', array['아름', '앎', '알름'], '{}'::text[], '알음은 사람끼리 서로 아는 일이다.', '우리말 바로 쓰기', 21, null, null, 167),
  ('korean-grammar-169', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '___이 힘이다.', '빈칸의 바른 표기는?', null, '앎', array['알음', '아름', '암'], '{}'::text[], '앎은 배우거나 경험하여 모르던 것을 깨달음, 아는 일이다.', '우리말 바로 쓰기', 21, null, null, 168),
  ('korean-grammar-170', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '밥을 ___. / 윗자리에 ___.', '빈칸에 차례로 들어갈 말은?', null, '안친다–앉힌다', array['앉힌다–안친다', '안친다–안친다', '앉힌다–앉힌다'], '{}'::text[], '안치다는 재료를 솥에 넣고 불 위에 올리다, 앉히다는 앉다의 사동사다.', '우리말 바로 쓰기', 21, null, null, 169),
  ('korean-grammar-171', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '두 물건의 ___에서 반응이 일어났다. (경계)', '빈칸의 바른 표기는?', null, '어름', array['얼음', '얼름', '어룸'], '{}'::text[], '어름은 두 사물의 끝이 맞닿은 자리, 얼음은 물이 얼어서 굳어진 물질이다.', '우리말 바로 쓰기', 21, null, null, 170),
  ('korean-grammar-172', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '___ 오너라. (조금 지난 뒤에)', '빈칸의 바른 표기는?', null, '이따가', array['있다가', '잇따가', '이다가'], '{}'::text[], '이따가는 조금 지난 뒤에라는 뜻의 부사다.', '우리말 바로 쓰기', 21, null, null, 171),
  ('korean-grammar-173', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '방에 잠깐 ___ 나왔다.', '빈칸의 바른 표기는?', null, '있다가', array['이따가', '잇다가', '있따가'], '{}'::text[], '있다가는 있다에 연결 어미 -다가가 붙은 말로, 어떤 곳에 머물다가 다음 행동을 했다는 뜻이다. 이따가는 조금 지난 뒤를 뜻하는 부사다.', '우리말 바로 쓰기', 21, null, null, 172),
  ('korean-grammar-174', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '오래 앉았더니 다리가 ___. (찌릿한 느낌)', '빈칸의 바른 표기는?', null, '저리다', array['절이다', '절리다', '저리우다'], '{}'::text[], '저리다는 뼈마디나 몸의 일부가 오래 눌려서 감각이 둔하고 아리다는 뜻이다.', '우리말 바로 쓰기', 21, null, null, 173),
  ('korean-grammar-175', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '김장 배추를 ___.', '빈칸의 바른 표기는?', null, '절인다', array['저린다', '절린다', '저리인다'], '{}'::text[], '절이다는 절다의 사동사로, 소금이나 식초 따위에 절게 하다는 뜻이다.', '우리말 바로 쓰기', 21, null, null, 174),
  ('korean-grammar-176', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '생선을 ___. / 마음을 ___.', '빈칸에 차례로 들어갈 말은?', null, '조린다–졸인다', array['졸인다–조린다', '조린다–조린다', '졸인다–졸인다'], '{}'::text[], '조리다는 양념이 배게 바짝 끓이다, 졸이다는 속을 태우다시피 초조해하다는 뜻이다.', '우리말 바로 쓰기', 21, null, null, 175),
  ('korean-grammar-177', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '배고파서 며칠을 ___. / 비용을 ___.', '빈칸에 차례로 들어갈 말은?', null, '주렸다–줄인다', array['줄였다–주린다', '주렸다–주린다', '줄였다–줄인다'], '{}'::text[], '주리다는 제대로 먹지 못하여 배를 곯다, 줄이다는 줄다의 사동사다.', '우리말 바로 쓰기', 21, null, null, 176),
  ('korean-grammar-178', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '열심히 ___ 했다. (자기 나름의 노력)', '괄호의 뜻에 맞는 어미는?', null, '하노라고', array['하느라고', '하너라고', '하노라구'], '{}'::text[], '-노라고는 자기 나름대로 꽤 노력했다는 뜻을 나타낸다. -느라고는 앞의 행동 때문에 뒤의 결과가 생겼다는 뜻이다. 문장의 모양만으로 구별하지 않도록 이 문항에는 의미 조건을 제시했다.', '우리말 바로 쓰기', 21, null, null, 177),
  ('korean-grammar-179', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '공부___ 밤을 새웠다.', '빈칸의 바른 표기는?', null, '하느라고', array['하노라고', '하느라구', '하너라고'], '{}'::text[], '-느라고는 앞의 내용이 뒤 내용의 목적이나 원인이 됨을 나타낸다.', '우리말 바로 쓰기', 21, null, null, 178),
  ('korean-grammar-180', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '멀리 ___ 집에서 기다려라. (찾아오다)', '빈칸의 바른 표기는?', null, '찾아오느니보다', array['찾아오는 이보다', '찾아오느니 보다', '찾아오는이보다'], '{}'::text[], '-느니보다는 -는 것보다의 뜻인 어미이므로 붙여 쓴다.', '우리말 바로 쓰기', 21, null, null, 179),
  ('korean-grammar-181', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '오는 이가 ___ 많다. (가다)', '빈칸의 바른 표기는?', null, '가는 이보다', array['가느니보다', '가는이보다', '가느니 보다'], '{}'::text[], '‘-는 사람보다’의 뜻이면 의존 명사 ‘이’에 조사 ‘보다’가 붙은 것이므로 ‘가는 이보다’로 띄어 쓴다.', '우리말 바로 쓰기', 21, null, null, 180),
  ('korean-grammar-182', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '나를 ___ 잘못한 일이 없다. (미워하다)', '빈칸의 바른 표기는?', null, '미워하리만큼', array['미워하리 만큼', '미워하리만 큼', '미워하이만큼'], '{}'::text[], '-(으)리만큼은 -(으)ㄹ 정도로의 뜻인 어미이므로 붙여 쓴다.', '우리말 바로 쓰기', 21, null, null, 181),
  ('korean-grammar-183', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '공부___ 간다. / 지방으로 ___ 한다.', '빈칸에 차례로 들어갈 말은?', null, '하러–가려', array['하려–가러', '하러–가러', '하려–가려'], '{}'::text[], '-(으)러는 가거나 오는 동작의 목적, -(으)려는 어떤 행동을 할 의도나 욕망을 나타낸다.', '우리말 바로 쓰기', 21, null, null, 182),
  ('korean-grammar-184', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '사람___ 그럴 수는 없다.', '빈칸의 바른 표기는?', null, '으로서', array['으로써', '으로서써', '으로세'], '{}'::text[], '(으)로서는 지위·신분·자격을 나타낸다.', '우리말 바로 쓰기', 29, null, null, 183),
  ('korean-grammar-185', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '닭___ 꿩을 대신했다.', '빈칸의 바른 표기는?', null, '으로써', array['으로서', '으로써서', '으로서써'], '{}'::text[], '(으)로써는 재료·수단·도구를 나타낸다.', '우리말 바로 쓰기', 21, null, null, 184),
  ('korean-grammar-186', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '그가 나를 ___ 나도 그를 믿는다.', '빈칸의 바른 표기는?', null, '믿으므로', array['믿음으로', '믿음으로써', '믿으므로써'], '{}'::text[], '-(으)므로는 까닭을 나타내는 어미로, 써가 결합하지 않는다.', '우리말 바로 쓰기', 21, null, null, 185),
  ('korean-grammar-187', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '서로를 ___ 어려움을 이겨 냈다. (수단)', '수단을 나타내는 표현은?', null, '믿음으로써', array['믿으므로', '믿으므로써', '믿음므로'], '{}'::text[], '믿음으로써는 명사 믿음에 수단을 나타내는 조사 으로써가 붙은 표현이다. 믿으므로는 동사 믿다에 이유를 나타내는 어미 -으므로가 붙은 표현이다. 이 문항은 수단이라는 의미 조건을 명시했으므로 믿음으로써를 고른다.', '우리말 바로 쓰기', 21, null, null, 186),
  ('korean-grammar-188', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '이번 회의의 안건은 비밀에 ___로 했다.', '빈칸의 바른 표기는?', null, '부치기', array['붙이기', '붙히기', '부티기'], '{}'::text[], '어떤 일을 거론하거나 문제 삼지 않는 상태에 있게 하다는 뜻은 부치다이다.', '우리말 바로 쓰기', 29, null, null, 187),
  ('korean-grammar-189', 'korean-grammar', 'choice', '혼동하기 쉬운 표기', '게시판에 홍보 전단지를 ___.', '빈칸의 바른 표기는?', null, '붙였다', array['부쳤다', '붙혔다', '부첬다'], '{}'::text[], '맞닿아 떨어지지 않게 하다는 뜻은 붙이다이다.', '우리말 바로 쓰기', 29, null, null, 188),
  ('korean-grammar-written-001', 'korean-grammar', 'written', '띄어쓰기', null, '㉠ ‘이번에는 보다 높게 뛰어 보자.’ ㉡ ‘나는 시보다 소설이 좋다.’에서 제시된 ‘보다’의 띄어쓰기가 다른 까닭을 의미와 품사를 들어 쓰시오.', null, '㉠의 ‘보다’는 ‘어떤 수준에 비하여 한층 더’라는 뜻의 부사이므로 앞말과 띄어 쓴다. ㉡의 ‘보다’는 비교의 대상을 나타내는 조사이므로 앞말 ‘시’에 붙여 쓴다.', '{}'::text[], array['㉠ 부사, 한층 더의 뜻', '㉡ 조사, 비교 대상', '부사는 띄우고 조사는 붙인다는 규정'], '', '우리말 바로 쓰기', 27, null, null, 1000),
  ('korean-grammar-written-002', 'korean-grammar', 'written', '형태에 관한 것', null, '영희: “축하해 주세요. 우리 집 토끼가 ㉠나아써요.” 철수: “많이 ㉡나아쓰면 저 한 마리 주세요.” 영희: “그게 아니라 병이 다 나은 거예요.” ㉠, ㉡을 말한 사람이 뜻한 대로 맞춤법에 맞게 고치고, 오해가 생긴 까닭을 쓰시오.', null, '㉠ 나았어요(병이 낫다), ㉡ 낳았으면(새끼를 낳다). 소리 나는 대로 ‘나아써요’라고 적어 ‘나았어요’와 ‘낳았어요’가 구별되지 않아 오해가 생겼다. 어간(낫-, 낳-)과 어미를 구별해 원형을 밝혀 적어야 뜻이 분명해진다.', '{}'::text[], array['㉠ 나았어요', '㉡ 낳았으면', '소리대로 적어 어간이 구별되지 않음'], '', '우리말 바로 쓰기', 28, null, null, 1001),
  ('korean-grammar-written-003', 'korean-grammar', 'written', '소리에 관한 것', null, '‘구지 어려운 생각을 하지 말고, 조금만 더 힘내십시요.’에서 맞춤법이 틀린 부분 두 곳을 찾아 고치고, 고친 까닭을 쓰시오.', null, '‘구지’는 ‘굳이’로 고친다. 어간 ‘굳-’에 ‘-이’가 붙어 [구지]로 소리 나도 원형을 밝혀 ㄷ으로 적는다(구개음화, 제6항). ‘힘내십시요’는 ‘힘내십시오’로 고친다. 종결 어미 ‘-오’는 생략할 수 없는 어미의 일부이다.', '{}'::text[], array['구지 → 굳이, 구개음화·원형 밝힘', '힘내십시요 → 힘내십시오', '종결 어미는 -오로 적음'], '', '우리말 바로 쓰기', 29, null, null, 1002),
  ('korean-grammar-written-004', 'korean-grammar', 'written', '맞춤법의 원리', null, '<보기> 많이, 이슬, 이파리, 오뚝이, 노름(도박), 오빠 — 이 단어들을 한글 맞춤법의 두 표기 원칙인 ㉠ 소리대로 적기, ㉡ 어법에 맞도록 적기로 나누시오.', null, '㉠ 소리대로 적기: 이슬, 이파리, 노름(도박), 오빠. ㉡ 어법에 맞도록 적기: 많이, 오뚝이. 이파리는 잎에 -이 외의 모음 접미사 -아리가 붙었고, 노름은 놀다의 본뜻에서 멀어져 원형을 밝히지 않는다.', '{}'::text[], array['㉠ 이슬·이파리·노름·오빠', '㉡ 많이·오뚝이', '이파리·노름이 원형을 밝히지 않는 까닭'], '', '우리말 바로 쓰기', 24, null, null, 1003),
  ('social-001', 'social', 'choice', '세계화와 지역화', null, '보성 녹차는 전략 A, 「I♥NY」는 전략 B의 사례다. A–B는?', null, '지리적 표시제–지역 브랜드화', array['장소 마케팅–지역 브랜드화', '지리적 표시제–장소 마케팅', '지역 브랜드화–현지화'], '{}'::text[], '보성 녹차는 국내 지리적 표시제 1호이고, 「I♥NY」는 도시를 브랜드로 알리는 지역 브랜드화 전략이다.', '성신제T · 세계화와 지역화', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 0),
  ('social-002', 'social', 'choice', '세계화와 지역화', null, '두바이는 사막과 초고층 빌딩의 이미지를 개발해 관광지로 홍보한다. 이 전략은?', null, '장소 마케팅', array['지리적 표시제', '현지화', '글로컬라이제이션'], '{}'::text[], '장소 마케팅은 특정 장소를 하나의 상품으로 보고 독특한 이미지·시설을 개발해 장소 가치를 높이는 전략이다.', '성신제T · 세계화와 지역화', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 1),
