  ('social-049', 'social', 'choice', '세계화의 그늘', null, '세계 문화가 선진국 문화를 중심으로 비슷해지는 현상 X. X의 결과는?', null, '문화적 다양성 약화', array['고유문화 강화', '빈부 격차 축소', '보편 윤리 약화'], '{}'::text[], '문화의 획일화로 약소국·원주민·소수 민족의 고유문화가 사라질 위험에 처하고 문화적 다양성이 약화된다.', '성신제T · 세계화의 문제와 해결', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 48),
  ('social-050', 'social', 'choice', '세계화의 그늘', null, '선진국은 A 산업, 개발도상국은 B 산업에 집중해 격차가 커진다. A–B는?', null, '첨단 기술–농업', array['농업–첨단 기술', '제조업–금융', '농업–금융'], '{}'::text[], '선진국은 부가 가치가 높은 금융·첨단 기술 산업에, 개발도상국은 부가 가치가 낮은 제조업·농업에 집중한다.', '성신제T · 세계화의 문제와 해결', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 49),
  ('social-051', 'social', 'choice', '세계화의 그늘', null, '관습법처럼 특정 집단 안에서 중요한 가치를 강조하는 입장 X. X가 중시하는 것은?', null, '자국민의 복지', array['보편적 인권', '세계 시민 연대', '이민자의 이동권'], '{}'::text[], '특수 윤리는 특정 집단 내의 가치를 강조하며 개별 국가의 주권, 자국민의 복지 등을 중시한다.', '성신제T · 세계화의 문제와 해결', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 50),
  ('social-052', 'social', 'choice', '세계화의 그늘', null, '브렉시트 이민 문제에서 보편 윤리는 A를, 특수 윤리는 B를 중시한다. A–B는?', null, '이동권–복지', array['복지–이동권', '주권–인권', '복지–주권'], '{}'::text[], '보편 윤리는 이민자의 자유로운 이동권을, 특수 윤리는 특정 국가 시민이 누릴 복지를 우선시한다.', '성신제T · 세계화의 문제와 해결', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 51),
  ('social-053', 'social', 'choice', '세계화의 그늘', null, '2001년 문화 다양성 선언을 채택한 기구는?', null, '유네스코', array['세계 무역 기구', '국제 통화 기금', '세계 보건 기구'], '{}'::text[], '2001년 유네스코가 채택한 문화 다양성 선언은 문화의 고유성과 다양성 보존을 위한 국제 협력 사례다.', '성신제T · 세계화의 문제와 해결', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 52),
  ('social-054', 'social', 'choice', '세계화의 그늘', null, '생산자에게 정당한 가격을 지급한 제품을 사는 윤리적 소비 운동 X. X의 효과는?', null, '생산자의 경제적 자립', array['수입업자의 이익 확대', '운송비 절감', '문화 획일화'], '{}'::text[], '공정 무역은 무역의 이익이 개발도상국의 가난한 생산자에게 돌아가 그들이 경제적으로 자립하도록 돕는다.', '성신제T · 세계화의 문제와 해결', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 53),
  ('social-055', 'social', 'choice', '세계화의 그늘', null, '빈부 격차 해결을 위한 경제적 노력으로 옳지 않은 것은?', null, '선진국 보호 무역', array['공적 개발 원조', '기술 이전', '공정 무역'], '{}'::text[], '국제적 분배 정의를 위해 선진국은 ODA·기술 이전으로 자립을 돕고, 공정 무역으로 불공정한 무역 구조를 개선한다.', '성신제T · 세계화의 문제와 해결', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 54),
  ('social-056', 'social', 'choice', '세계화의 그늘', null, '원조 목적을 인류 고통 감소로 본 X, 질서 정연한 사회 확립으로 본 Y. X–Y는?', null, '싱어–롤스', array['롤스–싱어', '칸트–롤스', '싱어–노직'], '{}'::text[], '싱어는 극단적 빈곤을 막아 인류 전체의 고통을 줄이자 했고, 롤스는 질서 정연한 사회 확립을 원조 목적으로 보았다.', '성신제T · 세계화의 문제와 해결', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 55),
  ('social-057', 'social', 'choice', '세계화의 그늘', null, '공리주의·세계 시민주의 입장에서 원조를 의무로 본 X. X가 막자고 한 빈곤은?', null, '극단적 빈곤', array['모든 상대적 빈곤', '자국민의 빈곤만', '제도의 빈곤'], '{}'::text[], '싱어는 도덕적으로 중요한 다른 일을 희생하지 않고 막을 수 있는 극단적 빈곤이 있다면 원조해야 한다고 보았다.', '성신제T · 세계화의 문제와 해결', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 56),
  ('social-058', 'social', 'choice', '세계화의 그늘', null, '공정으로서의 정의를 주장한 X. X가 본 빈곤의 원인은?', null, '정치·사회 제도의 결함', array['물질적 자원 부족', '개인의 게으름', '인구 증가'], '{}'::text[], '롤스는 빈곤이 물질적 자원 부족이 아니라 정치·사회 제도의 결함에서 생긴다고 보았다.', '성신제T · 세계화의 문제와 해결', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 57),
  ('social-059', 'social', 'choice', '세계화의 그늘', null, '콜탄처럼 전쟁·범죄를 동원해 생산하는 자원 X. EU가 X에 대해 한 일은?', null, '원산지 확인 의무화', array['수입 전면 자유화', '가격 보조', '채굴 장려'], '{}'::text[], '콜탄 같은 분쟁 광물에 대해 EU는 2021년부터 원산지가 분명한 광물만 수입하도록 무역 규제를 시행하고 있다.', '성신제T · 세계화의 문제와 해결', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 58),
  ('social-060', 'social', 'choice', '세계화의 그늘', null, '세계화가 초래하는 문제로 옳지 않은 것은?', null, '문화 다양성 강화', array['빈부 격차 심화', '전염병 급속 확산', '보편·특수 윤리 갈등'], '{}'::text[], '세계화는 문화 획일화, 빈부 격차 심화, 보편 윤리와 특수 윤리의 갈등, 전염병 확산 등을 초래할 수 있다.', '성신제T · 세계화의 문제와 해결', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 59),
  ('social-061', 'social', 'choice', '평화와 행위 주체', null, '공식성과 대표성을 지닌 가장 기본적인 행위 주체 X. X가 최우선하는 것은?', null, '자국 이익·자국민 보호', array['지구촌 공익 실현', '국제 규범 정립', '종교적 화합'], '{}'::text[], '국가는 가장 기본적인 행위 주체이며, 자국의 이익과 자국민 보호를 위한 외교 활동을 최우선으로 한다.', '성신제T · 평화와 행위 주체·통일', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 60),
  ('social-062', 'social', 'choice', '평화와 행위 주체', null, '국제 연합(UN)·WHO·IMF가 속한 행위 주체 X. X의 구성원은?', null, '주권 국가', array['시민 개인', '다국적 기업', '종교 단체'], '{}'::text[], '정부 간 국제기구는 주권 국가를 구성원으로 하며 국가 간 이해관계를 조정하고 국제 규범을 정립한다.', '성신제T · 평화와 행위 주체·통일', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 61),
  ('social-063', 'social', 'choice', '평화와 행위 주체', null, '국경 없는 의사회·그린피스·국제 사면 위원회가 속하는 행위 주체는?', null, '국제 비정부 기구', array['정부 간 국제기구', '영향력 있는 개인', '다국적 기업'], '{}'::text[], '이들은 공익 실현을 위한 비영리 시민 단체인 국제 비정부 기구(NGO)다.', '성신제T · 평화와 행위 주체·통일', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 62),
  ('social-064', 'social', 'choice', '평화와 행위 주체', null, '1971년 핵실험 반대로 발족해 고래 보호 활동을 하는 NGO는?', null, '그린피스', array['국경 없는 의사회', '국제 사면 위원회', '국제 연합'], '{}'::text[], '그린피스는 1971년 핵실험 반대를 위해 발족했으며 원자력 반대, 방사성 폐기물 투기 저지, 고래 보호 등을 한다.', '성신제T · 평화와 행위 주체·통일', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 63),
  ('social-065', 'social', 'choice', '평화와 행위 주체', null, '칠레 피노체트 정권의 인권 침해를 고발한 NGO X. X의 활동 영역은?', null, '사형 폐지·양심수 옹호', array['긴급 의료 구호', '핵실험 저지', '국제 금융 안정'], '{}'::text[], '국제 사면 위원회는 고문 추방, 사형 폐지, 난민 보호, 소년병 반대, 양심수 인권 옹호 활동을 한다.', '성신제T · 평화와 행위 주체·통일', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 64),
  ('social-066', 'social', 'choice', '평화와 행위 주체', null, '남수단 외과 수술·예멘 의료 지원을 한 NGO X. X의 설립 신념은?', null, '누구나 치료받을 권리', array['핵 없는 세상', '고문 추방', '자유 무역 확대'], '{}'::text[], '국경 없는 의사회는 성별·인종·종교와 상관없이 누구나 의료 서비스를 받을 권리가 있다는 신념으로 설립되었다.', '성신제T · 평화와 행위 주체·통일', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 65),
  ('social-067', 'social', 'choice', '평화와 행위 주체', null, '영향력 있는 개인으로 볼 수 있는 행위 주체가 아닌 것은?', null, '그린피스', array['교황', '국제 연합 사무총장', '강대국 국가 원수'], '{}'::text[], '영향력 있는 개인에는 강대국 국가 원수, 국제 연합 사무총장, 교황 등이 있다. 그린피스는 NGO다.', '성신제T · 평화와 행위 주체·통일', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 66),
  ('social-068', 'social', 'choice', '평화와 행위 주체', null, '국제 사회의 특징으로 옳지 않은 것은?', null, '강력한 중앙 정부 존재', array['자국의 이익 추구', '힘의 논리 작용', '어느 정도 질서 존재'], '{}'::text[], '국제 사회는 강제력을 가진 중앙 정부가 없는 무정부 상태이며, 자국 이익 추구와 힘의 논리가 작용한다.', '성신제T · 평화와 행위 주체·통일', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 67),
  ('social-069', 'social', 'choice', '평화와 행위 주체', null, '문화적 폭력을 말한 A의 사상과 평화 연맹을 말한 B의 사상은?', null, '적극적 평화론–영구 평화론', array['영구 평화론–적극적 평화론', '절대 평화론–영구 평화론', '적극적 평화론–절대 윤리'], '{}'::text[], '갈퉁은 직접적·구조적·문화적 폭력을 제거한 적극적 평화를, 칸트는 평화 연맹을 통한 영구 평화를 주장했다.', '성신제T · 평화와 행위 주체·통일', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 68),
  ('social-070', 'social', 'choice', '평화와 행위 주체', null, '모든 전쟁을 끝낼 평화 연맹을 주장한 X. X가 각국에 요구한 체제는?', null, '공화정', array['군주정', '최소 국가', '공산 사회'], '{}'::text[], '칸트는 평화 연맹이 필요하며, 각국은 시민의 자유를 보장하는 공화정 체제를 확립해야 한다고 보았다.', '성신제T · 평화와 행위 주체·통일', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 69),
  ('social-071', 'social', 'choice', '평화와 행위 주체', null, '종교·사상·언어·예술이 폭력을 정당화하는 것. 갈퉁이 말한 이 폭력은?', null, '문화적 폭력', array['구조적 폭력', '직접적 폭력', '물리적 폭력'], '{}'::text[], '갈퉁은 종교·사상·언어·예술 등이 폭력을 정당화하는 것을 문화적 폭력이라 하였다.', '성신제T · 평화와 행위 주체·통일', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 70),
  ('social-072', 'social', 'choice', '평화와 행위 주체', null, '고통받는 사람을 구하려면 무력을 쓸 수 있다는 입장은?', null, '절대 윤리', array['절대 평화', '소극적 평화', '영구 평화'], '{}'::text[], '절대 평화는 어떤 경우에도 무력을 쓰면 안 된다는 입장이고, 절대 윤리는 사람을 구하려면 폭력도 쓸 수 있다는 입장이다.', '성신제T · 평화와 행위 주체·통일', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 71),
  ('social-073', 'social', 'choice', '평화와 행위 주체', null, '소극적 평화를 위해 정부 간 국제기구가 맡는 역할은?', null, '분쟁 당사국 중재', array['인도주의 구호만', '자국민 보호', '공화정 수립'], '{}'::text[], '소극적 평화를 위해 정부 간 국제기구는 분쟁 당사국이 원만한 해결을 모색하도록 중재자 역할을 한다.', '성신제T · 평화와 행위 주체·통일', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 72),
  ('social-074', 'social', 'choice', '남북 통일', null, '남북 분단의 국내적 배경으로 옳지 않은 것은?', null, '냉전 체제', array['신탁 통치 찬반 논쟁', '6·25 전쟁', '민족 내부 응집력 부족'], '{}'::text[], '자유주의·공산주의 진영 간 냉전 체제는 분단의 국제적 배경이다. 나머지는 국내적 배경이다.', '성신제T · 평화와 행위 주체·통일', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 73),
  ('social-075', 'social', 'choice', '남북 통일', null, '통일로 북한 주민 인권이 개선되면 실현되는 평화는?', null, '적극적 평화', array['소극적 평화', '절대 평화', '무장 평화'], '{}'::text[], '전쟁 위협 제거는 소극적 평화, 이산가족 슬픔 해소·북한 주민 인권 개선은 적극적 평화 실현과 연결된다.', '성신제T · 평화와 행위 주체·통일', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 74),
  ('social-076', 'social', 'choice', '남북 통일', null, '국방비는 A 비용, 화폐 통합 비용은 B 비용이다. A–B는?', null, '분단–통일', array['통일–분단', '분단–분단', '통일–통일'], '{}'::text[], '분단 비용은 분단으로 생기는 유·무형 지출(국방비 등), 통일 비용은 통일 후 격차를 통합하는 비용이다.', '성신제T · 평화와 행위 주체·통일', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 75),
  ('social-077', 'social', 'choice', '남북 통일', null, '내수 시장 확대·전쟁 위험 해소·규모의 경제는 무엇의 예인가?', null, '통일 편익', array['통일 비용', '분단 비용', '기회비용'], '{}'::text[], '통일로 얻을 수 있는 경제적·비경제적 이익을 통일 편익이라 하며, 내수 시장 확대 등이 그 예다.', '성신제T · 평화와 행위 주체·통일', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 76),
  ('social-078', 'social', 'choice', '남북 통일', null, '1969년 동독과의 교류·협력을 추진한 서독의 정책은?', null, '동방 정책', array['햇볕 정책', '봉쇄 정책', '신탁 통치'], '{}'::text[], '서독은 1969년 동방 정책을 통해 동독과의 교류·협력을 적극적으로 추진하였다.', '성신제T · 평화와 행위 주체·통일', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 77),
  ('social-079', 'social', 'choice', '남북 통일', null, '독일 통일 과정에 대한 설명으로 옳지 않은 것은?', null, '주변국 동의 없이 통일', array['꾸준한 인적 교류', '동방 정책 추진', '합법적 이주 지속'], '{}'::text[], '서독은 독일을 분할 점령했던 미국·소련·영국·프랑스를 설득해 통일에 대한 동의를 이끌어 냈다.', '성신제T · 평화와 행위 주체·통일', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 78),
  ('social-080', 'social', 'choice', '남북 통일', null, '바람직한 통일의 조건으로 옳지 않은 것은?', null, '무력에 의한 통일', array['평화적 통일', '국민적 합의', '주변국과의 협력'], '{}'::text[], '바람직한 통일은 평화적 통일, 국민적 합의에 따른 민주적 통일, 주변국과의 협력이 함께 이루어져야 한다.', '성신제T · 평화와 행위 주체·통일', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 79),
  ('social-081', 'social', 'choice', '역사·영토 갈등', null, '2002년부터 약 5년간 추진된 중국의 연구 X. X가 중국사로 보려 한 것이 아닌 것은?', null, '신라', array['고구려', '발해', '고조선'], '{}'::text[], '동북공정은 고조선·부여·고구려·발해의 역사를 중국 고대 지방 정권의 역사로 설명하려는 흐름이 핵심 쟁점이다.', '성신제T · 역사 갈등과 독도', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 80),
  ('social-082', 'social', 'choice', '역사·영토 갈등', null, '동북공정의 추진 배경으로 옳지 않은 것은?', null, '순수한 학술 연구', array['동북 3성 변경 안정', '소수 민족 분리 방지', '국가 통합 강화'], '{}'::text[], '동북공정은 변경 안정, 소수 민족 분리 움직임 방지, 국가 통합 강화라는 정책 목표와 결합되어 있다.', '성신제T · 역사 갈등과 독도', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 81),
  ('social-083', 'social', 'choice', '역사·영토 갈등', null, '사도광산 해설에서 에도 시대 기술만 강조하는 왜곡 방식은?', null, '시기 제한', array['강제성 약화', '침략 정당화', '영토 주장 반복'], '{}'::text[], '특정 시기만 잘라 보여 주는 시기 제한 방식은 근대의 조선인 강제 동원 역사를 주변화한다.', '성신제T · 역사 갈등과 독도', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 82),
  ('social-084', 'social', 'choice', '역사·영토 갈등', null, '''강제 연행''을 모호한 이동·동원으로 바꿔 쓰는 방식 X. X로 생기는 문제는?', null, '가해 책임이 흐려짐', array['영토관이 고착됨', '피해 자료가 늘어남', '세계유산 취소'], '{}'::text[], '강제성 약화 방식은 가해 책임과 피해자의 경험을 흐린다.', '성신제T · 역사 갈등과 독도', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 83),
  ('social-085', 'social', 'choice', '역사·영토 갈등', null, '식민 지배를 근대화·질서 확대로 설명하는 왜곡 방식은?', null, '침략의 정당화', array['시기 제한', '강제성 약화', '영토 주장 반복'], '{}'::text[], '침략의 정당화는 지배와 폭력의 불법성과 피해를 축소한다.', '성신제T · 역사 갈등과 독도', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 84),
  ('social-086', 'social', 'choice', '역사·영토 갈등', null, '2024년 세계유산이 된 사도광산에 대해 옳은 태도는?', null, '전체 역사 해설 이행 확인', array['등재로 논쟁 종료', '에도 시대만 기억', '강제 동원 제외'], '{}'::text[], '유네스코는 모든 시기의 전체 역사 해설을 권고했다. 등재되었다고 논쟁이 끝난 것이 아니라 이행을 확인해야 한다.', '성신제T · 역사 갈등과 독도', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 85),
  ('social-087', 'social', 'choice', '역사·영토 갈등', null, '정치 지도자의 참배가 외교 갈등이 되는 X. X에 합사된 사람은?', null, 'A급 전범', array['위안부 피해자', '독립운동가', '강제 동원 피해자'], '{}'::text[], '야스쿠니 신사는 일본의 전몰자를 기리는 시설로 A급 전범도 합사되어 있어 참배가 침략 미화로 받아들여진다.', '성신제T · 역사 갈등과 독도', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 86),
  ('social-088', 'social', 'choice', '역사·영토 갈등', null, '1877년 일본 최고 행정 기관이 울릉도와 ''외 1도''를 일본과 무관하다 한 자료는?', null, '태정관 지령', array['칙령 제41호', 'SCAPIN 677', '시마네현 고시'], '{}'::text[], '태정관 지령은 지적 편찬 과정에서 울릉도와 외 1도가 일본과 관계없다고 지시한 1877년 자료다.', '성신제T · 역사 갈등과 독도', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 87),
  ('social-089', 'social', 'choice', '역사·영토 갈등', null, '1900년 대한제국 칙령 제41호가 울도군 관할에 넣은 섬이 아닌 것은?', null, '대마도', array['울릉 전도', '죽도', '석도'], '{}'::text[], '칙령 제41호는 울도군의 관할을 울릉 전도·죽도·석도로 규정했으며, 석도는 독도를 가리키는 것으로 본다.', '성신제T · 역사 갈등과 독도', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 88),
  ('social-090', 'social', 'choice', '역사·영토 갈등', null, '1905년 시마네현 고시 제40호로 독도를 편입할 때 일본이 내세운 논리는?', null, '무주지 선점론', array['실효 지배론', '평화 조약', '태정관 지령'], '{}'::text[], '일본은 독도가 주인 없는 땅이어서 선점으로 영토를 획득했다는 무주지 선점론을 내세웠다.', '성신제T · 역사 갈등과 독도', 5, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 89),
  ('social-091', 'social', 'choice', '역사·영토 갈등', null, '1946년 SCAPIN 677에 대한 설명으로 옳은 것은?', null, '행정 범위에서 독도 제외', array['한국 주권 최종 확정', '일본 영유 인정', '독도 편입 고시'], '{}'::text[], '연합군 최고사령부는 일본의 행정 범위에서 독도를 제외했으나, 그 지령이 최종 영유권 결정은 아니라고 명시했다.', '성신제T · 역사 갈등과 독도', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 90),
  ('social-092', 'social', 'choice', '역사·영토 갈등', null, '일본이 독도 편입을 결정한 1905년의 군사적 맥락은?', null, '러일 전쟁 중', array['청일 전쟁 직전', '6·25 전쟁 중', '제2차 세계 대전 후'], '{}'::text[], '편입은 러일 전쟁 중 러시아 함대 감시 등 군사적 필요에서 이루어졌으며, 1904년에는 망루가 설치되었다.', '성신제T · 역사 갈등과 독도', 5, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 91),
  ('social-093', 'social', 'choice', '역사·영토 갈등', null, '영해는 원칙적으로 A해리, 배타적 경제 수역은 최대 B해리다. A–B는?', null, '12–200', array['3–200', '12–100', '200–12'], '{}'::text[], '영해는 기선에서 원칙적으로 12해리, 배타적 경제 수역은 최대 200해리까지 인정된다.', '성신제T · 역사 갈등과 독도', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 92),
  ('social-094', 'social', 'choice', '역사·영토 갈등', null, '동해안은 A 기선, 서·남해안은 B 기선을 적용한다. A–B는?', null, '통상–직선', array['직선–통상', '통상–통상', '직선–직선'], '{}'::text[], '섬이 적은 동해안은 썰물 때 해안선인 통상 기선, 섬이 많은 서·남해안은 직선 기선을 적용한다.', '성신제T · 역사 갈등과 독도', 4, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 93),
  ('social-095', 'social', 'choice', '역사·영토 갈등', null, '일본과 가까워 영해를 12해리보다 좁게 적용하는 곳 X. X의 영해는?', null, '직선 기선에서 3해리', array['통상 기선에서 12해리', '24해리', '200해리'], '{}'::text[], '대한 해협은 일본과 인접해 직선 기선에서 3해리까지를 영해로 적용한다.', '성신제T · 역사 갈등과 독도', 4, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 94),
  ('social-096', 'social', 'choice', '역사·영토 갈등', null, '어업 협정으로 한·일 사이 A, 한·중 사이 B 수역을 설정했다. A–B는?', null, '중간 수역–잠정 조치 수역', array['잠정 조치 수역–중간 수역', '영해–중간 수역', '공해–잠정 조치 수역'], '{}'::text[], '신한·일 어업 협정으로 한·일 중간 수역, 한·중 어업 협정으로 한·중 잠정 조치 수역을 설정했다.', '성신제T · 역사 갈등과 독도', 4, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 95),
  ('social-097', 'social', 'choice', '역사·영토 갈등', null, '독도 주변에 난류·한류가 만나 형성되는 수역 X. X 덕분에 풍부한 것은?', null, '어족 자원', array['석탄', '구아노', '금광'], '{}'::text[], '독도 주변은 조경 수역을 형성해 어족 자원이 풍부하다. 메탄하이드레이트도 매장되어 있다.', '성신제T · 역사 갈등과 독도', 4, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 96),
  ('social-098', 'social', 'choice', '역사·영토 갈등', null, '독도의 가치 중 환경·생태적 가치에 해당하는 것은?', null, '해저 화산 진화 과정', array['메탄하이드레이트', 'EEZ 기준점', '여객선 관광'], '{}'::text[], '독도는 천연 보호 구역이며 해저 화산의 진화 과정을 볼 수 있어 지형학적으로 의미가 크다. 나머지는 영역적·경제적 가치다.', '성신제T · 역사 갈등과 독도', 4, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 97),
  ('social-099', 'social', 'choice', '역사·영토 갈등', null, '센카쿠 열도를 실효 지배하는 A, 쿠릴 열도를 실효 지배하는 B는?', null, '일본–러시아', array['중국–러시아', '일본–일본', '중국–일본'], '{}'::text[], '센카쿠 열도(댜오위다오)는 일본, 쿠릴 열도(지시마)는 러시아가 실효 지배한다.', '성신제T · 역사 갈등과 독도', 5, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 98),
  ('social-100', 'social', 'choice', '역사·영토 갈등', null, '베트남·필리핀·중국 등이 나눠 지배하며 다투는 군도는?', null, '난사 군도', array['시사 군도', '센카쿠 열도', '쿠릴 열도'], '{}'::text[], '난사(스프래틀리) 군도는 베트남·필리핀·중국·타이완 등이 분할 지배하고, 말레이시아·브루나이도 분쟁에 참여한다.', '성신제T · 역사 갈등과 독도', 5, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 99),
  ('social-101', 'social', 'choice', '역사·영토 갈등', null, '역사 갈등을 평화롭게 해결하는 노력으로 옳지 않은 것은?', null, '자국 중심 교과서 강화', array['공동 역사 교재 개발', '여성 국제 전범 법정', '청소년 역사 캠프'], '{}'::text[], '공동 역사 연구와 국제 연대·교류 확대가 역사 갈등의 평화적 해결 방법이다.', '성신제T · 역사 갈등과 독도', 5, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 100),
  ('social-102', 'social', 'choice', '사회 윤리와 정의', null, '『도덕적 인간과 비도덕적 사회』의 저자 X. X가 집단 문제 해결에 필요하다고 본 것은?', null, '도덕이 통제하는 강제력', array['개인의 양심만', '무제한의 폭력', '시장의 자율'], '{}'::text[], '니부어는 집단의 비도덕성을 극복하려면 도덕적 선의지의 통제를 받는 외적 강제력이 필요하다고 보았다.', '성신제T · 정의의 의미', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 101),
  ('social-103', 'social', 'choice', '사회 윤리와 정의', null, '니부어의 주장으로 옳지 않은 것은?', null, '개인 도덕이 집단 도덕 결정', array['집단은 이기적이 되기 쉬움', '개인 도덕성도 필요', '도덕이 강제력 통제'], '{}'::text[], '니부어는 개인의 도덕적 행위가 집단의 도덕성을 결정하지 못하며, 오히려 구조와 제도가 개인 행위의 도덕성을 결정할 수 있다고 보았다.', '성신제T · 정의의 의미', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 102),
  ('social-104', 'social', 'choice', '사회 윤리와 정의', null, '니부어에 따르면 집단 간 관계는 윤리적이기보다 지극히 어떠한가?', null, '정치적', array['합리적', '이타적', '종교적'], '{}'::text[], '니부어는 집단 간 관계가 지극히 정치적이며, 각 집단이 지닌 힘의 비율에 따라 수립된다고 보았다.', '성신제T · 정의의 의미', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 103),
  ('social-105', 'social', 'choice', '사회 윤리와 정의', null, '사회 구조·제도의 도덕성을 중시하는 윤리 X. X의 문제 해결 방법은?', null, '제도 개선·세력 균형', array['개인 선의지 함양만', '도덕적 습관만', '양심 회복만'], '{}'::text[], '사회 윤리는 개인의 도덕성 함양과 더불어 사회 구조·제도 개선, 세력 균형, 최소한의 외적 강제력을 해결책으로 본다.', '성신제T · 정의의 의미', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 104),
  ('social-106', 'social', 'choice', '사회 윤리와 정의', null, '정의를 의로움(義)으로 표현한 A, 지혜·용기·절제의 조화로 본 B는?', null, '맹자–플라톤', array['공자–벤담', '맹자–마르크스', '플라톤–맹자'], '{}'::text[], '맹자는 정의를 의로움(義)으로 표현했고, 플라톤은 지혜·용기·절제가 조화를 이룰 때 정의가 나타난다고 보았다.', '성신제T · 정의의 의미', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 105),
  ('social-107', 'social', 'choice', '사회 윤리와 정의', null, '최대 다수의 최대 행복을 정의로 본 사상가는?', null, '벤담', array['플라톤', '마르크스', '공자'], '{}'::text[], '벤담은 최대 다수의 사람이 최대의 행복을 얻을 수 있게 하는 것을 정의로 보았다.', '성신제T · 정의의 의미', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 106),
  ('social-108', 'social', 'choice', '사회 윤리와 정의', null, '공정한 절차로 생긴 결과는 정당하다는 정의는?', null, '절차적 정의', array['분배적 정의', '교정적 정의', '일반적 정의'], '{}'::text[], '절차적 정의는 공정한 절차를 통하여 발생한 결과는 정당하다고 보며, 합의 과정의 투명성과 공정성을 중시한다.', '성신제T · 정의의 의미', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 107),
  ('social-109', 'social', 'choice', '사회 윤리와 정의', null, '아리스토텔레스의 분배적 정의는 A 비례, 교정적 정의는 B 비례다. A–B는?', null, '기하학적–산술적', array['산술적–기하학적', '기하학적–기하학적', '산술적–산술적'], '{}'::text[], '분배적 정의는 공헌에 따라 나누는 기하학적 비례, 교정적 정의는 손해를 바로잡는 산술적 비례를 따른다.', '성신제T · 정의의 의미', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 108),
  ('social-110', 'social', 'choice', '사회 윤리와 정의', null, '아리스토텔레스가 ''공동선과 덕을 위한 법을 준수하는 것''이라 한 정의는?', null, '일반적 정의', array['분배적 정의', '교정적 정의', '절차적 정의'], '{}'::text[], '일반적(보편적) 정의는 법을 지키는 것으로, 법을 지키는 사람은 정의롭고 지키지 않는 사람은 부정의하다.', '성신제T · 정의의 의미', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 109),
  ('social-111', 'social', 'choice', '사회 윤리와 정의', null, '아리스토텔레스의 정의관으로 옳지 않은 것은?', null, '교정: 가치에 비례 분배', array['분배: 기하학적 비례', '교정: 산술적 비례', '특수적 정의에 분배 포함'], '{}'::text[], '각자의 가치(공헌)에 비례해 나누는 것은 분배적 정의다. 교정적 정의는 잘못된 이익·손해를 바로잡는다.', '성신제T · 정의의 의미', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 110),
  ('social-112', 'social', 'choice', '사회 윤리와 정의', null, '교정적 정의가 적용되는 교섭(거래)의 범위로 옳은 것은?', null, '자발·비자발 모두', array['비자발적 교섭만', '자발적 교섭만', '국가 간 교섭만'], '{}'::text[], '아리스토텔레스의 교정적 정의는 자발적 교섭과 비자발적 교섭 모두에서 생긴 불균형에 적용된다.', '성신제T · 정의의 의미', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 111),
  ('social-113', 'social', 'choice', '사회 윤리와 정의', null, '''사회 제도의 제1덕목은 정의''라고 한 X. X가 정당화될 수 없다고 본 것은?', null, '다수 위해 소수 자유 박탈', array['정의 위한 제도 개혁', '기본권 보장', '공정한 법 집행'], '{}'::text[], '롤스는 타인의 더 큰 선을 위해 소수의 자유를 빼앗는 것은 정당화될 수 없다고 보았다.', '성신제T · 정의의 의미', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 112),
  ('social-114', 'social', 'choice', '사회 윤리와 정의', null, '정의의 필요성으로 옳지 않은 것은?', null, '공동선만 실현', array['기본적 권리 보장', '갈등 해결', '사회 통합의 기반'], '{}'::text[], '정의는 기본권 보장, 갈등 해결, 사회 통합의 기반이 되며 개인선과 공동선을 함께 실현하게 한다.', '성신제T · 정의의 의미', 4, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 113),
  ('social-115', 'social', 'choice', '사회 윤리와 정의', null, '개인의 행복·자아실현은 A, 구성원 모두의 이익은 B다. A–B는?', null, '개인선–공동선', array['공동선–개인선', '개인선–개인선', '공익–사익'], '{}'::text[], '개인선은 개인이 좋다고 여기며 추구하는 것, 공동선은 사회 구성원 모두에게 이익이 되는 것이다.', '성신제T · 정의의 의미', 4, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 114),
  ('social-116', 'social', 'choice', '분배적 정의', null, '1인 1표의 선거권은 어떤 분배 기준의 사례인가?', null, '절대적 평등', array['능력', '업적', '필요'], '{}'::text[], '1인 1표 선거권, 청소 구역을 같은 넓이로 배정하는 것은 절대적 평등에 따른 분배다.', '성신제T · 분배적 정의', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 115),
  ('social-117', 'social', 'choice', '분배적 정의', null, '자격증으로 신입을 뽑으면 A, 판매 실적으로 승진시키면 B 기준이다. A–B는?', null, '능력–업적', array['업적–능력', '능력–필요', '필요–업적'], '{}'::text[], '능력은 가능성에, 업적은 실제로 이뤄 낸 결과에 주목한다.', '성신제T · 분배적 정의', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 116),
  ('social-118', 'social', 'choice', '분배적 정의', null, '기초 생활 수급자 생계 급여의 분배 기준 X. X의 단점은?', null, '자원 한정·의욕 저하', array['약자 배려 부족', '측정 기준 모호', '경쟁 과열'], '{}'::text[], '필요에 따른 분배는 약자의 인간다운 삶을 보장하지만, 한정된 자원과 성취동기 약화가 단점이다.', '성신제T · 분배적 정의', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 117),
  ('social-119', 'social', 'choice', '분배적 정의', null, '성과 연봉제처럼 결과를 기준으로 나누는 방식 X. X의 단점이 아닌 것은?', null, '결과 수량화 어려움', array['약자 배려 부족', '경쟁 과열', '서로 다른 업적 비교 곤란'], '{}'::text[], '업적에 따른 분배는 결과를 수량화하기 쉬운 것이 장점이다. 약자 배려 부족, 경쟁 과열 등이 단점이다.', '성신제T · 분배적 정의', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 118),
  ('social-120', 'social', 'choice', '분배적 정의', null, '능력에 따른 분배의 문제점을 지적한 『공정하다는 착각』의 저자는?', null, '샌델', array['롤스', '노직', '왈처'], '{}'::text[], '샌델은 재능을 갖게 된 것도, 그 재능을 보상하는 사회에 사는 것도 행운이라며 능력 보상을 당연시하지 말라고 했다.', '성신제T · 분배적 정의', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 119),
  ('social-121', 'social', 'choice', '분배적 정의', null, '절대적 평등에 따른 분배의 단점으로 알맞은 것은?', null, '책임 의식 약화', array['약자 소외', '측정 기준 모호', '경쟁 과열'], '{}'::text[], '절대적 평등은 기회와 혜택을 균등히 보장하지만 생산 의욕·효율성을 떨어뜨리고 개인의 책임 의식을 약화시킬 수 있다.', '성신제T · 분배적 정의', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 120),
  ('social-122', 'social', 'choice', '분배적 정의', null, '''능력에 따라 일하고 필요에 따라 분배''를 주장한 X. X가 이상으로 삼은 사회는?', null, '계급 없는 공산 사회', array['최소 국가', '질서 정연한 사회', '공화정'], '{}'::text[], '마르크스는 생산 수단이 공유되고 계급과 국가가 소멸한 공산 사회를 이상으로 삼았다.', '성신제T · 분배적 정의', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 121),
  ('social-123', 'social', 'choice', '분배적 정의', null, '최소 수혜자에게 최대 이익을 말한 X. X의 정의 원칙 중 최우선 원칙은?', null, '평등한 자유의 원칙', array['차등의 원칙', '기회균등의 원칙', '효용의 원칙'], '{}'::text[], '롤스의 정의 원칙은 서열적이어서 제1원칙(평등한 자유)이 제2원칙(공정한 기회균등·차등)보다 우선한다.', '성신제T · 분배적 정의', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 122),
  ('social-124', 'social', 'choice', '분배적 정의', null, '롤스의 제2원칙을 이루는 두 원칙은?', null, '기회균등–차등', array['자유–차등', '취득–이전', '효용–차등'], '{}'::text[], '제2원칙은 공정한 기회균등의 원칙과, 불평등은 최소 수혜자에게 최대 이익일 때 정당하다는 차등의 원칙이다.', '성신제T · 분배적 정의', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 123),
  ('social-125', 'social', 'choice', '분배적 정의', null, '원초적 입장에서 자신의 재능·지위를 모르게 하는 장치 X. X 아래서도 아는 것은?', null, '사회의 일반적 지식', array['자신의 재능', '자신의 사회적 지위', '자신의 가치관'], '{}'::text[], '무지의 베일은 자신의 특수한 사실을 가리지만, 인간 사회에 관한 일반적 지식은 알 수 있게 한다.', '성신제T · 분배적 정의', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 124),
  ('social-126', 'social', 'choice', '분배적 정의', null, '롤스가 본 원초적 입장의 당사자에 대한 설명으로 옳지 않은 것은?', null, '타인을 배려하는 이타심', array['상호 무관심', '합리적 존재', '위험 최소화 전략'], '{}'::text[], '원초적 입장의 당사자는 타인의 이익에 관심 없는(상호 무관심) 합리적인 사람으로, 시기심이 없다.', '성신제T · 분배적 정의', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 125),
  ('social-127', 'social', 'choice', '분배적 정의', null, '롤스의 정의관으로 옳지 않은 것은?', null, '형식적 개방이면 충분', array['불평등 조건부 허용', '재능 분포는 공동 자산', '순수 절차적 정의'], '{}'::text[], '롤스는 공직·지위가 형식적으로 열려 있을 뿐 아니라 모두가 차지할 공정한 기회를 가져야 한다고 보았다.', '성신제T · 분배적 정의', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 126),
  ('social-128', 'social', 'choice', '분배적 정의', null, '상속세·증여세를 무겁게 매겨 부의 세습을 막자는 롤스의 구상은?', null, '재산 소유 민주주의', array['최소 국가론', '복합 평등', '공산 사회'], '{}'::text[], '롤스는 부가 대를 이어 쌓이는 것을 사전에 분산하는 재산 소유 민주주의를 구상했다.', '성신제T · 분배적 정의', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 127),
  ('social-129', 'social', 'choice', '분배적 정의', null, '취득·이전·교정의 원칙을 말한 X. X가 정당하다고 본 국가는?', null, '최소 국가', array['복지 국가', '확대 국가', '공화정 연맹'], '{}'::text[], '노직은 국가의 역할이 강도·절도·사기로부터 소유권을 보호하는 데 한정되어야 한다는 최소 국가론을 주장했다.', '성신제T · 분배적 정의', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 128),
  ('social-130', 'social', 'choice', '분배적 정의', null, '노직의 소유 권리론으로 옳지 않은 것은?', null, '약자 위한 재분배 찬성', array['교정의 원칙 인정', '비정형적 분배', '무정부주의 비판'], '{}'::text[], '노직은 사회적 약자를 위한 과세가 개인의 소유권을 침해한다고 보아 재분배 정책을 비판했다.', '성신제T · 분배적 정의', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 129),
  ('social-131', 'social', 'choice', '분배적 정의', null, '속임수 없이 자발적 교환·증여·상속으로 받은 소유물. 노직의 어떤 원칙인가?', null, '이전에서의 정의', array['취득에서의 정의', '교정의 원칙', '차등의 원칙'], '{}'::text[], '이전의 원칙에 따르면 강압 없는 자발적 교환·증여·상속으로 양도받은 소유물에 정당한 소유 권리가 있다.', '성신제T · 분배적 정의', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 130),
  ('social-132', 'social', 'choice', '분배적 정의', null, '부자가 돈으로 정치권력까지 얻는 것을 부정의하다고 본 X. X가 강조한 것은?', null, '복합 평등', array['차등의 원칙', '최소 국가', '절대적 평등'], '{}'::text[], '왈처는 한 영역에서 지배적인 가치가 다른 영역의 가치까지 차지하는 것을 부정의로 보고 복합 평등을 강조했다.', '성신제T · 분배적 정의', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 131),
  ('social-133', 'social', 'choice', '분배적 정의', null, '왈처에 따르면 회사 급여는 A, 안전·복지는 B를 기준으로 분배한다. A–B는?', null, '능력·업적–필요', array['필요–능력·업적', '업적–업적', '필요–필요'], '{}'::text[], '왈처는 이윤 추구 회사는 능력·업적으로, 안전과 복지는 필요를 기준으로 분배해야 한다고 보았다.', '성신제T · 분배적 정의', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 132),
  ('social-134', 'social', 'choice', '분배적 정의', null, '유용성의 원리로 사회 전체 효용을 극대화하려는 X. X가 받는 비판은?', null, '기본권 침해 우려', array['성취동기 약화', '결과 수량화 곤란', '책임 의식 약화'], '{}'::text[], '공리주의는 개인의 기본권을 침해하거나 사회적 약자에 무관심할 수 있다는 비판을 받는다.', '성신제T · 분배적 정의', 4, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 133),
  ('social-135', 'social', 'choice', '분배적 정의', null, '차등의 원칙을 말한 A, 소유 권리론을 말한 B의 재분배 입장은?', null, '찬성–반대', array['반대–찬성', '찬성–찬성', '반대–반대'], '{}'::text[], '롤스는 약자를 위한 재분배를 인정하고, 노직은 재분배가 소유권을 침해한다며 반대한다.', '성신제T · 분배적 정의', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 134),
  ('social-136', 'social', 'choice', '교정적 정의', null, '사기 피해자에게 손해를 배상하는 것은 교정적 정의 중 무엇인가?', null, '배상적 정의', array['형벌적 정의', '분배적 정의', '절차적 정의'], '{}'::text[], '배상적 정의는 손해·손실에 대한 공정한 대응(원상 회복)이고, 형벌적 정의는 범죄에 대한 공정한 처벌이다.', '성신제T · 교정적 정의와 사형', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 135),
  ('social-137', 'social', 'choice', '교정적 정의', null, '처벌 자체를 목적으로 보는 A, 범죄 예방 수단으로 보는 B는?', null, '응보주의–공리주의', array['공리주의–응보주의', '응보주의–응보주의', '사회 계약–응보주의'], '{}'::text[], '응보주의는 정의 실현을 위해 범죄에 상응하는 처벌을, 공리주의(예방주의)는 사회 이익을 위한 범죄 예방을 강조한다.', '성신제T · 교정적 정의와 사형', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 136),
  ('social-138', 'social', 'choice', '교정적 정의', null, '응보주의를 대표하는 사상가 X. X가 형벌의 척도로 본 것은?', null, '동등성의 원리', array['사회에 끼친 해악', '범죄 억제력', '최대 행복'], '{}'::text[], '칸트는 동등성(평등성)의 원리, 즉 보복법만이 형벌의 질과 양을 명확히 제시한다고 보았다.', '성신제T · 교정적 정의와 사형', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 137),
  ('social-139', 'social', 'choice', '교정적 정의', null, '공리주의 처벌관에 대한 비판으로 알맞은 것은?', null, '인간을 수단으로 여김', array['교화에 무관심', '범죄 예방 못 함', '전과자 적응 곤란'], '{}'::text[], '공리주의는 인간을 사회 안정의 수단으로 여겨 존엄성을 훼손한다는 비판을 받는다. 나머지는 응보주의 비판이다.', '성신제T · 교정적 정의와 사형', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 138),
  ('social-140', 'social', 'choice', '교정적 정의', null, '전체 이익을 위해 무고한 사람도 처벌할 수 있다는 비판을 받는 처벌관은?', null, '공리주의', array['응보주의', '사회 계약론', '죄형 법정주의'], '{}'::text[], '공리주의는 유죄를 사회 전체 이익의 관점에서 판단하므로 죄 없는 사람까지 처벌할 수 있다는 문제가 있다.', '성신제T · 교정적 정의와 사형', 1, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 139),
  ('social-141', 'social', 'choice', '교정적 정의', null, '법에 범죄로 규정되지 않으면 처벌할 수 없다는 원칙 X. X의 의의는?', null, '국가 권력의 자기 제한', array['범죄 억제력 강화', '응보의 실현', '교화 기회 확대'], '{}'::text[], '죄형 법정주의는 국민의 자유와 권리를 보장하기 위한 국가 권력의 자기 제한이다.', '성신제T · 교정적 정의와 사형', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 140),
  ('social-142', 'social', 'choice', '교정적 정의', null, '형벌이 범죄 행위에 대한 책임을 초과해서는 안 된다는 원칙은?', null, '비례성의 원칙', array['죄형 법정주의', '동종성 원칙', '일반 예방주의'], '{}'::text[], '비례성의 원칙은 범죄와 형벌 사이에 적정한 균형을 유지해야 한다는 원칙이다.', '성신제T · 교정적 정의와 사형', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 141),
  ('social-143', 'social', 'choice', '교정적 정의', null, '형벌을 정언 명령으로 본 A, 종신 노역형이 낫다고 본 B는?', null, '칸트–베카리아', array['베카리아–칸트', '루소–칸트', '칸트–루소'], '{}'::text[], '칸트는 형벌의 법칙을 정언 명령으로 보았고, 베카리아는 지속적인 종신 노역형이 범죄 예방에 더 효과적이라 했다.', '성신제T · 교정적 정의와 사형', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 142),
