  ('social-180', 'social', 'choice', '사회 불평등', null, '사회적 약자에 대한 차별의 원인으로 옳지 않은 것은?', null, '개인의 능력 부족', array['선입견과 편견', '차별 용인 사회 환경', '주류와 다르다는 이유'], '{}'::text[], '차별은 나이·장애·국적 등에 근거한 선입견·편견과 차별을 용인하는 사회 환경에서 생기며, 능력·업적과 무관하다.', '성신제T · 다양한 불평등 현상', 2, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 179),
  ('social-181', 'social', 'choice', '사회 불평등', null, '불평등을 사회에 불가피하다고 본 A, 지배 집단의 기득권 유지 결과로 본 B는?', null, '기능론–갈등론', array['갈등론–기능론', '기능론–기능론', '갈등론–갈등론'], '{}'::text[], '기능론은 중요한 위치에 능력 있는 사람을 충원하려면 불평등이 불가피하다고 보고, 갈등론은 지배 집단의 기득권 유지 결과로 본다.', '성신제T · 다양한 불평등 현상', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 180),
  ('social-182', 'social', 'choice', '사회 불평등', null, '가치 배분이 구성원의 합의를 반영한다고 보는 관점 X. X가 받는 비판은?', null, '가정 배경 영향 간과', array['순기능 경시', '개인 노력 영향 간과', '직업 중요도 동일시'], '{}'::text[], '기능론은 가정 배경 같은 현실적 영향력과 불평등이 낳는 갈등·소외를 간과한다는 비판을 받는다. 나머지는 갈등론에 대한 비판·주장이다.', '성신제T · 다양한 불평등 현상', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 181),
  ('social-183', 'social', 'choice', '사회 불평등', null, '갈등론의 관점으로 옳지 않은 것은?', null, '적재적소 배치 장치', array['계급 재생산', '집단 간 갈등 유발', '강제적·불공정 배분'], '{}'::text[], '불평등이 개인을 적재적소에 배치하는 사회적 장치라는 것은 기능론의 관점이다.', '성신제T · 다양한 불평등 현상', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 182),
  ('social-184', 'social', 'choice', '사회 불평등', null, '갈등론이 받는 비판 A, 기능론이 받는 비판 B는?', null, '순기능 경시–갈등 경시', array['갈등 경시–순기능 경시', '능력 과장–노력 경시', '합의 경시–강제 경시'], '{}'::text[], '갈등론은 성취동기 유발 같은 순기능을, 기능론은 불평등이 초래하는 대립·갈등과 소외된 사람들의 현실을 경시한다는 비판을 받는다.', '성신제T · 다양한 불평등 현상', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 183),
  ('social-185', 'social', 'choice', '사회 불평등', null, '기능론이 본 불평등의 기능으로 옳지 않은 것은?', null, '양극화 초래', array['성취동기 유발', '적재적소 배치', '사회적 효율성 향상'], '{}'::text[], '기능론은 불평등이 성취동기를 유발하고 적재적소 배치로 효율성을 높인다고 본다. 양극화 초래는 갈등론의 시각이다.', '성신제T · 다양한 불평등 현상', 3, null, 'https://drive.google.com/drive/folders/1etIcuZ7X0n_Y0iHDpN2ckiNnC9mlo0oH', 184),
