  ('biology-jo-033', 'biology-jo', 'choice', '유전 암호와 번역', '조용민T', '세균의 대표적인 개시 아미노산은?', null, 'fMet', array['글리신', '류신', '트립토판'], '{}'::text[], '세균의 개시에는 변형된 메티오닌인 포밀메티오닌(fMet)이 사용된다.', '유전자의 발현 수업자료', 21, null, null, 31),
  ('biology-jo-034', 'biology-jo', 'choice', '유전 암호와 번역', '조용민T', '신장 중 A 자리에 들어오는 것은?', null, '아미노아실-tRNA', array['비어 있는 tRNA만', 'DNA', '히스톤'], '{}'::text[], '다음 코돈에 대응하는 아미노산을 실은 tRNA가 A 자리에 들어온다.', '유전자의 발현 수업자료', 22, null, null, 32),
  ('biology-jo-035', 'biology-jo', 'choice', '유전 암호와 번역', '조용민T', '폴리펩타이드가 신장되는 방향은?', null, 'N말단 → C말단', array['C말단 → N말단', '5′ → 3′ 말단', '3′ → 5′ 말단'], '{}'::text[], '새 아미노산은 사슬의 C말단 쪽에 추가되어 N에서 C로 신장된다.', '유전자의 발현 수업자료', 22, null, null, 33),
  ('biology-jo-036', 'biology-jo', 'choice', '유전 암호와 번역', '조용민T', '번역 신장에서 GTP가 사용되는 과정은?', null, 'tRNA 도입과 리보솜 이동', array['DNA 염기 치환만', 'poly-A 꼬리 합성만', '인트론 절단만'], '{}'::text[], '신장 인자는 GTP를 사용하여 아미노아실-tRNA 도입과 한 코돈씩의 이동을 돕는다.', '유전자의 발현 수업자료', 22, null, null, 34),
  ('biology-jo-037', 'biology-jo', 'choice', '유전 암호와 번역', '조용민T', '종결 코돈을 인식하는 것은?', null, '방출 인자', array['종결 코돈 전용 tRNA', '히스톤', 'σ 인자'], '{}'::text[], '종결 코돈에는 아미노산을 운반하는 tRNA 대신 방출 인자가 작용해 사슬을 방출한다.', '유전자의 발현 수업자료', 23, null, null, 35),
  ('biology-jo-038', 'biology-jo', 'choice', '유전 암호와 번역', '조용민T', '폴리리보솜에 대한 설명은?', null, '한 mRNA를 여러 리보솜이 번역', array['여러 DNA를 한 리보솜이 복제', '한 리보솜에 여러 주형 DNA', '단백질을 RNA로 전환'], '{}'::text[], '여러 리보솜이 한 mRNA를 번역하여 단백질 합성 효율을 높인다.', '유전자의 발현 수업자료', 24, null, null, 36),
  ('biology-jo-039', 'biology-jo', 'choice', '유전 암호와 번역', '조용민T', '원핵에서 전사와 번역의 동시 진행이 가능한 이유는?', null, '핵막으로 분리되지 않기 때문', array['RNA가 필요 없기 때문', '리보솜이 DNA를 번역하기 때문', '전사 방향이 반대이기 때문'], '{}'::text[], '원핵에는 핵막이 없어 전사 중인 mRNA에 리보솜이 결합할 수 있다.', '유전자의 발현 수업자료', 25, null, null, 37),
  ('jo-written-001', 'biology-jo', 'written', '중심원리와 전사', null, '중심원리를 쓰고 전사와 번역의 주형·산물·방향을 구별하시오.', null, '일반적인 정보 흐름은 DNA→RNA→단백질이다. 전사는 DNA 주형을 3′→5′으로 읽어 RNA를 5′→3′으로 합성한다. 번역은 mRNA를 5′→3′으로 읽어 폴리펩타이드를 N말단→C말단으로 합성한다.', '{}'::text[], array['정보 흐름', '전사의 주형·산물·방향', '번역의 주형과 단백질 방향'], '', '유전자의 발현 수업자료', 3, null, null, 1000),
  ('jo-written-002', 'biology-jo', 'written', '전사', null, '원핵 RNA 중합효소의 핵심효소·완전효소·σ 인자의 관계를 설명하시오.', null, '핵심효소는 RNA 합성을 담당하며 σ 인자가 결합하면 완전효소가 된다. σ 인자는 프로모터의 공통서열을 인식해 전사 개시를 돕고 전사가 시작된 뒤 떨어져 나가며 핵심효소가 신장을 계속한다.', '{}'::text[], array['완전효소=핵심효소+σ', '프로모터 인식', '개시 후 σ 이탈'], '', '유전자의 발현 수업자료', 6, null, null, 1001),
  ('jo-written-003', 'biology-jo', 'written', '전사', null, '진핵 RNA 중합효소 I, II, III의 대표적인 산물을 비교하시오.', null, 'I은 주로 인에서 28S·18S·5.8S rRNA 전구체를 합성한다. II는 mRNA와 여러 작은 RNA를 합성한다. III는 tRNA와 5S rRNA 등을 합성한다. 따라서 모든 rRNA가 I에서 만들어지는 것은 아니다.', '{}'::text[], array['I의 세 rRNA', 'II의 mRNA', 'III의 tRNA와 5S rRNA'], '', '유전자의 발현 수업자료', 10, null, null, 1002),
  ('jo-written-004', 'biology-jo', 'written', 'RNA 가공', null, '진핵 pre-mRNA의 세 가지 주요 가공을 각 말단·인트론과 연결하여 설명하시오.', null, '5′ 말단에는 7-메틸구아노신 cap이 붙고 스플라이싱에서는 인트론이 제거되고 엑손이 이어진다. 3′ 쪽 절단 후 PAP가 poly-A 꼬리를 붙인다. 말단 구조는 안정성과 번역 등에 관여하고 스플라이싱은 성숙 RNA 서열을 형성한다.', '{}'::text[], array['5′ cap과 물질', '인트론 제거·엑손 연결', '3′ 절단 및 PAP 꼬리 첨가'], '', '유전자의 발현 수업자료', 13, null, null, 1003),
  ('jo-written-005', 'biology-jo', 'written', '유전 암호와 번역', null, '총 64개 코돈과 아미노산 코돈 61개의 차이 및 동요 가설을 설명하시오.', null, '64개 중 3개는 종결 코돈이며 나머지 61개가 아미노산을 지정한다. 코돈의 세 번째 염기와 안티코돈의 첫 번째 염기 사이에는 유연한 결합이 가능하여 한 tRNA가 여러 코돈을 인식할 수 있으므로 tRNA 종류가 61개보다 적어도 된다.', '{}'::text[], array['종결 코돈 3개', '61개 아미노산 코돈', '동요 위치와 여러 코돈 인식'], '', '유전자의 발현 수업자료', 18, null, null, 1004),
  ('jo-written-006', 'biology-jo', 'written', '유전 암호와 번역', null, 'tRNA에 아미노산이 결합하는 과정과 이 과정이 번역 정확성에 중요한 이유를 설명하시오.', null, '아미노아실-tRNA 합성효소가 ATP로 특정 아미노산을 활성화하고 대응하는 tRNA의 3′ CCA 말단에 부착한다. 코돈 인식은 안티코돈이 담당하지만 실제 운반 아미노산이 맞으려면 이 효소의 정확한 부착이 필요하다.', '{}'::text[], array['ATP와 합성효소', '3′ CCA 말단', '코돈 인식과 아미노산 부착의 구별'], '', '유전자의 발현 수업자료', 17, null, null, 1005),
  ('jo-written-007', 'biology-jo', 'written', '유전 암호와 번역', null, '원핵 번역 개시에서 SD 서열, 16S rRNA, 개시 tRNA의 역할을 설명하시오.', null, 'mRNA의 SD 서열이 소단위 16S rRNA와 상보적으로 결합해 개시 코돈 위치를 맞춘다. fMet을 실은 개시 tRNA가 개시 코돈에 대응하여 P 자리에 놓이고 큰 소단위가 결합해 번역을 진행한다.', '{}'::text[], array['SD–16S 상보 결합', '개시 코돈 위치 설정', 'fMet 개시 tRNA의 P 자리'], '', '유전자의 발현 수업자료', 21, null, null, 1006),
  ('jo-written-008', 'biology-jo', 'written', '유전 암호와 번역', null, '번역 신장의 A·P·E 자리와 GTP 사용을 설명하시오.', null, '다음 아미노아실-tRNA가 A 자리에 들어오고 P 자리의 펩타이드가 A 자리 tRNA의 아미노산으로 옮겨져 펩타이드 결합이 형성된다. 리보솜이 한 코돈 이동하면 펩타이드-tRNA는 P 자리로, 빈 tRNA는 E 자리로 가서 이탈한다. GTP는 tRNA 도입과 이동에 사용된다.', '{}'::text[], array['A 자리 도입', '펩타이드 전달 및 P·E 이동', 'GTP 사용 과정'], '', '유전자의 발현 수업자료', 22, null, null, 1007),
  ('jo-written-009', 'biology-jo', 'written', '유전 암호와 번역', null, '종결 코돈에서 번역이 종료되는 이유를 tRNA, 방출 인자, 가수분해와 연결하시오.', null, '종결 코돈에는 대응하는 아미노아실-tRNA가 없다. 방출 인자가 종결 코돈을 인식하고 물을 이용한 펩타이드-tRNA 연결의 가수분해를 유도하여 폴리펩타이드를 방출하며 리보솜 복합체가 해체된다.', '{}'::text[], array['종결 코돈 대응 tRNA 없음', '방출 인자', '가수분해와 사슬 방출'], '', '유전자의 발현 수업자료', 23, null, null, 1008),
  ('jo-written-010', 'biology-jo', 'written', '유전 암호와 번역', null, '폴리리보솜과 원핵의 전사·번역 동시 진행을 구별하시오.', null, '폴리리보솜은 하나의 mRNA를 여러 리보솜이 동시에 번역하는 것으로 원핵과 진핵 모두에서 가능하다. 전사·번역 동시 진행은 핵막이 없는 원핵에서 전사 중인 RNA를 바로 번역하는 것이다. 진핵에서는 핵의 전사·가공과 세포질 번역이 공간적으로 구분된다.', '{}'::text[], array['한 mRNA와 여러 리보솜', '원핵의 핵막 부재', '진핵의 공간적 구분'], '', '유전자의 발현 수업자료', 25, null, null, 1009),
  ('biology-park-001', 'biology-park', 'choice', '유전의 기본 원리', '박상영T', '상동염색체의 같은 유전자 좌위에 있는 서로 다른 형태의 유전자는?', null, '대립유전자', array['리보솜', '히스톤', '뉴클레오솜'], '{}'::text[], '대립유전자는 같은 좌위에서 특정 형질에 관여하며 두 상동염색체의 대립유전자는 같거나 다를 수 있다.', '박상영T 필기', 1, null, null, 0),
  ('biology-park-002', 'biology-park', 'choice', '유전의 기본 원리', '박상영T', 'Aa와 같은 기호로 나타내는 것은?', null, '유전자형', array['표현형', '대립형질', '염색체 수'], '{}'::text[], '유전자형은 대립유전자의 조합이며 표현형은 관찰되는 특성이다.', '박상영T 필기', 1, null, null, 1),
  ('biology-park-003', 'biology-park', 'choice', '유전의 기본 원리', '박상영T', '완전 우성에서 Aa가 우성 표현형인 이유는?', null, '이형접합에서 우성이 표현되기 때문', array['열성 유전자가 소실되기 때문', 'A만 복제되기 때문', 'a가 자손에게 전달되지 않기 때문'], '{}'::text[], '열성 대립유전자는 없어지지 않고 생식세포로 전달될 수 있다.', '박상영T 필기', 1, null, null, 2),
  ('biology-park-004', 'biology-park', 'choice', '유전의 기본 원리', '박상영T', '각 대립유전자가 같은 확률로 전달될 때 Aa × Aa 자손의 기대 유전자형 비율은?', null, 'AA:Aa:aa = 1:2:1', array['AA:Aa:aa = 3:0:1', 'AA:Aa:aa = 1:1:1', 'AA:Aa:aa = 2:1:1'], '{}'::text[], '각 부모가 A와 a를 같은 확률로 전달하고 무작위로 수정된다고 가정하면 AA 1/4, Aa 1/2, aa 1/4이다. 이는 기대 확률이며, 적은 수의 실제 자손이 반드시 같은 비율로 나오는 것은 아니다.', '박상영T 필기', 1, null, null, 3),
  ('biology-park-005', 'biology-park', 'choice', '유전의 기본 원리', '박상영T', '완전 우성에서 Aa × aa의 우성 표현형 확률은?', null, '1/2', array['1/4', '3/4', '1'], '{}'::text[], 'Aa는 A와 a를 반씩, aa는 a만 전달하므로 Aa와 aa가 1:1이다.', '박상영T 필기', 1, null, null, 4),
  ('biology-park-006', 'biology-park', 'choice', '유전의 기본 원리', '박상영T', '분리의 법칙의 세포학적 근거는?', null, '감수 1분열에서 상동염색체 분리', array['체세포의 세포질 분열만', '수정 시 DNA 분해', '감수 1분열에서 자매염색분체 분리'], '{}'::text[], '상동염색체에 놓인 대립유전자가 감수 1분열에서 서로 분리된다.', '박상영T 필기', 1, null, null, 5),
  ('biology-park-007', 'biology-park', 'choice', '유전의 기본 원리', '박상영T', '유전자 A/a와 B/b가 서로 다른 염색체에 있을 때 AaBb의 생식세포 종류는?', null, 'AB, Ab, aB, ab', array['AA, aa, BB, bb', 'AB, ab만', 'Aa, Bb만'], '{}'::text[], '두 염색체 쌍이 독립적으로 분리되어 네 종류가 각각 1/4이다.', '박상영T 필기', 1, null, null, 6),
  ('biology-park-008', 'biology-park', 'choice', '유전의 기본 원리', '박상영T', '완전 우성·독립 유전인 AaBb × AaBb의 aabb 확률은?', null, '1/16', array['1/4', '3/16', '9/16'], '{}'::text[], 'aa 확률 1/4와 bb 확률 1/4를 곱하면 1/16이다.', '박상영T 필기', 1, null, null, 7),
  ('biology-park-009', 'biology-park', 'choice', '유전의 기본 원리', '박상영T', '완전 우성·독립 유전인 AaBb × aabb의 표현형 비율은?', null, '1:1:1:1', array['9:3:3:1', '3:1', '1:2:1'], '{}'::text[], '검정교배에서는 AaBb가 만드는 네 생식세포가 자손의 표현형에 반영된다.', '박상영T 필기', 1, null, null, 8),
  ('biology-park-010', 'biology-park', 'choice', '유전의 기본 원리', '박상영T', '연관된 두 유전자에 대해 옳은 것은?', null, '같은 염색체에 있어 함께 전달되기 쉬움', array['반드시 독립의 법칙을 따름', '항상 다른 염색체에 존재', '교차가 절대 일어나지 않음'], '{}'::text[], '같은 염색체의 유전자는 연관되지만 교차로 재조합될 수 있다.', '박상영T 필기', 1, null, null, 9),
  ('biology-park-011', 'biology-park', 'choice', '유전의 기본 원리', '박상영T', '자매염색분체와 상동염색체를 옳게 구별한 것은?', null, '자매는 복제 산물, 상동은 부계·모계 한 쌍', array['둘 다 부계·모계 한 쌍', '상동은 한 염색체의 복제 산물', '자매는 항상 서로 다른 좌위를 가짐'], '{}'::text[], '자매염색분체는 DNA 복제 후 연결된 두 가닥이며 상동염색체는 같은 유전자 좌위를 갖는 부계·모계 염색체다.', '박상영T 필기', 1, null, null, 10),
