  ('biology-park-042', 'biology-park', 'choice', '유전체와 유전 물질', '박상영T', '파지 감염 후 혼합·원심분리한 허시·체이스 실험에서 ³²P의 주된 위치는?', null, '세균 침전물', array['파지 껍질 상층액만', '공기 중', '세균 밖 단백질만'], '{}'::text[], 'DNA 표지인 ³²P가 세균이 든 침전물에 주로 검출되어 DNA 유입을 지지했다.', '박상영T 필기', 3, null, null, 41),
  ('biology-park-043', 'biology-park', 'choice', '유전체와 유전 물질', '박상영T', '이중 가닥 DNA에서 A=20%이면 G는?', null, '30%', array['20%', '40%', '60%'], '{}'::text[], 'A=T=20%이므로 G+C=60%, G=C=30%이다.', '박상영T 필기', 3, null, null, 42),
  ('biology-park-044', 'biology-park', 'choice', '유전체와 유전 물질', '박상영T', 'A–T와 G–C의 수소 결합 수는?', null, '2개와 3개', array['3개와 2개', '둘 다 2개', '둘 다 3개'], '{}'::text[], '상보적 염기쌍 A–T는 2개, G–C는 3개의 수소 결합을 형성한다.', '박상영T 필기', 3, null, null, 43),
  ('biology-park-045', 'biology-park', 'choice', '유전체와 유전 물질', '박상영T', 'DNA 한 가닥이 5′-ATGC-3′일 때 마주 보는 가닥은?', null, '3′-TACG-5′', array['3′-ATGC-5′', '5′-TACG-3′', '3′-UACG-5′'], '{}'::text[], 'DNA 두 가닥은 역평행이며 A–T, G–C로 상보 결합한다.', '박상영T 필기', 3, null, null, 44),
  ('biology-park-046', 'biology-park', 'choice', '유전체와 유전 물질', '박상영T', '유전체와 유전자를 옳게 구별한 것은?', null, '유전체에는 비암호화 DNA도 포함', array['유전체는 단백질만의 총합', '유전자는 항상 단백질만 암호화', '유전체는 mRNA만 포함'], '{}'::text[], '유전체는 전체 유전 정보를 뜻하며 유전자는 기능성 RNA 또는 단백질 산물에 필요한 정보를 가진다.', '박상영T 필기', 3, null, null, 45),
  ('biology-park-047', 'biology-park', 'choice', '유전체와 유전 물질', '박상영T', '세균의 전형적인 유전체 특징은?', null, '핵막 없이 원형 DNA를 가짐', array['핵 안에 선형 염색체만 가짐', 'DNA가 전혀 없음', '모든 유전자에 인트론 존재'], '{}'::text[], '세균은 전형적으로 핵막이 없고 주 염색체가 원형이며 진핵생물은 핵에 여러 선형 염색체가 있다.', '박상영T 필기', 3, null, null, 46),
  ('park-term-001', 'biology-park', 'choice', '유전학 핵심 용어', '대립유전자', '대립유전자에 대한 설명으로 옳은 것은?', null, 'A와 a는 같은 좌위의 대립유전자이다.', array['한 개체가 가진 유전자 전체', '한 염색체가 복제된 두 가닥', '서로 다른 좌위의 모든 유전자'], '{}'::text[], '상동염색체의 같은 좌위에 있는 한 유전자의 서로 다른 형태다.', '박상영T · 유전학용어정리(교사용)', 1, null, null, 47),
  ('park-term-002', 'biology-park', 'choice', '유전학 핵심 용어', '상동염색체', '상동염색체에 대한 설명으로 옳은 것은?', null, '부계·모계에서 온 염색체 쌍으로 유전자 좌위가 같다.', array['한 염색체 복제로 생긴 두 염색분체', '모든 염색체가 크기와 형태가 같다', '대립유전자의 형태가 반드시 같아야 한다'], '{}'::text[], '부계와 모계에서 하나씩 받은 염색체 쌍으로, 보통 크기·형태와 유전자 좌위가 대응한다.', '박상영T · 유전학용어정리(교사용)', 1, null, null, 48),
  ('park-term-003', 'biology-park', 'choice', '유전학 핵심 용어', '형질', '형질에 해당하는 것은?', null, '완두의 종자 모양', array['둥근 종자와 주름진 종자의 대비', '상동염색체의 같은 좌위', 'AA와 Aa의 유전자 조합'], '{}'::text[], '생물에서 관찰하거나 측정할 수 있는 특징이다. 완두의 종자 모양처럼 비교하는 특성 자체를 가리킨다.', '박상영T · 유전학용어정리(교사용)', 1, null, null, 49),
  ('park-term-004', 'biology-park', 'choice', '유전학 핵심 용어', '대립형질', '대립형질에 해당하는 것은?', null, '둥근 종자와 주름진 종자', array['종자 모양과 꽃의 색', 'DNA와 RNA', '염색체와 뉴클레오솜'], '{}'::text[], '하나의 형질에서 서로 대비되는 표현 형태다. 예를 들어 종자 모양의 둥근 형태와 주름진 형태가 있다.', '박상영T · 유전학용어정리(교사용)', 1, null, null, 50),
  ('park-term-005', 'biology-park', 'choice', '유전학 핵심 용어', '유전자형', '유전자형에 대한 설명으로 옳은 것은?', null, '특정 형질의 대립유전자 조합', array['관찰되는 겉모습만', '환경에 의해 바뀐 몸무게만', '세포 전체의 단백질 총량'], '{}'::text[], '특정 형질에 관여하는 대립유전자 조합이다. AA·Aa·aa처럼 나타내며 표현형과 구별한다.', '박상영T · 유전학용어정리(교사용)', 1, null, null, 51),
  ('park-term-006', 'biology-park', 'choice', '유전학 핵심 용어', '표현형', '표현형에 대한 설명으로 옳은 것은?', null, '유전자형과 환경의 영향을 받아 관찰되는 형질', array['대립유전자 조합만을 뜻한다', 'DNA 염기서열 전체와 같다', '항상 유전자형과 일대일로 대응한다'], '{}'::text[], '유전자형과 환경의 영향으로 실제 관찰되는 형질의 표현 모습이다. 완전 우성에서 AA와 Aa는 같은 표현형을 보일 수 있다.', '박상영T · 유전학용어정리(교사용)', 2, null, null, 52),
  ('park-term-007', 'biology-park', 'choice', '유전학 핵심 용어', '우성 형질', '우성 형질에 대한 설명으로 옳은 것은?', null, '이형접합체에서 나타나는 형질', array['더 우수한 생존 능력을 가진 형질', '집단에서 반드시 더 흔한 형질', '열성 대립유전자를 없애는 형질'], '{}'::text[], '완전 우성 관계에서 이형접합체에 나타나는 형질이다. 우성이라고 해서 더 좋거나 집단에서 더 흔한 형질이라는 뜻은 아니다.', '박상영T · 유전학용어정리(교사용)', 2, null, null, 53),
  ('park-term-008', 'biology-park', 'choice', '유전학 핵심 용어', '열성 형질', '열성 형질에 대한 설명으로 옳은 것은?', null, '이형접합체에서 드러나지 않아도 대립유전자는 남는다', array['이형접합체에서 대립유전자가 소멸한다', '집단에서 반드시 드물다', '유전될 수 없는 형질이다'], '{}'::text[], '완전 우성 관계에서 이형접합체에는 나타나지 않고 열성 동형접합체에 나타나는 형질이다. 이형접합체에서도 열성 대립유전자는 유지된다.', '박상영T · 유전학용어정리(교사용)', 2, null, null, 54),
  ('park-term-009', 'biology-park', 'choice', '유전학 핵심 용어', '분리의 법칙', '분리의 법칙에 대한 설명으로 옳은 것은?', null, 'Aa는 A 또는 a 하나만 가진 생식세포를 만든다', array['A와 a가 항상 함께 생식세포에 들어간다', '모든 유전자가 같은 염색체에 있다', '수정 때만 대립유전자가 처음 생긴다'], '{}'::text[], '감수분열로 생식세포가 형성될 때 한 쌍의 대립유전자가 분리되어 서로 다른 생식세포에 들어간다.', '박상영T · 유전학용어정리(교사용)', 2, null, null, 55),
  ('park-term-010', 'biology-park', 'choice', '유전학 핵심 용어', '독립의 법칙', '독립의 법칙에 대한 설명으로 옳은 것은?', null, '서로 다른 염색체의 유전자 쌍이 독립적으로 분리된다', array['같은 염색체의 모든 유전자가 항상 독립이다', '생식세포 하나에 두 대립유전자가 모두 들어간다', '우성 대립유전자만 전달된다'], '{}'::text[], '서로 독립적으로 분리되는 유전자 쌍은 한 쌍의 분리가 다른 쌍의 분리에 영향을 주지 않는다. 서로 다른 염색체에 있는 유전자에서 적용되며 연관 유전은 주의한다.', '박상영T · 유전학용어정리(교사용)', 2, null, null, 56),
  ('park-term-011', 'biology-park', 'choice', '유전학 핵심 용어', '단일유전자유전', '단일유전자유전에 대한 설명으로 옳은 것은?', null, '하나의 유전자 좌위가 주로 형질을 결정한다', array['여러 좌위가 반드시 함께 결정한다', '항상 중간 표현형만 나타난다', '오직 성염색체에서만 나타난다'], '{}'::text[], '한 유전자 좌위가 주로 한 형질을 결정하는 유전이다. 우열 관계에 따라 완전 우성·불완전 우성·공동 우성이 나타날 수 있다.', '박상영T · 유전학용어정리(교사용)', 2, null, null, 57),
  ('park-term-012', 'biology-park', 'choice', '유전학 핵심 용어', '다유전자유전', '다유전자유전에 대한 설명으로 옳은 것은?', null, '여러 유전자 좌위가 하나의 형질에 관여한다', array['한 개인이 한 좌위에 세 대립유전자를 가진다', '한 유전자가 여러 염색체로 분리된다', '환경이 유전자 없이 형질을 모두 결정한다'], '{}'::text[], '여러 유전자 좌위가 하나의 형질에 함께 관여하는 유전이다. 키처럼 연속적인 변이를 보이기 쉬우며 환경의 영향도 받을 수 있다.', '박상영T · 유전학용어정리(교사용)', 2, null, null, 58),
  ('park-term-013', 'biology-park', 'choice', '유전학 핵심 용어', '상염색체 유전', '상염색체 유전에 대한 설명으로 옳은 것은?', null, '관련 유전자가 상염색체에 있다', array['관련 유전자가 반드시 X에 있다', '관련 유전자가 반드시 Y에 있다', '아버지에서 아들에게만 전달된다'], '{}'::text[], '형질에 관여하는 유전자가 상염색체에 있는 유전이다. 성염색체 유전과 구별하며 성별만으로 전달 경로를 판단하지 않는다.', '박상영T · 유전학용어정리(교사용)', 2, null, null, 59),
  ('park-term-014', 'biology-park', 'choice', '유전학 핵심 용어', '성염색체 유전', '성염색체 유전에 대한 설명으로 옳은 것은?', null, '유전자가 X 또는 Y에 있어 성별에 따른 전달 양상이 다르다', array['유전자가 모든 상염색체에 있다', '남녀 모두 항상 같은 유전자형이다', '모든 성염색체 유전이 아버지에서 아들에게만 간다'], '{}'::text[], '형질에 관여하는 유전자가 X 또는 Y 성염색체에 있는 유전이다. X 연관 열성과 Y 연관 유전 등 위치와 성별에 따라 전달 양상이 달라진다.', '박상영T · 유전학용어정리(교사용)', 3, null, null, 60),
  ('park-term-015', 'biology-park', 'choice', '유전학 핵심 용어', '복대립유전', '복대립유전에 대한 설명으로 옳은 것은?', null, '집단에는 3종 이상이지만 개인은 그 좌위에 2개를 가진다', array['개인 한 명이 한 좌위에 항상 3개를 가진다', '여러 유전자 좌위가 한 형질에 관여한다', '모든 대립유전자가 한 생식세포에 들어간다'], '{}'::text[], '집단에서 한 유전자 좌위에 세 종류 이상의 대립유전자가 존재하는 유전이다. 이배체 개인은 그 좌위에 두 대립유전자만 가지며 ABO 혈액형이 예다.', '박상영T · 유전학용어정리(교사용)', 3, null, null, 61),
  ('park-term-016', 'biology-park', 'choice', '유전학 핵심 용어', '유전체', '유전체에 대한 설명으로 옳은 것은?', null, '유전자와 비암호화 DNA를 포함한 유전 정보 전체', array['한 형질의 대립유전자 조합만', '단백질을 암호화하는 유전자만', '세포가 만든 모든 단백질만'], '{}'::text[], '생물 또는 세포가 가진 유전 정보 전체다. 유전자뿐 아니라 비암호화 DNA도 포함하며 유전자형이라는 말과 구별한다.', '박상영T · 유전학용어정리(교사용)', 3, null, null, 62),
  ('park-term-017', 'biology-park', 'choice', '유전학 핵심 용어', '뉴클레오타이드', '뉴클레오타이드의 구성 성분은?', null, '인산·당·염기', array['인산·아미노산·염기', '히스톤·당·염기', '당·단백질·지질'], '{}'::text[], '핵산을 구성하는 기본 단위로 인산·당·염기가 1:1:1로 결합한다. DNA의 당은 디옥시리보스, RNA의 당은 리보스다.', '박상영T · 유전학용어정리(교사용)', 3, null, null, 63),
  ('park-term-018', 'biology-park', 'choice', '유전학 핵심 용어', '뉴클레오솜', '뉴클레오솜에 대한 설명으로 옳은 것은?', null, '히스톤 코어를 감은 DNA', array['인산·당·염기로 된 핵산 단량체', '아미노산을 운반하는 RNA', '상동염색체가 접합한 쌍'], '{}'::text[], 'DNA가 히스톤 단백질 코어를 감아 형성한 염색질의 기본 포장 단위다. 핵산의 단량체인 뉴클레오타이드와 구별한다.', '박상영T · 유전학용어정리(교사용)', 3, null, null, 64),
  ('park-term-019', 'biology-park', 'choice', '유전학 핵심 용어', '상보결합', '상보결합에 대한 설명으로 옳은 것은?', null, 'A–T 2개, G–C 3개 수소결합', array['A–G 2개, T–C 3개 수소결합', 'A–T 3개, G–C 2개 수소결합', 'DNA에서 A–U만 결합한다'], '{}'::text[], 'DNA에서 A–T, G–C가 선택적으로 짝을 이루는 결합이다. A–T는 수소결합 2개, G–C는 3개이며 두 DNA 가닥은 역평행이다.', '박상영T · 유전학용어정리(교사용)', 3, null, null, 65),
  ('park-term-020', 'biology-park', 'choice', '유전학 핵심 용어', '돌연변이', '돌연변이에 대한 설명으로 옳은 것은?', null, '유전 물질의 염기서열·염색체 구조·수의 변화', array['환경에 따른 모든 일시적 표현형 변화', '유전자 발현량의 변화만', '모든 변화가 반드시 자손에게 전달되는 현상'], '{}'::text[], 'DNA 염기서열 또는 염색체의 구조·수에 생긴 변화다. 모든 돌연변이가 표현형을 바꾸는 것은 아니며 생식세포 계열의 변화는 자손에 전달될 수 있다.', '박상영T · 유전학용어정리(교사용)', 3, null, null, 66),
  ('park-term-021', 'biology-park', 'choice', '유전학 핵심 용어', '유전자돌연변이', '유전자돌연변이에 대한 설명으로 옳은 것은?', null, '유전자 수준의 DNA 염기서열 변화', array['염색체 수의 증가만', '뉴클레오솜 포장만 변하는 현상', '표현형이 변하면 항상 성립한다'], '{}'::text[], '유전자 수준에서 DNA 염기서열이 바뀌는 변화다. 치환·삽입·결실 등이 있으며 단백질에 영향을 주거나 영향이 없을 수도 있다.', '박상영T · 유전학용어정리(교사용)', 4, null, null, 67),
  ('park-term-022', 'biology-park', 'choice', '유전학 핵심 용어', '염색체돌연변이', '염색체돌연변이에 대한 설명으로 옳은 것은?', null, '염색체 수 또는 구조의 변화', array['단백질 아미노산 수의 변화만', '모든 RNA 가공의 변화', '대립유전자 분리가 정상인 모든 경우'], '{}'::text[], '염색체 수 또는 구조가 바뀌는 변화다. 수 변화에는 비분리가, 구조 변화에는 결실·중복·역위·전좌 등이 관련된다.', '박상영T · 유전학용어정리(교사용)', 4, null, null, 68),
  ('park-written-001', 'biology-park', 'written', '유전의 기본 원리', null, '상동염색체, 자매염색분체, 대립유전자를 서로 구별해 설명하시오.', null, '상동염색체는 부계와 모계에서 하나씩 받은 염색체 쌍으로 같은 좌위에 유전자가 있다. 자매염색분체는 한 염색체가 복제된 산물이다. 대립유전자는 상동염색체의 같은 좌위에 있는 유전자의 서로 다른 형태다.', '{}'::text[], array['상동염색체의 부계·모계 기원', '자매염색분체가 복제 산물임', '대립유전자의 같은 좌위와 서로 다른 형태'], '', '박상영T 필기', 1, null, null, 1000),
  ('park-written-002', 'biology-park', 'written', '유전의 기본 원리', null, '완전 우성에서 Aa × Aa의 유전자형 비와 표현형 비가 다른 이유를 쓰시오.', null, '각 부모가 A와 a를 각각 1/2 확률로 전달하므로 AA:Aa:aa는 1:2:1이다. AA와 Aa는 모두 우성 표현형을 나타내므로 우성:열성은 3:1이다.', '{}'::text[], array['생식세포 A와 a가 1:1', '유전자형 비 1:2:1', 'AA와 Aa의 같은 표현형 및 3:1'], '', '박상영T 필기', 1, null, null, 1001),
  ('park-written-003', 'biology-park', 'written', '유전의 기본 원리', null, '분리의 법칙과 독립의 법칙의 세포학적 근거를 쓰고, 연관 유전자에서 주의할 점을 설명하시오.', null, '감수 1분열에서 상동염색체가 분리되어 대립유전자가 나뉜다. 서로 다른 염색체 쌍의 배열과 분리는 독립적으로 일어나 두 유전자 쌍의 독립 분리를 설명한다. 같은 염색체에 연관된 유전자에는 단순한 독립 비율을 그대로 적용할 수 없고 교차를 고려해야 한다.', '{}'::text[], array['상동염색체 분리', '서로 다른 쌍의 독립적 배열·분리', '연관과 교차의 조건'], '', '박상영T 필기', 1, null, null, 1002),
  ('park-written-004', 'biology-park', 'written', '유전의 기본 원리', null, '완전 우성·독립 유전인 AaBb × AaBb에서 두 형질 모두 열성일 확률을 계산 과정을 포함해 쓰시오.', null, 'aa가 될 확률은 1/4, bb가 될 확률도 1/4이다. 두 유전자는 독립적으로 유전되므로 곱셈법칙을 적용하면 aabb 확률은 1/4 × 1/4 = 1/16이다.', '{}'::text[], array['각 열성 확률 1/4', '독립 조건에 따른 곱셈', '최종값 1/16'], '', '박상영T 필기', 1, null, null, 1003),
  ('park-written-005', 'biology-park', 'written', '사람의 유전', null, '정상 부모 둘 사이에서 상염색체 열성 유전병 자녀가 태어났다. 부모 유전자형과 정상인 자녀가 보인자일 확률을 설명하시오.', null, '자녀 aa에게 각각 a를 전달한 정상 부모는 둘 다 Aa이다. Aa × Aa에서 AA:Aa:aa는 1:2:1이며 정상 자녀로 조건을 제한하면 AA와 Aa만 남으므로 보인자일 확률은 2/3이다.', '{}'::text[], array['부모 모두 Aa', '자녀 비 1:2:1', '정상 조건부 확률 2/3'], '', '박상영T 필기', 2, null, null, 1004),
  ('park-written-006', 'biology-park', 'written', '사람의 유전', null, 'X 연관 열성에서 보인자 어머니 XᴬXᵃ와 정상 아버지 XᴬY 사이의 아들 중 발병 확률과 전체 자녀 중 발병 확률을 구하시오. 성비는 1:1이다.', null, '아들은 아버지의 Y와 어머니의 X를 받으므로 아들 중 XᵃY가 될 확률은 1/2이다. 딸은 아버지의 정상 X를 받으므로 발병하지 않는다. 전체 자녀에서 발병 확률은 아들일 확률 1/2 × Xᵃ를 받을 확률 1/2 = 1/4이다.', '{}'::text[], array['아들의 X가 모계 유래', '아들 중 1/2', '전체 자녀 중 1/4 및 딸 정상'], '', '박상영T 필기', 2, null, null, 1005),
  ('park-written-007', 'biology-park', 'written', '사람의 유전', null, 'ABO 혈액형의 복대립유전과 공동 우성을 구별하고 Iᴬi × Iᴮi의 자녀 혈액형을 쓰시오.', null, '복대립유전은 집단에 Iᴬ, Iᴮ, i의 세 대립유전자가 존재한다는 뜻이며 개인이 세 개를 모두 갖는다는 뜻은 아니다. Iᴬ와 Iᴮ는 공동 우성으로 AB형에서 두 항원이 발현된다. 교배 자녀는 A, B, AB, O형이 각각 1/4이다.', '{}'::text[], array['집단의 세 대립유전자와 개인의 두 개 구별', 'Iᴬ와 Iᴮ의 공동 우성', '네 혈액형 각각 1/4'], '', '박상영T 필기', 2, null, null, 1006),
  ('park-written-008', 'biology-park', 'written', '사람의 유전', null, '복대립유전과 다유전자유전의 차이를 예를 들어 설명하시오.', null, '복대립유전은 한 유전자 좌위에 집단 수준에서 세 종류 이상 대립유전자가 있는 것으로 ABO 혈액형이 예다. 다유전자유전은 여러 유전자 좌위가 하나의 형질에 기여하는 것으로 키·피부색 등이 예이며 환경도 영향을 줄 수 있다.', '{}'::text[], array['한 좌위의 여러 대립유전자', '여러 좌위의 한 형질 기여', '각 예와 환경 영향'], '', '박상영T 필기', 2, null, null, 1007),
  ('park-written-009', 'biology-park', 'written', '사람의 유전병', null, '한 염색체 쌍의 감수 1분열 비분리와 감수 2분열 한 세포의 비분리가 만드는 생식세포를 비교하시오.', null, '감수 1분열에서는 상동염색체가 분리되지 않아 n+1 두 개와 n−1 두 개가 생긴다. 감수 2분열의 한 세포에서는 자매염색분체가 분리되지 않아 n+1 한 개, n−1 한 개와 정상 n 두 개가 생긴다.', '{}'::text[], array['1분열의 상동염색체 비분리', '2분열의 자매염색분체 비분리', '각 생식세포 종류와 개수'], '', '박상영T 필기', 2, null, null, 1008),
  ('park-written-010', 'biology-park', 'written', '사람의 유전병', null, '염색체 구조 이상 네 가지를 구별해 설명하시오.', null, '결실은 염색체 구간 소실, 중복은 같은 구간의 반복, 역위는 구간의 방향 반전, 전좌는 구간이 다른 비상동염색체로 옮겨지는 것이다.', '{}'::text[], array['결실·중복 구별', '역위의 방향 반전', '전좌의 비상동염색체 이동'], '', '박상영T 필기', 2, null, null, 1009),
  ('park-written-011', 'biology-park', 'written', '사람의 유전병', null, '암호화 구간의 1개 염기 결실과 3개 염기 결실이 번역에 미치는 영향을 비교하시오.', null, '1개 결실은 3염기 단위의 읽는 틀을 바꾸어 뒤쪽 아미노산 서열과 종결 위치를 크게 바꿀 수 있다. 3개 결실은 뒤쪽 읽는 틀을 유지하지만 한 아미노산이 줄거나 결실 경계의 코돈이 달라질 수 있어 단백질 기능에 영향을 줄 수 있다.', '{}'::text[], array['3염기 코돈과 읽는 틀', '1개 결실의 프레임시프트', '3개 결실도 기능 영향 가능'], '', '박상영T 필기', 2, null, null, 1010),
  ('park-written-012', 'biology-park', 'written', '유전체와 유전 물질', null, '그리피스 실험과 에이버리 실험의 결과 및 결론을 구별하시오.', null, '그리피스는 열처리 S형과 살아 있는 R형의 혼합에서 형질전환이 일어남을 보였다. 에이버리는 S형 추출물에서 단백질이나 RNA를 분해해도 형질전환이 일어나지만 DNA를 분해하면 일어나지 않음을 보여 DNA가 형질전환 물질임을 뒷받침했다.', '{}'::text[], array['그리피스의 혼합 조건과 형질전환', 'DNase 처리 결과', 'DNA라는 결론의 근거'], '', '박상영T 필기', 3, null, null, 1011),
  ('park-written-013', 'biology-park', 'written', '유전체와 유전 물질', null, '허시·체이스가 ³²P와 ³⁵S를 사용한 이유, 혼합·원심분리의 목적 및 결과를 설명하시오.', null, 'DNA에는 인이 있고 황이 없으므로 ³²P로, 파지 단백질은 황을 포함하므로 ³⁵S로 표지했다. 혼합은 세균 밖 파지 껍질을 떼고 원심분리는 세균 침전물과 껍질 상층액을 분리한다. ³²P가 주로 세균 쪽에 검출되어 DNA가 세균에 유입되는 유전 물질임을 지지했다.', '{}'::text[], array['각 동위원소의 표지 대상', '혼합과 원심분리의 목적', '침전물 ³²P와 DNA 결론'], '', '박상영T 필기', 3, null, null, 1012),
  ('park-written-014', 'biology-park', 'written', '유전체와 유전 물질', null, '이중 가닥 DNA의 A가 30%일 때 T, G, C 비율을 구하고 두 가닥의 방향과 결합을 설명하시오.', null, '상보 결합으로 A=T, G=C이므로 T는 30%, G와 C는 각각 20%이다. 두 가닥은 역평행으로 한 가닥이 5′→3′이면 맞은편은 3′→5′이다. A–T는 2개, G–C는 3개의 수소 결합을 형성한다.', '{}'::text[], array['T 30%, G와 C 각 20%', '역평행', '염기쌍별 수소 결합 수'], '', '박상영T 필기', 3, null, null, 1013),
  ('park-term-written-001', 'biology-park', 'written', '유전학 핵심 용어', null, 'A와 a가 대립유전자라고 할 수 있는 이유를 좌위와 유전자 형태를 이용해 설명하시오.', null, 'A와 a는 상동염색체의 같은 좌위에 있는 같은 유전자의 서로 다른 형태이므로 대립유전자이다. 한 개체는 AA·Aa·aa 중 하나의 조합을 가진다.', '{}'::text[], array['상동염색체의 같은 좌위', '같은 유전자의 서로 다른 형태', 'AA·Aa·aa 중 적절한 조합 예'], '', '박상영T · 유전학용어정리(교사용)', 1, null, null, 1014),
  ('park-term-written-002', 'biology-park', 'written', '유전학 핵심 용어', null, '상동염색체와 자매염색분체를 기원과 유전자 좌위의 관점에서 구별하시오.', null, '상동염색체는 부계와 모계에서 하나씩 받은 쌍으로 유전자 좌위가 대응하지만 대립유전자는 다를 수 있다. 자매염색분체는 한 염색체가 복제되어 생긴 두 염색분체다.', '{}'::text[], array['상동의 부계·모계 기원', '좌위가 같아도 대립유전자 형태는 다를 수 있음', '자매는 한 염색체의 복제 산물'], '', '박상영T · 유전학용어정리(교사용)', 1, null, null, 1015),
  ('park-term-written-003', 'biology-park', 'written', '유전학 핵심 용어', null, '완두의 종자 모양, 둥근 종자, Aa 중에서 형질 자체를 골라 이유를 쓰시오.', null, '형질 자체는 종자 모양이다. 둥근 종자는 종자 모양이라는 형질의 관찰되는 표현형이고, Aa는 대립유전자 조합인 유전자형이다. 형질은 생물의 관찰·측정 가능한 특징을 뜻한다.', '{}'::text[], array['종자 모양 선택', '둥근 종자는 표현형', 'Aa는 유전자형'], '', '박상영T · 유전학용어정리(교사용)', 1, null, null, 1016),
  ('park-term-written-004', 'biology-park', 'written', '유전학 핵심 용어', null, '종자 모양과 꽃 색, 둥근 종자와 주름진 종자 중 대립형질의 예를 골라 설명하시오.', null, '둥근 종자와 주름진 종자가 대립형질이다. 같은 형질인 종자 모양의 대비되는 표현 형태이기 때문이다. 종자 모양과 꽃 색은 서로 다른 형질이므로 두 개를 대립형질이라고 하지 않는다.', '{}'::text[], array['둥근·주름진 선택', '하나의 형질의 대비되는 형태', '종자 모양·꽃 색은 다른 형질'], '', '박상영T · 유전학용어정리(교사용)', 1, null, null, 1017),
  ('park-term-written-005', 'biology-park', 'written', '유전학 핵심 용어', null, '완전 우성에서 AA와 Aa의 유전자형과 표현형을 비교하시오.', null, 'AA는 우성 동형접합체이고 Aa는 이형접합체이므로 유전자형은 다르다. 그러나 완전 우성에서는 둘 다 우성 형질이 나타나 같은 표현형이다. 따라서 표현형만으로 두 유전자형을 구별할 수 없다.', '{}'::text[], array['AA와 Aa의 조합 차이', '완전 우성에서 같은 표현형', '표현형만으로 구별 불가'], '', '박상영T · 유전학용어정리(교사용)', 1, null, null, 1018),
  ('park-term-written-006', 'biology-park', 'written', '유전학 핵심 용어', null, '유전자형이 같은 두 식물의 키가 다른 환경에서 달라질 수 있는 이유를 표현형과 연결해 쓰시오.', null, '표현형은 유전자형뿐 아니라 환경의 영향도 받아 나타난다. 같은 유전자형이어도 빛·물·영양 공급이 달라지면 키가 달라질 수 있다. 키의 차이가 있다고 반드시 유전자형이 다르다고 결론 내릴 수는 없다.', '{}'::text[], array['표현형에 환경도 관여', '빛·물·영양 등 구체적 예', '표현형 차이만으로 유전자형 차이 단정 불가'], '', '박상영T · 유전학용어정리(교사용)', 2, null, null, 1019),
  ('park-term-written-007', 'biology-park', 'written', '유전학 핵심 용어', null, '“우성 형질은 더 우수하고 더 흔하다”라는 주장을 평가하시오.', null, '우성은 완전 우성 관계에서 이형접합체에 나타난다는 뜻이다. 우수성이나 집단의 빈도와 같은 뜻이 아니다. Aa에서 A에 해당하는 표현형이 보인다는 사실만으로 생존에 유리하거나 더 흔하다고 말할 수 없다.', '{}'::text[], array['이형접합체에서 발현', '우성은 우수성과 무관', '집단 빈도와 동일한 뜻 아님'], '', '박상영T · 유전학용어정리(교사용)', 2, null, null, 1020),
  ('park-term-written-008', 'biology-park', 'written', '유전학 핵심 용어', null, 'Aa에서 열성 형질이 나타나지 않아도 자손에 나타날 수 있는 이유를 쓰시오.', null, 'Aa에서도 열성 대립유전자 a는 없어지지 않고 남아 있다. 감수분열 때 A와 a가 분리되므로 a를 가진 생식세포가 생긴다. 부모 모두 a를 전달해 자손이 aa가 되면 완전 우성에서 열성 표현형이 나타난다.', '{}'::text[], array['a가 유지됨', '감수분열로 a 생식세포 형성', 'aa에서 열성 표현형'], '', '박상영T · 유전학용어정리(교사용)', 2, null, null, 1021),
  ('park-term-written-009', 'biology-park', 'written', '유전학 핵심 용어', null, 'Aa 개체가 만드는 생식세포의 종류와 비율을 분리의 법칙으로 설명하시오.', null, '감수분열에서 한 쌍의 대립유전자 A와 a가 분리되어 서로 다른 생식세포로 들어간다. 정상적인 분리에서는 A와 a 생식세포가 각각 1/2 확률로 형성된다. 한 생식세포에는 이 좌위의 대립유전자 하나가 들어간다.', '{}'::text[], array['A와 a 분리', 'A:a=1:1', '한 좌위의 대립유전자 하나씩'], '', '박상영T · 유전학용어정리(교사용)', 2, null, null, 1022),
  ('park-term-written-010', 'biology-park', 'written', '유전학 핵심 용어', null, 'A/a와 B/b가 서로 다른 염색체에 있을 때 AaBb의 생식세포 종류·확률을 쓰고 적용 조건을 설명하시오.', null, '두 유전자 쌍이 독립적으로 분리되므로 AB·Ab·aB·ab가 각각 1/4 확률로 생긴다. 서로 다른 염색체의 독립적인 배열이 조건이다. 같은 염색체에서 연관된 유전자에 이 결과를 무조건 적용하면 안 된다.', '{}'::text[], array['네 종류 AB·Ab·aB·ab', '각각 1/4', '독립 조건과 연관 유전 주의'], '', '박상영T · 유전학용어정리(교사용)', 2, null, null, 1023),
  ('park-term-written-011', 'biology-park', 'written', '유전학 핵심 용어', null, '한 좌위가 형질을 결정하지만 이형접합체가 중간 표현형인 경우를 단일유전자유전이라고 할 수 있는가? 이유를 쓰시오.', null, '할 수 있다. 단일유전자유전은 형질에 주로 관여하는 좌위가 하나라는 뜻이다. 우열 관계가 완전 우성인지 불완전 우성인지는 별개다. 한 좌위에서 이형접합체가 중간 표현형을 보여도 단일유전자유전에 해당한다.', '{}'::text[], array['한 좌위가 결정', '불완전 우성도 가능', '유전자 수와 우열 관계를 구별'], '', '박상영T · 유전학용어정리(교사용)', 2, null, null, 1024),
  ('park-term-written-012', 'biology-park', 'written', '유전학 핵심 용어', null, '키가 다유전자유전의 예인 이유와 연속적인 변이가 나타나는 원인을 쓰시오.', null, '키에는 여러 유전자 좌위가 함께 관여한다. 여러 대립유전자 조합의 효과가 누적되고 영양 등 환경도 영향을 주므로 다양한 중간값이 나타나기 쉽다. 이것은 한 좌위에 집단의 대립유전자가 여러 종류인 복대립유전과 다르다.', '{}'::text[], array['여러 좌위 관여', '효과 누적·환경과 연속 변이', '복대립유전과 구별'], '', '박상영T · 유전학용어정리(교사용)', 2, null, null, 1025),
  ('park-term-written-013', 'biology-park', 'written', '유전학 핵심 용어', null, '상염색체 유전과 성염색체 유전을 구별하는 기준을 쓰고, 남녀의 발병 빈도만으로 단정하면 안 되는 이유를 쓰시오.', null, '기준은 관련 유전자의 위치가 상염색체인지 X·Y 성염색체인지이다. 상염색체 유전에서도 환경·성별에 따른 발현 차이가 있을 수 있으므로 발병 빈도만으로 단정하지 않는다. 유전자 위치와 가계의 전달 양상을 함께 분석한다.', '{}'::text[], array['유전자 위치가 기준', '빈도만으로 단정 불가', '위치와 가계 분석'], '', '박상영T · 유전학용어정리(교사용)', 2, null, null, 1026),
  ('park-term-written-014', 'biology-park', 'written', '유전학 핵심 용어', null, 'X 연관 열성 형질이 XY인 사람에게 나타나기 쉬운 이유를 XX와 비교하여 쓰시오.', null, 'XY인 사람은 보통 X가 하나이므로 해당 좌위의 열성 대립유전자가 다른 X의 우성 대립유전자에 가려지지 않는다. XX에서는 완전 우성 관계의 이형접합체일 때 열성 형질이 드러나지 않을 수 있다. X의 수와 대립유전자 조합이 발현 차이를 만든다.', '{}'::text[], array['XY의 X 한 개', '다른 X의 우성 대립유전자로 가려지지 않음', 'XX 이형접합체와 비교'], '', '박상영T · 유전학용어정리(교사용)', 3, null, null, 1027),
  ('park-term-written-015', 'biology-park', 'written', '유전학 핵심 용어', null, 'ABO 혈액형의 대립유전자는 집단에 세 종류다. AB형 개인은 왜 세 종류를 모두 갖지 않는지 쓰시오.', null, 'ABO 좌위의 대립유전자는 집단에서 Iᴬ·Iᴮ·i 세 종류이므로 복대립유전이다. 이배체 개인은 상동염색체에서 하나씩 받아 이 좌위에 두 대립유전자만 갖는다. AB형의 유전자형은 IᴬIᴮ이며 i를 함께 갖는 것은 아니다.', '{}'::text[], array['집단의 세 종류', '개인은 두 대립유전자', 'AB형 IᴬIᴮ'], '', '박상영T · 유전학용어정리(교사용)', 3, null, null, 1028),
  ('park-term-written-016', 'biology-park', 'written', '유전학 핵심 용어', null, '유전체와 유전자형을 구별하고, 유전체에 비암호화 DNA가 포함되는지 쓰시오.', null, '유전체는 생물 또는 세포의 유전 정보 전체이며 단백질을 암호화하는 유전자뿐 아니라 비암호화 DNA도 포함한다. 유전자형은 특정 형질에 관여하는 대립유전자 조합이다. 예를 들어 Aa는 유전자형이지 그 개체의 유전체 전체가 아니다.', '{}'::text[], array['유전체는 유전 정보 전체', '비암호화 DNA 포함', '유전자형은 대립유전자 조합'], '', '박상영T · 유전학용어정리(교사용)', 3, null, null, 1029),
  ('park-term-written-017', 'biology-park', 'written', '유전학 핵심 용어', null, '뉴클레오타이드의 세 구성 성분과 DNA·RNA에서 당의 차이를 쓰시오.', null, '뉴클레오타이드는 인산·당·염기가 1:1:1로 결합한 핵산의 기본 단위다. DNA 뉴클레오타이드의 당은 디옥시리보스이고 RNA의 당은 리보스다. 여러 뉴클레오타이드가 연결되어 핵산 사슬을 이루며 단백질의 기본 단위와 구별한다.', '{}'::text[], array['인산·당·염기', '1:1:1 결합', 'DNA 디옥시리보스·RNA 리보스'], '', '박상영T · 유전학용어정리(교사용)', 3, null, null, 1030),
  ('park-term-written-018', 'biology-park', 'written', '유전학 핵심 용어', null, '뉴클레오솜과 뉴클레오타이드를 구성 성분과 역할로 구별하시오.', null, '뉴클레오솜은 DNA가 히스톤 단백질 코어를 감은 구조로 염색질의 기본 포장 단위다. 뉴클레오타이드는 인산·당·염기로 구성된 핵산의 단량체다. 따라서 DNA를 포장하는 구조와 DNA 자체를 이루는 기본 단위를 구별해야 한다.', '{}'::text[], array['DNA·히스톤 코어', '염색질의 포장 단위', '뉴클레오타이드는 핵산 단량체'], '', '박상영T · 유전학용어정리(교사용)', 3, null, null, 1031),
  ('park-term-written-019', 'biology-park', 'written', '유전학 핵심 용어', null, 'DNA 가닥 5′-ATGC-3′에 상보적인 가닥을 방향과 함께 쓰고 염기쌍의 수소결합 수를 설명하시오.', null, '대응하는 상보 가닥은 3′-TACG-5′이다. DNA의 두 가닥은 역평행이므로 방향을 반대로 표시한다. A–T는 수소결합 2개, G–C는 3개를 형성한다. 이 예의 네 염기쌍에서는 총 수소결합 수가 2+2+3+3=10개다.', '{}'::text[], array['3′-TACG-5′', '두 가닥의 역평행', 'A–T 2개·G–C 3개'], '', '박상영T · 유전학용어정리(교사용)', 3, null, null, 1032),
  ('park-term-written-020', 'biology-park', 'written', '유전학 핵심 용어', null, '“모든 돌연변이는 겉모습을 바꾸고 자손에게 전달된다”라는 주장에 반례를 들어 설명하시오.', null, '염기서열이 바뀌어도 같은 아미노산을 지정하거나 기능에 영향이 작으면 표현형이 달라지지 않을 수 있다. 체세포에서만 생긴 변화는 일반적으로 자손에 유전되지 않는다. 자손 전달 가능성을 판단할 때 생식세포 계열의 변화를 구별해야 한다.', '{}'::text[], array['표현형이 안 변할 수 있음', '체세포 변화는 일반적으로 자손에 유전되지 않음', '생식세포 계열 구별'], '', '박상영T · 유전학용어정리(교사용)', 3, null, null, 1033),
  ('park-term-written-021', 'biology-park', 'written', '유전학 핵심 용어', null, '염기 치환과 한 염기 삽입이 단백질에 미칠 수 있는 영향을 유전자돌연변이와 연결해 설명하시오.', null, '둘 다 DNA 염기서열이 바뀌는 유전자돌연변이다. 치환은 같은 아미노산을 지정하거나 다른 아미노산·종결 코돈으로 바꿀 수 있다. 번역되는 부위에 한 염기가 삽입되면 읽는 틀이 바뀌어 뒤쪽 아미노산 서열에 큰 영향을 줄 수 있다.', '{}'::text[], array['둘 다 염기서열 변화', '치환의 다양한 결과', '한 염기 삽입의 틀 이동 가능성'], '', '박상영T · 유전학용어정리(교사용)', 4, null, null, 1034),
  ('park-term-written-022', 'biology-park', 'written', '유전학 핵심 용어', null, '감수분열의 비분리와 염색체 일부의 역위를 수 변화·구조 변화로 구별하시오.', null, '비분리는 염색체가 정상적으로 분리되지 않아 염색체 수가 비정상인 생식세포를 만들 수 있으므로 수 변화와 관련된다. 역위는 염색체 일부가 반대로 연결되는 구조 변화다. 두 현상 모두 염색체돌연변이에 포함되지만 변화의 수준이 다르다.', '{}'::text[], array['비분리와 수 변화', '역위와 구조 변화', '둘 다 염색체돌연변이'], '', '박상영T · 유전학용어정리(교사용)', 4, null, null, 1035),
  ('astronomy-001', 'astronomy-hwang', 'choice', '관측 준비', null, '행성이 뜨고 지는 시각이 날짜마다 달라지게 만드는 각은?', null, '태양과의 이각', array['관측지의 경도', '관측지의 위도', '망원경 배율'], '{}'::text[], '행성의 출몰 시각은 태양과 이루는 각(이각)에 따라 달라진다. 관측 프로그램으로 날짜·시각·방향을 미리 확인한다.', '황윤환T 슬라이드', null, 5, null, 0),
  ('astronomy-002', 'astronomy-hwang', 'choice', '관측 준비', null, '장비를 다 조립하고 보니 행성이 이미 졌다. 미리 확인했어야 할 것은?', null, '관측 가능 시간', array['렌즈 분해 방법', '최대 배율', '파인더 위치'], '{}'::text[], '탐구 순서는 대상 선정 → 프로그램으로 관측 가능한 날짜·시간 확인 → 망원경 설치 → 관측이다.', '황윤환T 슬라이드', null, 4, null, 1),
  ('astronomy-003', 'astronomy-hwang', 'choice', '구조', null, '접안렌즈가 확대할 상을 먼저 맺어 주는 렌즈는?', null, '대물렌즈', array['접안렌즈', '파인더 접안렌즈', '극축망원경 렌즈'], '{}'::text[], '대물렌즈가 빛을 모아 상을 맺고, 접안렌즈가 그 상을 확대한다.', '황윤환T 슬라이드', null, 6, null, 2),
  ('astronomy-004', 'astronomy-hwang', 'choice', '구조', null, '대물렌즈가 맺은 상이 너무 작다. 이 상을 확대하는 부품은?', null, '접안렌즈', array['대물렌즈', '파인더', '극축망원경'], '{}'::text[], '대물렌즈가 맺은 상을 눈으로 확대해 보는 부품이 접안렌즈다.', '황윤환T 슬라이드', null, 6, null, 3),
  ('astronomy-005', 'astronomy-hwang', 'choice', '구조', null, '주망원경 시야에서 대상을 놓쳤다. 넓은 시야로 다시 찾는 장치는?', null, '파인더', array['접안렌즈', '극축망원경', '수준기'], '{}'::text[], '파인더는 배율이 낮고 시야가 넓어 대상을 먼저 찾는 데 쓴다.', '황윤환T 슬라이드', null, 29, null, 4),
  ('astronomy-006', 'astronomy-hwang', 'choice', '관측 순서', null, '대상을 아직 못 찾았다. 배율을 높이기 전에 먼저 넓혀야 할 것은?', null, '시야', array['배율', '초점거리', '구경'], '{}'::text[], '저배율로 넓은 시야를 확보해 대상을 찾은 뒤에 배율을 높인다.', '황윤환T 슬라이드', null, 8, null, 5),
  ('astronomy-007', 'astronomy-hwang', 'choice', '관측 순서', null, '대물렌즈가 맺은 상을 확대하는 렌즈는 주망원경의 어디에 끼울까?', null, '접안부', array['경통 앞쪽', '파인더 다리', '극축 구멍'], '{}'::text[], '상을 확대하는 접안렌즈는 주망원경의 접안부에 끼운다.', '황윤환T 슬라이드', null, 8, null, 6),
  ('astronomy-008', 'astronomy-hwang', 'choice', '관측 준비', null, '삼각대가 기울어 가대가 흔들린다. 가장 먼저 점검할 것은?', null, '바닥의 평탄함', array['접안렌즈 배율', '극축 방위', '렌즈 초점'], '{}'::text[], '삼각대가 가대를 안정적으로 받치려면 평평하고 단단한 바닥에 세워야 한다.', '황윤환T 슬라이드', null, 3, null, 7),
  ('astronomy-009', 'astronomy-hwang', 'choice', '조립 순서', null, '경통을 올리기 전에, 반대쪽 무게를 맡을 부품부터 단다. 이 부품은?', null, '균형추', array['접안렌즈', '파인더', '카메라'], '{}'::text[], '조립 순서는 삼각대 → 가대 → 균형추 → 경통 → 파인더·접안렌즈다.', '황윤환T 슬라이드', null, 4, null, 8),
  ('astronomy-010', 'astronomy-hwang', 'choice', '조립 순서', null, '관측에 쓸 카메라는 어떤 조절을 하기 전에 달아야 할까?', null, '균형 맞추기', array['파인더 초점 맞추기', '후드 펴기', '접안부 청소'], '{}'::text[], '실제로 쓸 카메라와 접안렌즈를 단 상태에서 균형을 맞춘다. 나중에 달면 균형이 다시 깨진다.', '황윤환T 슬라이드', null, 18, null, 9),
  ('astronomy-011', 'astronomy-hwang', 'choice', '조립 순서', null, '균형을 맞췄다. 두 망원경이 같은 곳을 보게 하는 다음 단계는?', null, '파인더 조정', array['가대 설치', '균형추 달기', '삼각대 세우기'], '{}'::text[], '조립 뒤 순서는 균형 맞추기 → 파인더 조정 → 극축 맞추기다.', '황윤환T 슬라이드', null, 4, null, 10),
  ('astronomy-012', 'astronomy-hwang', 'choice', '가대 설치', null, '가대의 좌우 방위 조정 나사 두 개 사이에 끼워지는 것은?', null, '방위각 핀', array['추봉', '캡 볼트', '안전 너트'], '{}'::text[], '삼각대의 방위각 핀이 가대의 방위 조정 나사 사이에 들어가야 좌우 미세 조정을 할 수 있다.', '황윤환T 슬라이드', null, 14, null, 11),
  ('astronomy-013', 'astronomy-hwang', 'choice', '가대 설치', null, '극축을 좌우로 미세 조정할 수 없다. 가대 밑에서 너무 세게 조인 것은?', null, '장착 너트', array['안전 너트', '경통 밴드', '접안부 고정 링'], '{}'::text[], '가대 아래 장착 너트를 너무 조이면 방위 미세 조정이 막힌다. 조정할 여유를 남겨 둔다.', '황윤환T 슬라이드', null, 14, null, 12),
  ('astronomy-014', 'astronomy-hwang', 'choice', '가대 설치', null, '여유 있게 조여 둔 장착 너트는 언제 완전히 잠글까?', null, '극축 조정을 마친 뒤', array['방위각 핀을 넣기 전', '삼각대를 펴기 전', '보관하기 직전'], '{}'::text[], '극축 방위 조정을 마친 다음 장착 너트를 완전히 조인다.', '황윤환T 슬라이드', null, 14, null, 13),
  ('astronomy-015', 'astronomy-hwang', 'choice', '균형추 장착', null, '추봉을 빼낸 뒤, 추봉 자체를 고정하는 부품은?', null, '추봉 클램프', array['안전 너트', '장착 너트', '적경 클램프'], '{}'::text[], '추봉을 인출한 뒤 추봉 클램프를 잠가 추봉을 고정한다.', '황윤환T 슬라이드', null, 15, null, 14),
  ('astronomy-016', 'astronomy-hwang', 'choice', '균형추 장착', null, '끝의 안전 너트를 빼고 균형추를 끼우는 막대는?', null, '추봉', array['경통', '드로튜브', '파인더 다리'], '{}'::text[], '균형추는 추봉에 끼운다. 끼운 뒤에는 끝의 안전 너트를 다시 조인다.', '황윤환T 슬라이드', null, 15, null, 15),
  ('astronomy-017', 'astronomy-hwang', 'choice', '균형추 장착', null, '균형추 고정 나사를 풀기 전, 추가 빠지지 않게 확인할 끝 부품은?', null, '안전 너트', array['렌즈 캡', '접안부 덮개', '후드 캡'], '{}'::text[], '균형추 위치를 바꾸기 전에 추봉 끝 안전 너트가 조여져 있는지 확인한다. 균형추가 떨어지는 것을 막는 부품이다.', '황윤환T 슬라이드', null, 15, null, 16),
  ('astronomy-018', 'astronomy-hwang', 'choice', '균형추 장착', null, '고정 나사는 균형추 위치를 잡는다. 추봉 끝에서 이탈을 막는 것은?', null, '안전 너트', array['추봉 클램프', '장착 너트', '적위 클램프'], '{}'::text[], '고정 나사는 균형추의 위치를, 안전 너트는 추봉 끝에서 균형추가 빠지는 것을 막는다.', '황윤환T 슬라이드', null, 15, null, 17),
  ('astronomy-019', 'astronomy-hwang', 'choice', '경통 장착', null, '경통을 수평으로 얹을 수 있게 받침 방향을 바꿀 때 돌리는 축은?', null, '적위축', array['초점 노브', '후드', '파인더 접안부'], '{}'::text[], '적위축을 돌려 경통 받침을 수평 방향으로 맞춘 뒤 경통을 얹는다.', '황윤환T 슬라이드', null, 16, null, 18),
  ('astronomy-020', 'astronomy-hwang', 'choice', '경통 장착', null, '경통을 고정했더니 겉면이 찌그러졌다. 너무 세게 조인 부품은?', null, '경통 밴드', array['안전 너트', '장착 너트', '추봉 클램프'], '{}'::text[], '경통 밴드를 지나치게 조이면 경통이 변형되거나 광축이 틀어질 수 있다.', '황윤환T 슬라이드', null, 12, null, 19),
  ('astronomy-021', 'astronomy-hwang', 'choice', '클램프', null, '모터 대신 손으로 축을 돌리려면 먼저 풀어야 할 것은?', null, '축 클램프', array['경통 밴드', '장착 너트', '안전 너트'], '{}'::text[], '적경축·적위축을 손으로 움직이려면 해당 축의 클램프를 푼다.', '황윤환T 슬라이드', null, 17, null, 20),
  ('astronomy-022', 'astronomy-hwang', 'choice', '클램프', null, '손으로 돌리던 축을 다시 모터와 연결하려면 잠글 것은?', null, '축 클램프', array['경통 밴드', '추봉 클램프', '접안부 고정 링'], '{}'::text[], '손으로 대상을 넣은 뒤 축 클램프를 다시 잠그면 구동계와 연결된다.', '황윤환T 슬라이드', null, 17, null, 21),
  ('astronomy-023', 'astronomy-hwang', 'choice', '클램프', null, '손으로 대상을 시야에 넣었다. 추적하기 전에 다시 연결할 것은?', null, '모터 구동계', array['파인더 광축', '접안 광학계', '균형추 고정부'], '{}'::text[], '풀었던 축 클램프를 다시 잠가 모터 구동계와 연결해야 추적할 수 있다.', '황윤환T 슬라이드', null, 17, null, 22),
  ('astronomy-024', 'astronomy-hwang', 'choice', '안전', null, '파인더도 빛을 모은다. 파인더로도 직접 겨누면 안 되는 대상은?', null, '태양', array['북극성', '달', '행성'], '{}'::text[], '파인더도 빛을 모으므로 주망원경과 마찬가지로 태양을 직접 보면 안 된다.', '황윤환T 슬라이드', null, 12, null, 23),
