  ('astronomy-jeon-066', 'astronomy-jeon', 'choice', '연주운동', null, '태양이 배경 별 사이를 1년 동안 이동하는 하늘의 길은?', null, '황도', array['일주권', '지평선', '자오선'], '{}'::text[], '황도는 지구 공전 궤도면을 천구까지 연장해 얻는 태양의 연주운동 경로다.', '전효진T · 행성우주과학 6번', 4, null, 'https://drive.google.com/file/d/1dmXS2cDm5NkNQUlKtCq1xhqZbGnqBAO8/view', 65),
  ('astronomy-jeon-067', 'astronomy-jeon', 'choice', '연주운동', null, '황도와 천구 적도가 기울어 만나는 근본 원인은?', null, '자전축의 기울기', array['지구 궤도 이심률', '달의 자전', '관측자의 경도'], '{}'::text[], '지구 자전축이 공전 궤도면의 수직 방향에 대해 약 23.5° 기울어져 황도와 천구 적도도 기울어 만난다.', '전효진T · 행성우주과학 6번', 4, null, 'https://drive.google.com/file/d/1dmXS2cDm5NkNQUlKtCq1xhqZbGnqBAO8/view', 66),
  ('astronomy-jeon-068', 'astronomy-jeon', 'choice', '연주운동', null, '태양 적위가 음수에서 양수로 바뀌며 적도를 지난다. 통과점은?', null, '춘분점', array['추분점', '하지점', '동지점'], '{}'::text[], '태양이 천구 남반구에서 북반구로 이동하며 천구 적도를 지나는 점이 춘분점이다.', '전효진T · 행성우주과학 6번', 4, null, 'https://drive.google.com/file/d/1dmXS2cDm5NkNQUlKtCq1xhqZbGnqBAO8/view', 67),
  ('astronomy-jeon-069', 'astronomy-jeon', 'choice', '연주운동', null, '태양 적위가 양수에서 음수로 바뀌며 적도를 지난다. 통과점은?', null, '추분점', array['춘분점', '하지점', '동지점'], '{}'::text[], '태양이 천구 북반구에서 남반구로 이동하며 천구 적도를 지나는 점이 추분점이다.', '전효진T · 행성우주과학 6번', 4, null, 'https://drive.google.com/file/d/1dmXS2cDm5NkNQUlKtCq1xhqZbGnqBAO8/view', 68),
  ('astronomy-jeon-070', 'astronomy-jeon', 'choice', '연주운동', null, '태양이 춘분점에서 황도를 따라 1/4바퀴 이동했다. 적경은?', null, '6h', array['0h', '12h', '18h'], '{}'::text[], '춘분·하지·추분·동지의 태양 적경은 각각 0h·6h·12h·18h다. 춘분에서 1/4바퀴 뒤는 하지다.', '전효진T · 행성우주과학 6번', 5, null, 'https://drive.google.com/file/d/1dmXS2cDm5NkNQUlKtCq1xhqZbGnqBAO8/view', 69),
  ('astronomy-jeon-071', 'astronomy-jeon', 'choice', '연주운동', null, '태양 적경이 6h다. 자정에 남중하는 별의 적경은?', null, '18h', array['6h', '0h', '12h'], '{}'::text[], '자정에는 태양과 반대 방향, 적경 차이가 약 12h인 별이 남중한다. 6h+12h=18h다.', '전효진T · 행성우주과학 6번', 4, null, 'https://drive.google.com/file/d/1dmXS2cDm5NkNQUlKtCq1xhqZbGnqBAO8/view', 70),
  ('astronomy-jeon-072', 'astronomy-jeon', 'choice', '연주운동', null, '태양 적경이 18h다. 자정 남중 별의 적경은?', null, '6h', array['18h', '12h', '0h'], '{}'::text[], '자정 남중 별은 태양과 적경이 12h 차이 난다. 18h+12h=30h에서 24h를 빼면 6h다.', '전효진T · 행성우주과학 6번', 5, null, 'https://drive.google.com/file/d/1dmXS2cDm5NkNQUlKtCq1xhqZbGnqBAO8/view', 71),
  ('astronomy-jeon-073', 'astronomy-jeon', 'choice', '남중과 계절', null, '위도 35°N, 적위 +10°인 별이 남쪽에서 남중한다. 고도는?', null, '65°', array['45°', '35°', '80°'], '{}'::text[], '남쪽 남중 조건에서 h=90°−φ+δ다. 90°−35°+10°=65°다.', '전효진T · 행성우주과학 6번', 6, null, 'https://drive.google.com/file/d/1dmXS2cDm5NkNQUlKtCq1xhqZbGnqBAO8/view', 72),
  ('astronomy-jeon-074', 'astronomy-jeon', 'choice', '남중과 계절', null, '위도 35°N, 적위 −10°인 별의 남쪽 남중 고도는?', null, '45°', array['65°', '35°', '80°'], '{}'::text[], 'h=90°−φ+δ에 δ=−10°를 넣으면 90°−35°−10°=45°다.', '전효진T · 행성우주과학 6번', 6, null, 'https://drive.google.com/file/d/1dmXS2cDm5NkNQUlKtCq1xhqZbGnqBAO8/view', 73),
  ('astronomy-jeon-075', 'astronomy-jeon', 'choice', '남중과 계절', null, '같은 별을 더 북쪽에서 봤다. 남쪽 남중 고도는?', null, '낮아진다', array['높아진다', '반드시 같다', '항상 90°'], '{}'::text[], '남쪽에서 남중하는 조건을 유지하면 h=90°−φ+δ에서 위도 φ가 커질수록 남중 고도는 낮아진다.', '전효진T · 행성우주과학 6번', 6, null, 'https://drive.google.com/file/d/1dmXS2cDm5NkNQUlKtCq1xhqZbGnqBAO8/view', 74),
  ('astronomy-jeon-076', 'astronomy-jeon', 'choice', '남중과 계절', null, '위도 35°N에서 태양의 남중 고도가 가장 높은 때는?', null, '하지', array['동지', '춘분', '추분'], '{}'::text[], '하지에는 태양 적위가 가장 큰 양수이므로 이 위도에서 남중 고도가 가장 높다.', '전효진T · 행성우주과학 6번', 6, null, 'https://drive.google.com/file/d/1dmXS2cDm5NkNQUlKtCq1xhqZbGnqBAO8/view', 75),
  ('astronomy-jeon-077', 'astronomy-jeon', 'choice', '남중과 계절', null, '우리나라에서 태양이 정동보다 북쪽에서 뜬다. 가능한 날은?', null, '하지', array['동지', '춘분', '추분'], '{}'::text[], '하지 무렵 태양은 북동쪽에서 떠 북서쪽으로 진다. 춘분·추분은 정동·정서, 동지는 남동·남서다.', '전효진T · 행성우주과학 6번', 6, null, 'https://drive.google.com/file/d/1dmXS2cDm5NkNQUlKtCq1xhqZbGnqBAO8/view', 76),
  ('astronomy-jeon-078', 'astronomy-jeon', 'choice', '남중과 계절', null, '우리나라에서 태양이 남동쪽에 뜨고 낮이 짧다. 어느 때인가?', null, '동지', array['하지', '춘분', '추분'], '{}'::text[], '동지에는 태양 적위가 음수이고 일주권의 지평선 위 구간이 짧다. 남동쪽에서 떠 남서쪽으로 진다.', '전효진T · 행성우주과학 6번', 6, null, 'https://drive.google.com/file/d/1dmXS2cDm5NkNQUlKtCq1xhqZbGnqBAO8/view', 77),
  ('astronomy-jeon-079', 'astronomy-jeon', 'choice', '남중과 계절', null, '춘분과 추분, 태양의 남중 고도를 같은 장소에서 비교하면?', null, '같다', array['춘분이 더 높다', '추분이 더 높다', '둘 다 90°'], '{}'::text[], '두 때 모두 태양 적위가 0°다. 같은 장소에서는 남중 고도 90°−위도도 같다.', '전효진T · 행성우주과학 6번', 6, null, 'https://drive.google.com/file/d/1dmXS2cDm5NkNQUlKtCq1xhqZbGnqBAO8/view', 78),
  ('astronomy-jeon-080', 'astronomy-jeon', 'choice', '행성 관측', null, '지구 궤도 안쪽을 도는 행성은 밤새 보일 수 있는가?', null, '없다', array['항상 가능', '충에서 가능', '동구에서 가능'], '{}'::text[], '내행성은 태양에서 크게 떨어지지 않아 주로 해 뜨기 전이나 해 진 뒤에 보인다. 충이나 구의 위치가 되지 않는다.', '전효진T · 행성우주과학 7번', 1, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 79),
  ('astronomy-jeon-081', 'astronomy-jeon', 'choice', '행성 관측', null, '금성이 태양 동쪽에 있다. 어느 시간대에 찾을까?', null, '해 진 뒤', array['해 뜨기 전', '항상 자정', '태양과 동시에만'], '{}'::text[], '태양 동쪽의 내행성은 태양보다 늦게 지므로 초저녁 서쪽 하늘에서 볼 수 있다.', '전효진T · 행성우주과학 7번', 1, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 80),
  ('astronomy-jeon-082', 'astronomy-jeon', 'choice', '행성 관측', null, '금성이 태양 서쪽 최대 이각이다. 찾을 시간·방향은?', null, '새벽 동쪽', array['초저녁 서쪽', '자정 남쪽', '정오 북쪽'], '{}'::text[], '서방 최대 이각의 내행성은 태양보다 먼저 떠 새벽 동쪽 하늘에서 관측한다.', '전효진T · 행성우주과학 7번', 1, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 81),
  ('astronomy-jeon-083', 'astronomy-jeon', 'choice', '행성 관측', null, '금성을 초저녁에 비교적 오래 보려면 어느 위치가 유리한가?', null, '동방 최대 이각', array['서방 최대 이각', '내합', '외합'], '{}'::text[], '동방 최대 이각에서는 내행성이 태양 동쪽으로 가장 멀리 떨어져 초저녁 관측에 유리하다.', '전효진T · 행성우주과학 7번', 4, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 82),
  ('astronomy-jeon-084', 'astronomy-jeon', 'choice', '행성 관측', null, '태양과 지구 사이에 금성이 놓였다. 이 위치 관계는?', null, '내합', array['외합', '충', '동구'], '{}'::text[], '내합에서는 내행성이 태양과 지구 사이에 놓인다. 외합에서는 태양 반대편에 내행성이 놓인다.', '전효진T · 행성우주과학 7번', 1, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 83),
  ('astronomy-jeon-085', 'astronomy-jeon', 'choice', '행성 관측', null, '금성이 태양 너머에 있다. 지구에서 본 관계는?', null, '외합', array['내합', '충', '서구'], '{}'::text[], '외합은 태양이 지구와 내행성 사이에 놓인 배치다. 내행성은 지구에서 태양과 같은 방향에 보인다.', '전효진T · 행성우주과학 7번', 1, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 84),
  ('astronomy-jeon-086', 'astronomy-jeon', 'choice', '행성 관측', null, '금성의 시직경은 크지만 밝은 면이 가늘다. 가까운 위치는?', null, '내합 부근', array['외합 부근', '충 부근', '동구 부근'], '{}'::text[], '내합 부근 금성은 지구와 가까워 시직경이 크지만 햇빛을 받는 면 대부분이 지구 반대편이라 가늘게 보인다.', '전효진T · 행성우주과학 7번', 1, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 85),
  ('astronomy-jeon-087', 'astronomy-jeon', 'choice', '행성 관측', null, '금성은 작게 보이지만 거의 둥글다. 가까운 위치는?', null, '외합 부근', array['내합 부근', '충 부근', '서구 부근'], '{}'::text[], '외합 부근에는 금성이 멀어 시직경은 작고, 지구를 향한 쪽 대부분이 햇빛을 받아 둥근 위상이다.', '전효진T · 행성우주과학 7번', 1, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 86),
  ('astronomy-jeon-088', 'astronomy-jeon', 'choice', '행성 관측', null, '원궤도인 내행성이 최대 이각에 있다. 보이는 밝은 면은?', null, '약 반쪽', array['거의 전부', '거의 없음', '항상 초승 모양'], '{}'::text[], '원궤도에서 최대 이각 시 지구에서 내행성으로 향한 선은 궤도에 접한다. 위상각이 약 90°라 반쪽 위상이다.', '전효진T · 행성우주과학 7번', 1, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 87),
  ('astronomy-jeon-089', 'astronomy-jeon', 'choice', '행성 관측', null, '화성이 태양 반대 방향에 있다. 이각과 위치 관계는?', null, '180°·충', array['0°·합', '90°·동구', '90°·서구'], '{}'::text[], '충에서는 지구가 태양과 외행성 사이에 놓이며 이각은 180°다.', '전효진T · 행성우주과학 7번', 2, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 88),
  ('astronomy-jeon-090', 'astronomy-jeon', 'choice', '행성 관측', null, '외행성이 해 질 무렵 뜨고 자정에 남중한다. 위치는?', null, '충', array['합', '동구', '서구'], '{}'::text[], '충의 외행성은 태양과 반대 방향이라 일몰 무렵 떠 자정에 남중하고 일출 무렵 진다.', '전효진T · 행성우주과학 7번', 2, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 89),
  ('astronomy-jeon-091', 'astronomy-jeon', 'choice', '행성 관측', null, '외행성이 태양 동쪽 90°에 있다. 대략적인 남중 시각은?', null, '18시', array['6시', '12시', '0시'], '{}'::text[], '동구의 외행성은 태양보다 약 6시간 늦게 남중한다. 태양 남중을 12시로 두면 18시다.', '전효진T · 행성우주과학 7번', 2, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 90),
  ('astronomy-jeon-092', 'astronomy-jeon', 'choice', '행성 관측', null, '외행성이 태양 서쪽 90°에 있다. 대략적인 남중 시각은?', null, '6시', array['18시', '12시', '0시'], '{}'::text[], '서구의 외행성은 태양보다 약 6시간 먼저 남중한다. 이상화한 관측 표에서 남중은 6시다.', '전효진T · 행성우주과학 7번', 2, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 91),
  ('astronomy-jeon-093', 'astronomy-jeon', 'choice', '행성 관측', null, '화성이 태양과 거의 같은 시각에 뜨고 진다. 위치 관계는?', null, '합', array['충', '동구', '서구'], '{}'::text[], '합에서는 외행성이 태양과 같은 방향에 있어 함께 뜨고 지며 밤에 관측하기 어렵다.', '전효진T · 행성우주과학 7번', 4, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 92),
  ('astronomy-jeon-094', 'astronomy-jeon', 'choice', '행성 관측', null, '같은 외행성을 가장 크게, 오래 볼 수 있는 위치는?', null, '충 부근', array['합 부근', '동구 부근', '서구 부근'], '{}'::text[], '충 부근 외행성은 지구와 가까워 시직경이 크고 태양 반대편에 있어 밤 동안 관측에 유리하다.', '전효진T · 행성우주과학 7번', 4, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 93),
  ('astronomy-jeon-095', 'astronomy-jeon', 'choice', '행성 관측', null, '지구가 바깥 궤도 행성을 추월한다. 배경 별에 대한 운동은?', null, '역행', array['항상 순행', '일주운동 소멸', '공전 방향 반전'], '{}'::text[], '추월 무렵 시선 방향이 바뀌어 외행성이 배경 별에 대해 역행한다. 행성의 실제 공전 방향이 뒤집히는 것은 아니다.', '전효진T · 행성우주과학 7번', 2, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 94),
  ('astronomy-jeon-096', 'astronomy-jeon', 'choice', '행성 관측', null, '행성이 배경 별에 대해 동쪽에서 서쪽으로 이동한다. 적경은?', null, '감소', array['증가', '항상 0h', '반드시 일정'], '{}'::text[], '역행은 배경 별에 대해 동→서로 이동하여 적경이 감소하는 겉보기 운동이다. 0h 경계를 제외한 구간에서 비교한다.', '전효진T · 행성우주과학 7번', 3, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 95),
  ('astronomy-jeon-097', 'astronomy-jeon', 'choice', '행성 관측', null, '순행과 역행이 바뀌는 순간, 배경 별에 대해 멈춘 듯 보이는 것은?', null, '유', array['합', '충', '남중'], '{}'::text[], '유는 순행과 역행이 전환될 때 행성이 배경 별에 대해 잠시 정지한 듯 보이는 상태다.', '전효진T · 행성우주과학 7번', 3, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 96),
  ('astronomy-jeon-098', 'astronomy-jeon', 'choice', '행성 관측', null, '하루 동안 동→서로 움직였다. 이것만으로 역행이라고 할 수 있나?', null, '없다', array['항상 가능', '금성만 가능', '외행성만 가능'], '{}'::text[], '역행은 날짜에 따른 배경 별 상대 위치의 변화다. 하루의 동→서 일주운동만으로 역행을 판정하지 않는다.', '전효진T · 행성우주과학 7번', 3, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 97),
  ('astronomy-jeon-099', 'astronomy-jeon', 'choice', '행성 관측', null, '내행성의 역행은 어느 위치 관계 부근에 나타나는가?', null, '내합', array['외합', '충', '동구'], '{}'::text[], '내행성은 내합 부근에서 지구에 대한 시선 방향 변화로 역행한다. 외행성은 충 부근에서 역행한다.', '전효진T · 행성우주과학 7번', 2, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 98),
  ('astronomy-jeon-100', 'astronomy-jeon', 'choice', '회합주기', null, '목성이 충에서 다음 충까지 돌아왔다. 측정한 주기는?', null, '회합주기', array['자전 주기', '항성월', '일주 주기'], '{}'::text[], '태양·지구·행성의 상대 배치가 같은 상태로 돌아오는 시간이 회합주기다.', '전효진T · 행성우주과학 7번', 5, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 99),
  ('astronomy-jeon-101', 'astronomy-jeon', 'choice', '회합주기', null, '회합주기를 구하려면 두 행성의 어떤 값 차이를 써야 하나?', null, '공전 각속도', array['자전 속력', '행성 반지름', '남중 고도'], '{}'::text[], '상대 배치가 반복되는 시간은 두 천체의 공전 각속도 차로 정한다. 1/S=|1/P−1/E|다.', '전효진T · 행성우주과학 7번', 6, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 100),
  ('astronomy-jeon-102', 'astronomy-jeon', 'choice', '회합주기', null, '지구 주기 1년, 내행성 주기 0.5년이다. 회합주기는?', null, '1년', array['0.5년', '1.5년', '2년'], '{}'::text[], '1/S=1/0.5−1/1=1이므로 S=1년이다. 같은 단위로 계산한다.', '전효진T · 행성우주과학 7번', 6, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 101),
  ('astronomy-jeon-103', 'astronomy-jeon', 'choice', '회합주기', null, '지구 주기 1년, 외행성 주기 2년이다. 회합주기는?', null, '2년', array['1년', '3년', '0.5년'], '{}'::text[], '1/S=1/1−1/2=1/2이므로 S=2년이다.', '전효진T · 행성우주과학 7번', 6, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 102),
  ('astronomy-jeon-104', 'astronomy-jeon', 'choice', '회합주기', null, '지구 주기 1년, 금성 주기 0.6년이다. 새벽 최대 이각 반복 간격은?', null, '1.5년', array['0.6년', '1년', '2.5년'], '{}'::text[], '1/S=1/0.6−1=2/3이므로 S=1.5년이다. 같은 쪽 최대 이각 배치도 회합주기마다 반복된다.', '전효진T · 행성우주과학 7번', 7, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 103),
  ('astronomy-jeon-105', 'astronomy-jeon', 'choice', '회합주기', null, '외행성의 주기가 지구 주기에 가까워졌다. 회합주기는?', null, '길어진다', array['짧아진다', '항상 1년', '항상 공전 주기와 같음'], '{}'::text[], '공전 주기가 가까워지면 각속도 차가 줄어든다. 상대적으로 한 바퀴 따라잡는 시간이 길어져 회합주기가 커진다.', '전효진T · 행성우주과학 7번', 6, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 104),
  ('astronomy-jeon-106', 'astronomy-jeon', 'choice', '달 관측', null, '달이 한쪽 면만 지구에 보인다. 그 이유가 되는 관계는?', null, '자전 주기=공전 주기', array['달은 자전하지 않음', '달은 공전하지 않음', '자전 주기=지구 자전'], '{}'::text[], '달은 한 바퀴 공전하는 동안 한 바퀴 자전하는 동주기 자전을 한다. 자전하지 않는 것은 아니다.', '전효진T · 행성우주과학 7번', 9, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 105),
  ('astronomy-jeon-107', 'astronomy-jeon', 'choice', '달 관측', null, '달이 지구와 태양 사이에 있다. 지구에서 본 위상은?', null, '삭', array['망', '상현', '하현'], '{}'::text[], '삭에서는 달이 태양과 거의 같은 방향이다. 햇빛을 받는 쪽 대부분이 지구 반대편이라 잘 보이지 않는다.', '전효진T · 행성우주과학 7번', 8, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 106),
  ('astronomy-jeon-108', 'astronomy-jeon', 'choice', '달 관측', null, '태양 반대편의 달이 해 질 때 뜬다. 위상은?', null, '망', array['삭', '상현', '하현'], '{}'::text[], '망의 달은 태양 반대 방향에 있어 밝은 면 전체가 지구 쪽으로 보이며 일몰 무렵 뜬다.', '전효진T · 행성우주과학 7번', 8, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 107),
  ('astronomy-jeon-109', 'astronomy-jeon', 'choice', '달 관측', null, '반달이 초저녁에 남중하고 자정 무렵 진다. 위상은?', null, '상현', array['하현', '삭', '망'], '{}'::text[], '상현달은 태양 동쪽 90°에 있어 정오 무렵 뜨고 초저녁 남중, 자정 무렵 진다.', '전효진T · 행성우주과학 7번', 8, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 108),
  ('astronomy-jeon-110', 'astronomy-jeon', 'choice', '달 관측', null, '반달이 자정 무렵 떠서 새벽에 남중한다. 위상은?', null, '하현', array['상현', '망', '삭'], '{}'::text[], '하현달은 태양 서쪽 90°에 있어 자정 무렵 뜨고 일출 무렵 남중한다.', '전효진T · 행성우주과학 7번', 8, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 109),
  ('astronomy-jeon-111', 'astronomy-jeon', 'choice', '달 관측', null, '초저녁 서쪽 하늘에서 가느다란 달을 봤다. 위상은?', null, '초승달', array['그믐달', '망', '하현'], '{}'::text[], '삭 이후의 초승달은 태양보다 늦게 져 초저녁 서쪽 하늘에 보인다. 그믐달은 새벽 동쪽에서 보인다.', '전효진T · 행성우주과학 7번', 8, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 110),
  ('astronomy-jeon-112', 'astronomy-jeon', 'choice', '달 관측', null, '해 뜨기 전 동쪽에서 가느다란 달을 봤다. 위상은?', null, '그믐달', array['초승달', '상현', '망'], '{}'::text[], '삭 이전의 그믐달은 태양보다 먼저 떠 새벽 동쪽 하늘에서 관측한다.', '전효진T · 행성우주과학 7번', 8, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 111),
  ('astronomy-jeon-113', 'astronomy-jeon', 'choice', '달 관측', null, '같은 시각에 달을 매일 봤다. 배경 별에 대해 이동하는 쪽은?', null, '동쪽', array['서쪽', '항상 북쪽', '항상 남쪽'], '{}'::text[], '달이 지구 주위를 서→동으로 공전하므로 같은 시각의 달은 배경 별에 대해 하루 약 13° 동쪽으로 이동한다.', '전효진T · 행성우주과학 7번', 8, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 112),
  ('astronomy-jeon-114', 'astronomy-jeon', 'choice', '달 관측', null, '달이 매일 동쪽으로 이동한다. 다음 날 월출 시각의 경향은?', null, '더 늦다', array['더 빠르다', '항상 같다', '낮에는 뜨지 않음'], '{}'::text[], '지구가 달 방향을 다시 향하려면 더 자전해야 하므로 월출은 평균적으로 하루 약 50분 늦어진다.', '전효진T · 행성우주과학 7번', 8, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 113),
  ('astronomy-jeon-115', 'astronomy-jeon', 'choice', '달 관측', null, '달이 별을 기준으로 한 바퀴 돌아 제자리다. 이 기간은?', null, '항성월', array['삭망월', '태양일', '회귀년'], '{}'::text[], '항성월은 배경 별을 기준으로 달이 한 바퀴 공전하는 실제 공전 주기다. 약 27.3일이다.', '전효진T · 행성우주과학 7번', 9, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 114),
  ('astronomy-jeon-116', 'astronomy-jeon', 'choice', '달 관측', null, '보름달에서 다음 보름달까지 잰 기간은?', null, '삭망월', array['항성월', '태양일', '항성일'], '{}'::text[], '같은 위상이 반복되는 기간은 삭망월이며 약 29.5일이다. 별 기준의 항성월보다 길다.', '전효진T · 행성우주과학 7번', 9, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 115),
  ('astronomy-jeon-117', 'astronomy-jeon', 'choice', '달 관측', null, '달은 별 기준 한 바퀴를 돌았지만 아직 보름이 아니다. 원인은?', null, '지구도 공전했음', array['달이 자전을 멈춤', '태양이 지구를 공전', '지구가 자전하지 않음'], '{}'::text[], '달이 한 바퀴 도는 동안 지구도 태양 주위를 이동한다. 같은 태양·지구·달 배치를 되찾으려 달이 조금 더 공전해야 한다.', '전효진T · 행성우주과학 7번', 9, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 116),
  ('astronomy-jeon-118', 'astronomy-jeon', 'choice', '달 관측', null, '별 기준 주기와 위상 반복 주기 중 더 긴 달의 주기는?', null, '삭망월', array['항성월', '둘이 같음', '위상에 따라 무작위'], '{}'::text[], '지구의 공전 때문에 위상 배치가 복원될 때까지 추가 시간이 필요하여 삭망월이 항성월보다 길다.', '전효진T · 행성우주과학 7번', 9, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 117),
  ('astronomy-jeon-119', 'astronomy-jeon', 'choice', '달 관측', null, '달의 모양이 변할 때 달 표면에서 햇빛을 받는 비율은 대략?', null, '항상 절반', array['삭에서 0', '망에서 전체', '위상마다 무작위'], '{}'::text[], '일식·월식 등은 제외한다. 달의 절반은 햇빛을 받지만 지구에서 볼 수 있는 밝은 부분의 비율이 바뀐다.', '전효진T · 행성우주과학 7번', 8, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 118),
  ('astronomy-jeon-120', 'astronomy-jeon', 'choice', '달 관측', null, '보름달 뒤 밝은 부분이 줄어든다. 다음 반달의 위상은?', null, '하현', array['상현', '삭', '초승달'], '{}'::text[], '달의 위상은 삭→상현→망→하현→삭 순서다. 보름인 망 이후 밝은 부분이 줄면 하현을 지난다.', '전효진T · 행성우주과학 7번', 8, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 119),
  ('astronomy-jeon-121', 'astronomy-jeon', 'choice', '달 관측', null, '초저녁에 상현달을 봤다. 태양에 대한 달의 위치는?', null, '동쪽 약 90°', array['서쪽 약 90°', '같은 방향', '반대 방향'], '{}'::text[], '상현달은 태양 동쪽으로 약 90° 떨어진다. 하현은 서쪽 약 90°, 망은 반대 방향이다.', '전효진T · 행성우주과학 7번', 8, null, 'https://drive.google.com/file/d/1IXCH6HC9eF3EI-gDLYsQE9FIx8AGCAgg/view', 120),
  ('physics-u06-001', 'physics-ii', 'choice', '06 전기장과 정전기 유도', '물리학Ⅱ · 6단원', '두 점전하 사이의 거리를 2배로 하고 전하량은 유지했다. 전기력의 크기는 처음의 몇 배인가?', null, '1/4배', array['1/2배', '2배', '4배'], '{}'::text[], 'F=k|q₁q₂|/r²이다. 거리를 2배로 하면 분모가 4배이므로 힘은 1/4배가 된다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 87, null, null, 0),
  ('physics-u06-002', 'physics-ii', 'choice', '06 전기장과 정전기 유도', '물리학Ⅱ · 6단원', '두 점전하의 전하량을 각각 2배로 하고 거리는 유지했다. 전기력의 크기는 처음의 몇 배인가?', null, '4배', array['1/4배', '2배', '1/2배'], '{}'::text[], '전하량의 곱이 4배가 되므로 전기력도 4배다. 거리는 바뀌지 않았다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 87, null, null, 1),
  ('physics-u06-003', 'physics-ii', 'choice', '06 전기장과 정전기 유도', '물리학Ⅱ · 6단원', '양전하가 만든 전기장에서 음전하에 작용하는 전기력의 방향은?', null, '전기장과 반대', array['항상 전기장에 수직', '항상 힘이 0', '전기장과 같은 방향'], '{}'::text[], '전기장의 방향은 양의 시험 전하가 받는 힘의 방향이다. F=qE에서 q가 음수이면 힘은 전기장과 반대다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 87, null, null, 2),
  ('physics-u06-004', 'physics-ii', 'choice', '06 전기장과 정전기 유도', '물리학Ⅱ · 6단원', '크기가 같은 양의 점전하 두 개가 일정한 거리에 고정돼 있다. 두 전하의 중점에서 합성 전기장은?', null, '0', array['각 전기장의 합', '왼쪽 방향', '오른쪽 방향'], '{}'::text[], '중점에서 두 전기장의 크기는 같고 방향은 반대이므로 벡터 합이 0이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 87, null, null, 3),
  ('physics-u06-005', 'physics-ii', 'choice', '06 전기장과 정전기 유도', '물리학Ⅱ · 6단원', '크기가 같은 +Q와 −Q가 각각 왼쪽과 오른쪽에 고정돼 있다. 중점의 전기장 방향은?', null, '오른쪽', array['왼쪽', '위쪽', '전기장이 0'], '{}'::text[], '중점에서 +Q의 전기장은 오른쪽, −Q의 전기장도 오른쪽이다. 같은 방향으로 더해진다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 87, null, null, 4),
  ('physics-u06-006', 'physics-ii', 'choice', '06 전기장과 정전기 유도', '물리학Ⅱ · 6단원', '+Q에서 거리 r인 곳의 전기장이 E다. 같은 전하에서 거리 3r인 곳의 전기장 크기는?', null, 'E/9', array['9E', 'E/3', '3E'], '{}'::text[], '점전하의 전기장 크기는 E=k|Q|/r²이므로 거리가 3배이면 전기장은 1/9배다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 87, null, null, 5),
  ('physics-u06-007', 'physics-ii', 'choice', '06 전기장과 정전기 유도', '물리학Ⅱ · 6단원', '정전기적 평형 상태인 도체 내부의 전기장은?', null, '0', array['도체 전체에서 같은 양수', '외부 전기장과 항상 같음', '표면보다 항상 큼'], '{}'::text[], '도체의 자유 전자가 재배치되어 내부 전기장이 0이 된다. 전류가 흐르는 도체와 구별한다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 89, null, null, 6),
  ('physics-u06-008', 'physics-ii', 'choice', '06 전기장과 정전기 유도', '물리학Ⅱ · 6단원', '중성 금속 구에 양전하를 가까이 댔다. 접촉·접지가 없을 때 구의 가까운 쪽과 전체 전하는?', null, '가까운 쪽 음전하·전체 중성', array['가까운 쪽 양전하·전체 중성', '가까운 쪽 음전하·전체 음전하', '가까운 쪽 양전하·전체 양전하'], '{}'::text[], '자유 전자가 양전하 쪽으로 이동한다. 접촉이나 접지로 전하가 출입하지 않았으므로 전체 전하량은 0이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 89, null, null, 7),
  ('physics-u06-009', 'physics-ii', 'choice', '06 전기장과 정전기 유도', '물리학Ⅱ · 6단원', '중성 금속 구에 음전하를 가까이 둔 채 접지했다. 접지를 먼저 끊고 음전하를 치우면 구의 전하는?', null, '양전하', array['음전하', '반드시 중성', '접지와 같은 음전하'], '{}'::text[], '음전하가 전자를 밀어내 접지선을 통해 전자가 빠져나간다. 접지를 먼저 끊으면 전자 부족 상태가 남는다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 89, null, null, 8),
  ('physics-u06-010', 'physics-ii', 'choice', '06 전기장과 정전기 유도', '물리학Ⅱ · 6단원', '절연체를 외부 전기장에 놓았을 때 유전 분극에 대한 설명으로 옳은 것은?', null, '속박된 전하의 분포가 치우친다', array['절연체 내부 전기장이 반드시 0이다', '자유 전자가 도체처럼 멀리 이동한다', '항상 전체 전하량이 증가한다'], '{}'::text[], '유전 분극은 원자·분자에 속박된 전하의 분포가 치우치는 현상이다. 도체의 자유 전자 이동이나 순전하 획득과 구별한다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 90, null, null, 9),
  ('physics-u06-011', 'physics-ii', 'choice', '06 전기장과 정전기 유도', '물리학Ⅱ · 6단원', '정전기장에서 전기력선 두 개가 한 점에서 교차할 수 없는 까닭은?', null, '한 점의 전기장 방향은 하나다', array['전기력선은 반드시 평행하다', '전기력선은 음전하에서만 나온다', '전기장의 크기는 항상 일정하다'], '{}'::text[], '전기력선의 접선은 그 점의 전기장 방향이다. 교차하면 한 점에서 방향이 두 개가 되어 모순이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 88, null, null, 10),
  ('physics-u06-012', 'physics-ii', 'choice', '06 전기장과 정전기 유도', '물리학Ⅱ · 6단원', '같은 균일한 전기장에서 +q를 가진 질량 m, 2m의 두 입자가 받는 가속도 크기의 비 aₘ:a₂ₘ은?', null, '2:1', array['1:2', '1:1', '4:1'], '{}'::text[], '둘 다 같은 전기력 qE를 받는다. a=qE/m이므로 질량 m인 입자의 가속도는 질량 2m인 입자의 2배다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 87, null, null, 11),
  ('physics-u07-001', 'physics-ii', 'choice', '07 저항의 연결과 전기 에너지', '물리학Ⅱ · 7단원', '길이가 L, 단면적이 A인 도선의 저항은 R이다. 같은 재료로 길이 2L, 단면적 2A로 만들면 저항은?', null, 'R', array['2R', 'R/2', '4R'], '{}'::text[], '온도가 같아 비저항이 같을 때 R=ρL/A다. 길이와 단면적의 배율이 같으므로 저항은 유지된다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 99, null, null, 12),
  ('physics-u07-002', 'physics-ii', 'choice', '07 저항의 연결과 전기 에너지', '물리학Ⅱ · 7단원', '3 Ω과 6 Ω 저항을 직렬로 연결했다. 합성 저항은?', null, '9 Ω', array['18 Ω', '2 Ω', '3 Ω'], '{}'::text[], '직렬 연결은 같은 전류가 차례로 흐르므로 합성 저항은 3+6=9 Ω이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 101, null, null, 13),
  ('physics-u07-003', 'physics-ii', 'choice', '07 저항의 연결과 전기 에너지', '물리학Ⅱ · 7단원', '3 Ω과 6 Ω 저항을 병렬로 연결했다. 합성 저항은?', null, '2 Ω', array['3 Ω', '18 Ω', '9 Ω'], '{}'::text[], '1/R=1/3+1/6=1/2이므로 R=2 Ω이다. 병렬 합성 저항은 가장 작은 저항보다 작다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 102, null, null, 14),
  ('physics-u07-004', 'physics-ii', 'choice', '07 저항의 연결과 전기 에너지', '물리학Ⅱ · 7단원', '3 Ω과 6 Ω을 직렬로 연결해 이상적인 18 V 전원에 연결했다. 6 Ω 저항의 전압은?', null, '12 V', array['6 V', '18 V', '9 V'], '{}'::text[], '합성 저항은 9 Ω, 전류는 2 A다. 6 Ω 저항의 전압은 IR=12 V이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 101, null, null, 15),
  ('physics-u07-005', 'physics-ii', 'choice', '07 저항의 연결과 전기 에너지', '물리학Ⅱ · 7단원', '3 Ω과 6 Ω을 병렬로 연결해 이상적인 12 V 전원에 연결했다. 두 저항의 전류 I₃:I₆은?', null, '2:1', array['1:2', '1:1', '4:1'], '{}'::text[], '두 저항의 전압이 12 V로 같으므로 전류는 각각 4 A, 2 A다. 전류는 저항에 반비례한다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 102, null, null, 16),
  ('physics-u07-006', 'physics-ii', 'choice', '07 저항의 연결과 전기 에너지', '물리학Ⅱ · 7단원', '6 Ω 저항에 2 A가 흐른다. 소비 전력은?', null, '24 W', array['36 W', '12 W', '6 W'], '{}'::text[], 'P=I²R=2²×6=24 W다. IR=12는 전압이며 전력과 단위가 다르다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 103, null, null, 17),
  ('physics-u07-007', 'physics-ii', 'choice', '07 저항의 연결과 전기 에너지', '물리학Ⅱ · 7단원', '같은 이상적인 전압에 연결한 저항을 R에서 2R로 바꿨다. 소비 전력은 처음의 몇 배인가?', null, '1/2배', array['4배', '1/4배', '2배'], '{}'::text[], '전압이 일정하면 P=V²/R이므로 저항이 2배일 때 전력은 1/2배다. 전류가 일정한 조건과 구별한다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 103, null, null, 18),
  ('physics-u07-008', 'physics-ii', 'choice', '07 저항의 연결과 전기 에너지', '물리학Ⅱ · 7단원', '이상적인 전류원이 같은 전류를 유지한다. 저항을 R에서 2R로 바꾸면 소비 전력은?', null, '2배', array['1/2배', '4배', '변하지 않음'], '{}'::text[], '전류가 일정하면 P=I²R이므로 저항과 전력이 비례한다. 일정 전압 조건의 결과와 반대다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 103, null, null, 19),
  ('physics-u07-009', 'physics-ii', 'choice', '07 저항의 연결과 전기 에너지', '물리학Ⅱ · 7단원', '20 W의 전력을 3분 동안 소비했다. 소비한 전기 에너지는?', null, '3600 J', array['60 J', '600 J', '400 J'], '{}'::text[], '시간을 180 s로 바꾸면 W=Pt=20×180=3600 J이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 103, null, null, 20),
  ('physics-u07-010', 'physics-ii', 'choice', '07 저항의 연결과 전기 에너지', '물리학Ⅱ · 7단원', '회로의 접점으로 5 A가 들어오고 한 가지로 2 A가 나간다. 다른 한 가지로 나가는 전류는?', null, '3 A', array['10 A', '7 A', '2.5 A'], '{}'::text[], '접점에서 전하가 쌓이지 않으면 유입 전류와 유출 전류의 합이 같다. 5=2+I이므로 I=3 A다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 100, null, null, 21),
  ('physics-u07-011', 'physics-ii', 'choice', '07 저항의 연결과 전기 에너지', '물리학Ⅱ · 7단원', '회로의 저항 양단 전압을 측정할 때 이상적인 전압계의 연결 방법은?', null, '저항과 병렬', array['전원에만 직렬', '회로와 연결하지 않음', '저항과 직렬'], '{}'::text[], '전압계는 측정할 두 점에 병렬로 연결한다. 이상적인 전압계의 저항은 무한대라 회로 전류를 바꾸지 않는다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 100, null, null, 22),
  ('physics-u07-012', 'physics-ii', 'choice', '07 저항의 연결과 전기 에너지', '물리학Ⅱ · 7단원', '전하 12 C가 도선의 한 단면을 4 s 동안 통과했다. 평균 전류는?', null, '3 A', array['48 A', '1/3 A', '8 A'], '{}'::text[], '전류 I=ΔQ/Δt이므로 12/4=3 A이다. 쿨롬을 초로 나누면 암페어다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 100, null, null, 23),
  ('physics-u08-001', 'physics-ii', 'choice', '08 트랜지스터와 축전기', '물리학Ⅱ · 8단원', 'n-p-n 트랜지스터가 정상 증폭하는 상태다. 이미터–베이스와 베이스–컬렉터 접합의 바이어스는?', null, '순방향·역방향', array['역방향·순방향', '순방향·순방향', '역방향·역방향'], '{}'::text[], '증폭 상태에서는 이미터–베이스 접합은 순방향, 베이스–컬렉터 접합은 역방향으로 동작한다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 109, null, null, 24),
  ('physics-u08-002', 'physics-ii', 'choice', '08 트랜지스터와 축전기', '물리학Ⅱ · 8단원', '트랜지스터의 베이스 전류가 0.02 mA, 컬렉터 전류가 2 mA다. 이미터 전류의 크기는?', null, '2.02 mA', array['100 mA', '1.98 mA', '0.04 mA'], '{}'::text[], '세 단자의 전류 관계는 I_E=I_B+I_C다. 따라서 0.02+2=2.02 mA이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 109, null, null, 25),
  ('physics-u08-003', 'physics-ii', 'choice', '08 트랜지스터와 축전기', '물리학Ⅱ · 8단원', '트랜지스터의 I_B=0.04 mA, I_C=4 mA다. 전류 증폭률 β=I_C/I_B는?', null, '100', array['4.04', '4000', '0.01'], '{}'::text[], '같은 단위끼리 나누면 β=4/0.04=100이다. 증폭률은 단위가 없는 비다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 109, null, null, 26),
  ('physics-u08-004', 'physics-ii', 'choice', '08 트랜지스터와 축전기', '물리학Ⅱ · 8단원', '트랜지스터 증폭 회로에 적절한 바이어스 전압을 거는 목적은?', null, '신호가 증폭되는 동작점을 정한다', array['모든 접합을 항상 역방향으로 만든다', '베이스를 도선처럼 단락한다', '입력 신호를 반드시 0으로 만든다'], '{}'::text[], '바이어스는 트랜지스터의 동작점을 정해 입력의 변화가 출력으로 증폭되도록 한다. 부적절하면 신호가 잘릴 수 있다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 110, null, null, 27),
  ('physics-u08-005', 'physics-ii', 'choice', '08 트랜지스터와 축전기', '물리학Ⅱ · 8단원', '평행판 축전기의 면적을 2배, 판 사이 거리를 2배로 했다. 같은 유전체일 때 전기 용량은?', null, '변하지 않음', array['2배', '1/2배', '4배'], '{}'::text[], 'C=εA/d이므로 면적과 거리의 배율이 같으면 전기 용량은 변하지 않는다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 112, null, null, 28),
  ('physics-u08-006', 'physics-ii', 'choice', '08 트랜지스터와 축전기', '물리학Ⅱ · 8단원', '전기 용량 3 μF의 축전기를 4 V로 충전했다. 저장된 전하량의 크기는?', null, '12 μC', array['48 μC', '0.75 μC', '7 μC'], '{}'::text[], 'Q=CV=3 μF×4 V=12 μC다. 전기 용량과 전압을 곱한다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 111, null, null, 29),
  ('physics-u08-007', 'physics-ii', 'choice', '08 트랜지스터와 축전기', '물리학Ⅱ · 8단원', '전기 용량 2 μF의 축전기를 10 V로 충전했다. 저장 에너지는?', null, '100 μJ', array['200 μJ', '10 μJ', '20 μJ'], '{}'::text[], 'U=(1/2)CV²=(1/2)×2 μF×100 V²=100 μJ이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 113, null, null, 30),
  ('physics-u08-008', 'physics-ii', 'choice', '08 트랜지스터와 축전기', '물리학Ⅱ · 8단원', '충전한 축전기를 전원에서 분리했다. 누설 없이 판 사이 거리를 2배로 늘리면 전하량과 전압은?', null, '전하량 일정·전압 2배', array['전하량 1/2배·전압 일정', '전하량 2배·전압 일정', '전하량 일정·전압 1/2배'], '{}'::text[], '분리된 축전기의 Q는 일정하다. C는 1/2배가 되고 V=Q/C는 2배가 된다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 112, null, null, 31),
  ('physics-u08-009', 'physics-ii', 'choice', '08 트랜지스터와 축전기', '물리학Ⅱ · 8단원', '축전기를 이상적인 전압원에 계속 연결했다. 판 사이 거리를 2배로 늘리면 전압과 전하량은?', null, '전압 일정·전하량 1/2배', array['전압 2배·전하량 일정', '전압 1/2배·전하량 일정', '전압 일정·전하량 2배'], '{}'::text[], '전압원이 V를 유지한다. C가 1/2배가 되므로 Q=CV도 1/2배다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 112, null, null, 32),
  ('physics-u08-010', 'physics-ii', 'choice', '08 트랜지스터와 축전기', '물리학Ⅱ · 8단원', '2 μF와 3 μF의 이상적인 축전기를 병렬로 연결했다. 합성 전기 용량은?', null, '5 μF', array['0.5 μF', '1.2 μF', '6 μF'], '{}'::text[], '병렬 축전기는 전압이 같고 전하가 더해지므로 합성 용량은 2+3=5 μF다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 112, null, null, 33),
  ('physics-u08-011', 'physics-ii', 'choice', '08 트랜지스터와 축전기', '물리학Ⅱ · 8단원', '2 μF와 3 μF의 이상적인 축전기를 직렬로 연결했다. 합성 전기 용량은?', null, '1.2 μF', array['6 μF', '0.5 μF', '5 μF'], '{}'::text[], '직렬 축전기는 전하량의 크기가 같고 전압이 더해진다. 1/C=1/2+1/3이므로 C=6/5=1.2 μF다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 112, null, null, 34),
  ('physics-u08-012', 'physics-ii', 'choice', '08 트랜지스터와 축전기', '물리학Ⅱ · 8단원', '충전 후 전원에서 분리한 축전기에 유전체를 채워 용량이 3배가 됐다. 전압과 저장 에너지는?', null, '둘 다 1/3배', array['둘 다 3배', '전압 일정·에너지 3배', '전압 1/3배·에너지 일정'], '{}'::text[], 'Q가 일정할 때 V=Q/C, U=Q²/(2C)다. C가 3배이면 V와 U는 모두 1/3배다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 113, null, null, 35),
  ('physics-u09-001', 'physics-ii', 'choice', '09 전류에 의한 자기장', '물리학Ⅱ · 9단원', '긴 직선 도선에 같은 전류가 흐른다. 도선에서 거리가 r에서 2r로 늘면 자기장 크기는?', null, '1/2배', array['1/4배', '2배', '4배'], '{}'::text[], '긴 직선 전류의 자기장은 B=μ₀I/(2πr)이므로 거리에 반비례한다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 123, null, null, 36),
  ('physics-u09-002', 'physics-ii', 'choice', '09 전류에 의한 자기장', '물리학Ⅱ · 9단원', '긴 직선 도선에서 관찰점 거리는 같다. 전류가 3배가 되면 자기장 크기는?', null, '3배', array['변하지 않음', '9배', '1/3배'], '{}'::text[], 'B=μ₀I/(2πr)에서 r이 일정하면 B는 전류 I에 비례한다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 123, null, null, 37),
  ('physics-u09-003', 'physics-ii', 'choice', '09 전류에 의한 자기장', '물리학Ⅱ · 9단원', '종이면을 뚫고 나오는 직선 전류의 주위 자기장 방향을 앞에서 보면?', null, '반시계 방향', array['전류와 평행', '도선에서 방사상 바깥', '시계 방향'], '{}'::text[], '오른손 엄지를 전류 방향인 독자 쪽으로 두면 감기는 손가락은 반시계 방향이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 123, null, null, 38),
  ('physics-u09-004', 'physics-ii', 'choice', '09 전류에 의한 자기장', '물리학Ⅱ · 9단원', '평행한 긴 직선 도선 두 개에 같은 방향 전류가 흐른다. 두 도선의 힘은?', null, '서로 끌어당김', array['서로 밀어냄', '항상 힘이 0', '두 도선이 같은 쪽으로 밀림'], '{}'::text[], '같은 방향으로 흐르는 평행 전류는 서로 끌어당긴다. 반대 방향 전류라면 서로 밀어낸다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 124, null, null, 39),
  ('physics-u09-005', 'physics-ii', 'choice', '09 전류에 의한 자기장', '물리학Ⅱ · 9단원', '전류의 크기는 같다. 원형 도선 반지름을 R에서 2R로 바꾸면 중심 자기장은?', null, '1/2배', array['1/4배', '2배', '4배'], '{}'::text[], '원형 전류 중심에서 B=μ₀I/(2R)이므로 반지름에 반비례한다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 125, null, null, 40),
  ('physics-u09-006', 'physics-ii', 'choice', '09 전류에 의한 자기장', '물리학Ⅱ · 9단원', '반지름이 같은 원형 코일의 감은 수를 2배, 전류를 3배로 했다. 중심 자기장은?', null, '6배', array['2/3배', '5배', '3/2배'], '{}'::text[], 'N회 감은 코일의 중심 자기장은 B=μ₀NI/(2R)이므로 N과 I의 곱에 비례한다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 125, null, null, 41),
  ('physics-u09-007', 'physics-ii', 'choice', '09 전류에 의한 자기장', '물리학Ⅱ · 9단원', '긴 솔레노이드의 단위 길이당 감은 수 n을 2배로 했다. 전류가 같을 때 내부 자기장은?', null, '2배', array['4배', '변하지 않음', '1/2배'], '{}'::text[], '이상적으로 긴 솔레노이드 내부의 B=μ₀nI다. n이 2배이면 B도 2배다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 126, null, null, 42),
  ('physics-u09-008', 'physics-ii', 'choice', '09 전류에 의한 자기장', '물리학Ⅱ · 9단원', '긴 솔레노이드의 총 감은 수와 전류는 유지하고 길이를 2배로 했다. 내부 자기장은?', null, '1/2배', array['2배', '4배', '변하지 않음'], '{}'::text[], 'n=N/L이 1/2배가 되므로 B=μ₀nI도 1/2배다. 가장자리 효과는 무시한다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 126, null, null, 43),
  ('physics-u09-009', 'physics-ii', 'choice', '09 전류에 의한 자기장', '물리학Ⅱ · 9단원', '코일 앞면에서 전류가 반시계 방향으로 흐른다. 이 면의 자기극은?', null, 'N극', array['S극', '전류 세기에 따라 N·S가 바뀜', '극이 생기지 않음'], '{}'::text[], '오른손 손가락을 전류 방향으로 감으면 엄지가 앞면 바깥쪽을 가리킨다. 자기장이 나오는 면이 N극이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 125, null, null, 44),
  ('physics-u09-010', 'physics-ii', 'choice', '09 전류에 의한 자기장', '물리학Ⅱ · 9단원', '한 점의 자기장 A는 오른쪽 3 mT, B는 왼쪽 1 mT다. 합성 자기장은?', null, '오른쪽 2 mT', array['왼쪽 4 mT', '오른쪽 4 mT', '왼쪽 2 mT'], '{}'::text[], '자기장은 벡터이므로 반대 방향 성분을 빼면 오른쪽으로 3−1=2 mT다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 123, null, null, 45),
  ('physics-u09-011', 'physics-ii', 'choice', '09 전류에 의한 자기장', '물리학Ⅱ · 9단원', '같은 크기·반대 방향 전류가 흐르는 평행한 긴 두 도선의 중점에서 자기장은?', null, '같은 방향으로 더해진다', array['각각 1/2배로 줄어든다', '전류와 평행한 방향이 된다', '서로 상쇄되어 0이다'], '{}'::text[], '오른손 법칙으로 두 방향을 따로 구한다. 중점에서는 반대 방향 전류가 만드는 자기장이 같은 방향이어서 더해진다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 124, null, null, 46),
  ('physics-u09-012', 'physics-ii', 'choice', '09 전류에 의한 자기장', '물리학Ⅱ · 9단원', '솔레노이드의 전류 방향만 반대로 바꿨다. 내부 자기장에 대한 설명은?', null, '크기 같음·방향 반대', array['크기 2배·방향 같음', '크기 1/2배·방향 같음', '항상 자기장이 0이 됨'], '{}'::text[], '크기는 |I|에 비례하고 방향은 전류 방향으로 정해진다. 전류 크기가 같으면 자기장 크기는 그대로고 방향만 바뀐다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 126, null, null, 47),
  ('physics-u10-001', 'physics-ii', 'choice', '10 전자기 유도와 상호유도', '물리학Ⅱ · 10단원', '균일한 자기장 B가 평면 코일의 면에 수직이다. 면적 A인 코일의 자기 선속 크기는?', null, 'BA', array['B/A', 'A/B', '0'], '{}'::text[], 'Φ=BAcosθ에서 θ는 자기장과 면의 법선 사이 각이다. 면에 수직인 자기장이므로 θ=0°다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 136, null, null, 48),
  ('physics-u10-002', 'physics-ii', 'choice', '10 전자기 유도와 상호유도', '물리학Ⅱ · 10단원', '자기장이 평면 코일의 면과 평행하다. 코일을 지나는 자기 선속은?', null, '0', array['2BA', 'BA', 'BA/2'], '{}'::text[], '면의 법선과 자기장 사이 각은 90°이므로 Φ=BAcos90°=0이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 136, null, null, 49),
  ('physics-u10-003', 'physics-ii', 'choice', '10 전자기 유도와 상호유도', '물리학Ⅱ · 10단원', '20회 감은 코일의 각 고리를 지나는 자기 선속이 0.1 s 동안 0.03 Wb 감소했다. 평균 유도 기전력 크기는?', null, '6 V', array['60 V', '0.15 V', '0.6 V'], '{}'::text[], '|ε|=N|ΔΦ|/Δt=20×0.03/0.1=6 V다. ΔΦ는 한 고리를 지나는 선속 변화다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 136, null, null, 50),
  ('physics-u10-004', 'physics-ii', 'choice', '10 전자기 유도와 상호유도', '물리학Ⅱ · 10단원', '코일을 지나는 종이면 안쪽 자기 선속이 증가한다. 이를 방해하는 유도 전류를 앞에서 보면?', null, '반시계 방향', array['시계 방향', '유도 전류가 흐르지 않음', '자기장 방향으로 직선 전류'], '{}'::text[], '렌츠 법칙에 따라 코일은 바깥쪽 자기장을 만든다. 오른손 법칙으로 바깥쪽 자기장을 만드는 전류는 반시계 방향이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 136, null, null, 51),
  ('physics-u10-005', 'physics-ii', 'choice', '10 전자기 유도와 상호유도', '물리학Ⅱ · 10단원', '종이면 안쪽 자기장이 약해져 코일의 안쪽 선속이 감소한다. 유도 전류를 앞에서 보면?', null, '시계 방향', array['반시계 방향', '항상 전류가 0', '안쪽으로 흐르는 직선 전류'], '{}'::text[], '감소를 방해하려고 안쪽 자기장을 만든다. 안쪽 자기장을 만드는 고리 전류는 시계 방향이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 136, null, null, 52),
  ('physics-u10-006', 'physics-ii', 'choice', '10 전자기 유도와 상호유도', '물리학Ⅱ · 10단원', '막대의 길이 l=0.5 m, 속력 v=4 m/s, 균일한 자기장 B=0.2 T다. 세 방향이 서로 수직일 때 기전력 크기는?', null, '0.4 V', array['0.8 V', '4 V', '0.1 V'], '{}'::text[], '세 방향이 서로 수직인 움직이는 막대의 기전력은 ε=Blv=0.2×0.5×4=0.4 V다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 137, null, null, 53),
  ('physics-u10-007', 'physics-ii', 'choice', '10 전자기 유도와 상호유도', '물리학Ⅱ · 10단원', '동일한 자기장과 속력으로 움직이는 막대의 길이를 2배로 했다. 나머지 조건이 같으면 기전력은?', null, '2배', array['4배', '변하지 않음', '1/2배'], '{}'::text[], 'ε=Blv이므로 유효 길이가 2배이면 기전력도 2배다. 세 방향은 서로 수직이라고 가정한다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 137, null, null, 54),
  ('physics-u10-008', 'physics-ii', 'choice', '10 전자기 유도와 상호유도', '물리학Ⅱ · 10단원', '자기 선속이 변하지 않는 닫힌 코일이 있다. 외부 전원이 없고 초기 전류도 0일 때 유도 전류는?', null, '0', array['항상 반시계 방향', '항상 시계 방향', '자기장 크기에만 비례'], '{}'::text[], '유도 기전력은 선속의 크기 자체가 아니라 변화율에 의해 결정된다. 선속이 일정하면 유도 기전력이 0이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 136, null, null, 55),
  ('physics-u10-009', 'physics-ii', 'choice', '10 전자기 유도와 상호유도', '물리학Ⅱ · 10단원', '상호 인덕턴스 M=0.4 H인 두 코일에서 1차 전류가 0.2 s 동안 3 A 증가했다. 2차 평균 유도 기전력 크기는?', null, '6 V', array['0.24 V', '1.2 V', '15 V'], '{}'::text[], '|ε₂|=M|ΔI₁|/Δt=0.4×3/0.2=6 V다. 코일 사이의 결합 조건은 일정하다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 141, null, null, 56),
  ('physics-u10-010', 'physics-ii', 'choice', '10 전자기 유도와 상호유도', '물리학Ⅱ · 10단원', '이상적인 변압기의 N₁:N₂=2:5다. 1차 교류 전압이 12 V이면 2차 전압은?', null, '30 V', array['12 V', '4.8 V', '60 V'], '{}'::text[], 'V₂/V₁=N₂/N₁=5/2이므로 V₂=30 V다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 142, null, null, 57),
  ('physics-u10-011', 'physics-ii', 'choice', '10 전자기 유도와 상호유도', '물리학Ⅱ · 10단원', '이상적인 변압기에서 2차 전압이 1차의 3배이고 부하가 연결돼 있다. 2차 전류는 1차의 몇 배인가?', null, '1/3배', array['9배', '같음', '3배'], '{}'::text[], '전력 손실이 없으므로 V₁I₁=V₂I₂다. 전압이 3배이면 전류는 1/3배다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 142, null, null, 58),
  ('physics-u10-012', 'physics-ii', 'choice', '10 전자기 유도와 상호유도', '물리학Ⅱ · 10단원', '변압기 1차 코일에 일정한 직류 전류가 흐르는 정상 상태다. 2차 코일에 지속적인 기전력이 생기지 않는 까닭은?', null, '자기 선속이 변하지 않는다', array['1차 코일에 자기장이 없다', '2차 코일의 감은 수가 항상 0이다', '직류에서는 도선의 저항이 없다'], '{}'::text[], '직류를 켜고 끄는 순간에는 과도 현상이 가능하지만, 전류와 선속이 일정한 정상 상태에서는 지속적인 유도 기전력이 없다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 142, null, null, 59),
  ('physics-u11-001', 'physics-ii', 'choice', '11 전자기파의 간섭과 회절', '물리학Ⅱ · 11단원', '위상이 같은 두 파동이 만나 경로차가 파장의 정수배다. 이 점의 간섭은?', null, '보강 간섭', array['상쇄 간섭', '반드시 진폭이 0', '항상 회절만 발생'], '{}'::text[], '동위상 두 파동의 경로차가 mλ이면 위상이 같아져 보강 간섭한다. 상쇄는 (m+1/2)λ다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 152, null, null, 60),
  ('physics-u11-002', 'physics-ii', 'choice', '11 전자기파의 간섭과 회절', '물리학Ⅱ · 11단원', '위상이 같고 진폭이 같은 두 파동이 경로차 λ/2로 만난다. 합성 진폭은?', null, '0', array['각 파동 진폭의 1/2배', '각 파동 진폭의 2배', '각 파동 진폭과 같음'], '{}'::text[], '경로차 λ/2는 위상차 π에 해당한다. 같은 진폭의 파동이 반대 위상으로 만나 상쇄된다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 152, null, null, 61),
  ('physics-u11-003', 'physics-ii', 'choice', '11 전자기파의 간섭과 회절', '물리학Ⅱ · 11단원', '진폭이 3 cm와 1 cm인 두 파동이 반대 위상으로 만난다. 합성 진폭의 크기는?', null, '2 cm', array['0 cm', '3 cm', '4 cm'], '{}'::text[], '반대 위상에서는 두 진폭의 차가 합성 진폭의 크기다. 3−1=2 cm이므로 진폭이 다르면 완전 상쇄되지 않는다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 152, null, null, 62),
  ('physics-u11-004', 'physics-ii', 'choice', '11 전자기파의 간섭과 회절', '물리학Ⅱ · 11단원', '이중 슬릿 실험에서 파장 λ, 스크린 거리 L, 슬릿 간격 d다. 작은 각도일 때 인접 밝은 무늬 간격은?', null, 'λL/d', array['λd/L', 'dL/λ', 'λ/(Ld)'], '{}'::text[], '작은 각도에서 경로차 d sinθ≈dx/L이다. 인접 보강 조건의 차가 λ이므로 Δx=λL/d다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 153, null, null, 63),
  ('physics-u11-005', 'physics-ii', 'choice', '11 전자기파의 간섭과 회절', '물리학Ⅱ · 11단원', '이중 슬릿의 파장과 슬릿 간격은 유지하고 스크린 거리를 2배로 했다. 밝은 무늬 간격은?', null, '2배', array['1/2배', '4배', '변하지 않음'], '{}'::text[], 'Δx=λL/d이므로 L이 2배이면 무늬 간격도 2배다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 153, null, null, 64),
  ('physics-u11-006', 'physics-ii', 'choice', '11 전자기파의 간섭과 회절', '물리학Ⅱ · 11단원', '이중 슬릿의 파장과 스크린 거리는 같다. 슬릿 간격을 2배로 하면 밝은 무늬 간격은?', null, '1/2배', array['변하지 않음', '2배', '4배'], '{}'::text[], 'Δx=λL/d이므로 슬릿 간격 d가 2배이면 무늬 간격은 1/2배다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 153, null, null, 65),
  ('physics-u11-007', 'physics-ii', 'choice', '11 전자기파의 간섭과 회절', '물리학Ⅱ · 11단원', '이중 슬릿의 λ=500 nm, L=2 m, d=0.5 mm다. 인접 밝은 무늬 간격은?', null, '2 mm', array['20 mm', '0.5 mm', '0.2 mm'], '{}'::text[], 'λ=5×10⁻⁷ m, d=5×10⁻⁴ m다. Δx=λL/d=2×10⁻³ m=2 mm이다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 153, null, null, 66),
  ('physics-u11-008', 'physics-ii', 'choice', '11 전자기파의 간섭과 회절', '물리학Ⅱ · 11단원', '같은 폭의 틈을 지나는 파동에서 파장이 길어졌다. 회절 정도는?', null, '더 커진다', array['더 작아진다', '파장과 무관하다', '회절이 없어지고 간섭만 한다'], '{}'::text[], '틈의 폭에 대한 파장의 비가 클수록 회절이 잘 나타난다. 틈의 폭을 일정하게 두었다는 조건이 중요하다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 156, null, null, 67),
  ('physics-u11-009', 'physics-ii', 'choice', '11 전자기파의 간섭과 회절', '물리학Ⅱ · 11단원', '같은 파장으로 관측하는 망원경의 구경을 크게 했다. 회절로 인한 각 분해능은?', null, '최소 구분 각도가 작아진다', array['최소 구분 각도가 커진다', '항상 두 별이 한 점이 된다', '빛의 파장이 자동으로 짧아진다'], '{}'::text[], '구경이 커지면 회절에 의한 퍼짐이 줄어 가까운 두 별을 더 잘 구별한다. 분해 가능한 최소 각도가 작아진다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 157, null, null, 68),
  ('physics-u11-010', 'physics-ii', 'choice', '11 전자기파의 간섭과 회절', '물리학Ⅱ · 11단원', '단일 슬릿의 폭을 줄이고 빛의 파장과 스크린 거리는 유지했다. 중앙의 밝은 회절 무늬 폭은?', null, '넓어진다', array['변하지 않는다', '좁아진다', '반드시 사라진다'], '{}'::text[], '단일 슬릿의 중앙 밝은 무늬 폭은 작은 각도에서 약 2λL/a다. 슬릿 폭 a가 작아지면 중앙 무늬는 넓어진다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 155, null, null, 69),
  ('physics-u11-011', 'physics-ii', 'choice', '11 전자기파의 간섭과 회절', '물리학Ⅱ · 11단원', '산 뒤에서 긴 파장의 AM 방송이 짧은 파장의 FM 방송보다 잘 수신되는 현상을 설명하는 주된 파동 성질은?', null, '회절', array['편광', '굴절률 증가', '전자기파 속력 증가'], '{}'::text[], '장애물의 크기에 비해 파장이 길수록 회절이 잘 나타난다. AM 전파는 FM보다 파장이 길어 산 뒤로 돌아 들어가기 쉽다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 157, null, null, 70),
  ('physics-u11-012', 'physics-ii', 'choice', '11 전자기파의 간섭과 회절', '물리학Ⅱ · 11단원', '위상이 같은 두 파동의 경로차가 3λ/2다. 진폭이 같을 때 이 점은?', null, '상쇄 간섭', array['보강 간섭', '중앙 밝은 무늬', '경로차가 0인 점'], '{}'::text[], '3λ/2=(1+1/2)λ이므로 동위상 두 파동은 반대 위상으로 만나 상쇄 간섭한다.', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 문제', 152, null, null, 71),
  ('physics-written-u06-001', 'physics-ii', 'written', '06 전기장과 정전기 유도', null, '같은 크기의 +Q 두 점전하가 x=−a와 x=+a에 고정돼 있다. 원점에서 합성 전기장이 0인 까닭을 크기와 방향으로 설명하시오.', null, '원점에서 각 전하까지 거리는 a이므로 각 전기장의 크기는 kQ/a²로 같다. 왼쪽 양전하의 전기장은 오른쪽, 오른쪽 양전하의 전기장은 왼쪽이다. 서로 반대인 두 벡터가 상쇄되어 합성 전기장은 0이다.', '{}'::text[], array['각 거리와 전기장 크기 같음', '두 전기장 방향 반대', '벡터 합이 0이라는 결론'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 87, null, null, 1000),
  ('physics-written-u06-002', 'physics-ii', 'written', '06 전기장과 정전기 유도', null, '중성 금속 구에 음전하를 가까이 둔 채 접지한다. 접지를 먼저 끊고 음전하를 치웠을 때 구가 띠는 전하와 전자의 이동을 설명하시오.', null, '음전하가 구의 자유 전자를 밀어내므로 접지된 상태에서 전자가 구에서 땅으로 이동한다. 음전하를 둔 채 접지를 먼저 끊으면 전자 부족 상태가 남는다. 이후 음전하를 치워도 구의 전체 전하량은 양수다.', '{}'::text[], array['전자가 땅으로 이동', '접지를 먼저 끊는 순서', '전자 부족과 양전하 연결'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 89, null, null, 1001),
  ('physics-written-u06-003', 'physics-ii', 'written', '06 전기장과 정전기 유도', null, '같은 외부 전기장에서 도체의 정전기 유도와 절연체의 유전 분극을 전하 이동과 전체 전하량 관점에서 비교하시오. 단, 접촉·접지는 없다.', null, '도체에서는 자유 전자가 물체 내부에서 이동하여 표면 전하 분포가 바뀐다. 절연체에서는 속박된 양·음전하 분포가 치우치지만 자유 전자가 도체처럼 물체 전체를 이동하지 않는다. 두 경우 모두 외부와 전하가 출입하지 않으므로 전체 전하량은 변하지 않는다.', '{}'::text[], array['도체 자유 전자의 이동', '절연체 속박 전하 분포 변화', '전하 출입 없을 때 전체 전하량 보존'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 90, null, null, 1002),
  ('physics-written-u07-001', 'physics-ii', 'written', '07 저항의 연결과 전기 에너지', null, '3 Ω과 6 Ω을 병렬로 연결해 12 V 이상적인 전원에 연결했다. 합성 저항, 전체 전류, 각 저항의 전력을 계산하시오.', null, '1/R=1/3+1/6이므로 R=2 Ω이다. 전체 전류는 12/2=6 A다. 각 가지 전류는 4 A와 2 A이며 전력은 V²/R로 각각 48 W와 24 W다. 전력 합 72 W는 전원의 12 V×6 A와 같다.', '{}'::text[], array['합성 저항 2 Ω', '전체 전류 6 A', '각 전력 48 W와 24 W 및 단위'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 103, null, null, 1003),
  ('physics-written-u07-002', 'physics-ii', 'written', '07 저항의 연결과 전기 에너지', null, '저항을 R에서 2R로 바꿀 때 일정 전압 조건과 일정 전류 조건의 전력 변화를 식으로 비교하시오.', null, '전압이 일정하면 P=V²/R이므로 저항이 2배일 때 전력은 1/2배다. 전류가 일정하면 P=I²R이므로 저항이 2배일 때 전력은 2배다. 어떤 양이 일정한지 확인하지 않고 저항만 보고 전력을 판단하면 안 된다.', '{}'::text[], array['일정 전압의 식', '일정 전류의 식', '전력 1/2배와 2배 구별'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 103, null, null, 1004),
  ('physics-written-u07-003', 'physics-ii', 'written', '07 저항의 연결과 전기 에너지', null, '같은 재료·온도인 두 도선 A, B가 있다. B의 길이는 A의 3배, 단면적은 2배다. 저항비 R_B/R_A를 유도하시오.', null, 'R=ρL/S이고 재료·온도가 같으므로 비저항 ρ가 같다. R_B/R_A=(L_B/L_A)/(S_B/S_A)=3/2다. 단면적의 배율을 지름의 배율로 혼동하면 안 된다.', '{}'::text[], array['R=ρL/S 사용', '같은 비저항 확인', '저항비 3/2'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 99, null, null, 1005),
  ('physics-written-u08-001', 'physics-ii', 'written', '08 트랜지스터와 축전기', null, 'n-p-n 트랜지스터의 정상 증폭 상태에서 두 접합의 바이어스와 세 단자 전류의 크기 관계를 설명하시오.', null, '이미터–베이스 접합은 순방향, 베이스–컬렉터 접합은 역방향이다. 얇은 베이스를 통과한 전하 운반자의 대부분이 컬렉터로 이동해 작은 베이스 전류로 큰 컬렉터 전류의 변화를 제어한다. 전류 크기는 I_E=I_B+I_C를 만족한다.', '{}'::text[], array['두 접합의 바이어스 구별', '얇은 베이스와 증폭 연결', 'I_E=I_B+I_C'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 109, null, null, 1006),
  ('physics-written-u08-002', 'physics-ii', 'written', '08 트랜지스터와 축전기', null, '충전한 평행판 축전기의 판 사이 거리를 2배로 한다. 전원에서 분리한 경우와 이상적인 전압원에 계속 연결한 경우에 Q, V, U의 배율을 비교하시오.', null, '두 경우 모두 C는 1/2배다. 전원에서 분리하면 Q가 일정하므로 V=Q/C와 U=Q²/(2C)는 각각 2배다. 전압원에 계속 연결하면 V가 일정하므로 Q=CV와 U=CV²/2는 각각 1/2배다. 에너지 변화에는 외부에서 한 일과 전원과의 에너지 교환이 관련된다.', '{}'::text[], array['C가 1/2배', '분리: Q 일정, V·U 2배', '연결: V 일정, Q·U 1/2배'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 113, null, null, 1007),
  ('physics-written-u08-003', 'physics-ii', 'written', '08 트랜지스터와 축전기', null, '2 μF와 3 μF를 직렬로 연결해 10 V로 충전했다. 합성 전기 용량, 각 축전기 전하량의 크기, 각 전압을 계산하시오.', null, '합성 용량은 C=6/5=1.2 μF다. 전체 전하량 Q=CV=12 μC이고 직렬로 연결된 두 축전기의 전하량 크기는 같다. 전압은 각각 Q/C=6 V와 4 V이며 합이 10 V다.', '{}'::text[], array['합성 용량 1.2 μF', '전하량 각 12 μC', '전압 6 V와 4 V'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 112, null, null, 1008),
  ('physics-written-u09-001', 'physics-ii', 'written', '09 전류에 의한 자기장', null, '긴 직선 도선의 전류를 2배로 하고 관찰점의 거리를 4배로 했다. 자기장 크기의 배율을 식으로 구하시오.', null, 'B=μ₀I/(2πr)이므로 B′/B=(I′/I)/(r′/r)=2/4=1/2다. 직선 전류 자기장은 거리에 반비례하며, 점전하 전기장의 거리 제곱 반비례와 구별한다.', '{}'::text[], array['직선 도선 식', '배율 2/4 적용', '자기장 1/2배'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 123, null, null, 1009),
  ('physics-written-u09-002', 'physics-ii', 'written', '09 전류에 의한 자기장', null, '총 감은 수 N과 전류 I를 유지하면서 이상적인 긴 솔레노이드 길이를 2배로 했다. 내부 자기장 변화를 설명하시오.', null, '단위 길이당 감은 수 n=N/L은 1/2배가 된다. B=μ₀nI이므로 전류가 일정할 때 내부 자기장도 1/2배다. 총 감은 수 N이 일정하다는 조건과 n이 일정하다는 조건은 다르다.', '{}'::text[], array['n=N/L', 'n이 1/2배', 'B가 1/2배'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 126, null, null, 1010),
  ('physics-written-u09-003', 'physics-ii', 'written', '09 전류에 의한 자기장', null, '반지름 R인 원형 코일 1회와 같은 반지름의 원형 코일 3회를 비교한다. 전류가 같을 때 중심 자기장의 크기 비와 방향 판단법을 설명하시오.', null, '각 고리의 자기장이 같은 방향으로 더해지므로 중심에서 B=μ₀NI/(2R)다. 따라서 1회와 3회의 크기 비는 1:3이다. 오른손 손가락을 전류 방향으로 감을 때 엄지가 중심 자기장 방향을 가리킨다.', '{}'::text[], array['감은 수 비례식', '크기 비 1:3', '오른손 법칙의 방향 설명'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 125, null, null, 1011),
  ('physics-written-u10-001', 'physics-ii', 'written', '10 전자기 유도와 상호유도', null, '20회 감은 코일의 각 고리를 지나는 안쪽 자기 선속이 0.1 s 동안 0.03 Wb 감소한다. 평균 유도 기전력의 크기와 유도 전류 방향을 앞에서 본 기준으로 설명하시오.', null, '|ε|=N|ΔΦ|/Δt=20×0.03/0.1=6 V다. 안쪽 선속의 감소를 방해하려면 코일은 안쪽 자기장을 만들어야 한다. 오른손 법칙에 따라 앞에서 본 유도 전류는 시계 방향이다.', '{}'::text[], array['기전력 6 V와 계산식', '감소를 방해하는 안쪽 자기장', '시계 방향'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 136, null, null, 1012),
  ('physics-written-u10-002', 'physics-ii', 'written', '10 전자기 유도와 상호유도', null, '이상적인 변압기의 N₁:N₂=1:4이며 1차 교류 전압은 10 V다. 2차 부하 전류가 0.5 A일 때 2차 전압, 1차 전류를 계산하시오.', null, 'V₂/V₁=N₂/N₁이므로 V₂=40 V다. 손실이 없어 V₁I₁=V₂I₂=20 W이므로 I₁=2 A다. 전압은 감은 수에 비례하지만 전류는 반비례한다.', '{}'::text[], array['2차 전압 40 V', '전력 보존식', '1차 전류 2 A'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 142, null, null, 1013),
  ('physics-written-u10-003', 'physics-ii', 'written', '10 전자기 유도와 상호유도', null, '두 코일의 위치와 감은 수를 유지한다. 1차 코일 전류가 변하는 시간을 절반으로 줄이고 전류 변화량은 같게 하면 2차 코일의 평균 유도 기전력은 어떻게 변하는지 설명하시오.', null, '두 코일의 배치가 같으므로 상호 인덕턴스 M은 일정하다. 2차 코일의 평균 유도 기전력 크기는 M|ΔI/Δt|다. 전류 변화량이 같고 변화 시간이 절반이면 전류 변화율은 2배이므로 기전력 크기도 2배다. 유도 전류가 흐를 수 있다면 그 방향은 자기 선속의 변화를 방해한다.', '{}'::text[], array['상호 인덕턴스 일정', '전류 변화율 2배', '기전력 크기 2배'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 139, null, null, 1014),
  ('physics-written-u11-001', 'physics-ii', 'written', '11 전자기파의 간섭과 회절', null, '동위상 이중 슬릿에서 λ=500 nm, L=2 m, d=0.5 mm다. 작은 각도 근사로 밝은 무늬 간격을 구하고, d를 2배로 할 때 변화를 설명하시오.', null, 'λ=5×10⁻⁷ m, d=5×10⁻⁴ m다. Δx=λL/d=2×10⁻³ m=2 mm다. d를 2배로 하고 λ와 L을 유지하면 무늬 간격은 1/2배인 1 mm가 된다.', '{}'::text[], array['SI 단위 변환', '간격 2 mm', 'd 2배일 때 1 mm'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 153, null, null, 1015),
  ('physics-written-u11-002', 'physics-ii', 'written', '11 전자기파의 간섭과 회절', null, '진폭이 같은 동위상 두 파동의 경로차가 λ인 점 A와 3λ/2인 점 B를 비교하여 간섭 종류와 합성 진폭을 설명하시오.', null, 'A는 경로차가 정수배 λ이므로 보강 간섭하며 합성 진폭은 각 진폭의 2배다. B는 경로차가 반정수배 λ이므로 상쇄 간섭하며 합성 진폭은 0이다. 위상과 진폭이 같다는 전제가 필요하다.', '{}'::text[], array['A 보강·진폭 2배', 'B 상쇄·진폭 0', '동위상·동일 진폭 조건'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 152, null, null, 1016),
  ('physics-written-u11-003', 'physics-ii', 'written', '11 전자기파의 간섭과 회절', null, '같은 파장으로 두 가까운 별을 관측할 때 망원경 구경을 크게 하면 구별하기 쉬워지는 까닭을 회절로 설명하시오.', null, '망원경 입구에서 빛이 회절하므로 점광원인 별의 상도 유한한 폭으로 퍼진다. 구경이 커지면 파장에 대한 구경의 비가 커져 회절 퍼짐이 줄어든다. 따라서 분해 가능한 최소 각도가 작아져 가까운 두 별을 구별하기 쉬워진다.', '{}'::text[], array['회절로 별의 상이 퍼짐', '큰 구경에서 퍼짐 감소', '최소 구분 각도 감소'], '', 'EBS 2025 수능특강 물리학Ⅱ · 개념 기반 새 서술형', 157, null, null, 1017)
on conflict (id) do nothing;
